// HPM package tools (issue #209 modularization).

private Map _fetchAppsListTree(String caller) {
    def responseText
    try {
        responseText = hubInternalGet("/hub2/appsList")
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to fetch installed apps for ${caller} [${e.class.simpleName}]: ${e.message ?: e.toString()}")
    }
    if (!responseText) {
        throw new IllegalArgumentException("Empty response from /hub2/appsList during ${caller} -- hub internal API may be unavailable")
    }
    try {
        return new groovy.json.JsonSlurper().parseText(responseText)
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to parse /hub2/appsList for ${caller}: ${e.message ?: e.toString()}")
    }
}

private String _hpmDiscoverAppId() {
    def parsed = _fetchAppsListTree("HPM discovery")
    // Walk the installed-app instance tree (apps[]) using a plain List as a BFS work queue.
    // Collects ALL matches unconditionally so duplicate HPM installs are surfaced as an error
    // rather than silently returning the first. BFS walks children[] at every node to handle
    // HPM nested under a parent app.
    def hpmMatches = []
    def workQueue = [] + (parsed?.apps ?: [])
    int qi = 0
    while (qi < workQueue.size()) {
        def node = workQueue[qi++]
        def d = node?.data ?: [:]
        if (d.type?.toString() == "Hubitat Package Manager") {
            if (d.id == null) throw new IllegalArgumentException("HPM entry found but has no id field -- cannot determine hpmAppId; pass hpmAppId explicitly")
            hpmMatches << d.id.toString()
        }
        for (it in (node?.children ?: [])) { workQueue << it }
    }
    if (hpmMatches.isEmpty()) {
        throw new IllegalArgumentException("HPM not found in installed apps -- Hubitat Package Manager does not appear to be installed")
    }
    if (hpmMatches.size() > 1) {
        def cap = 10
        def shown = hpmMatches.take(cap).join(', ')
        def extra = hpmMatches.size() > cap ? " and ${hpmMatches.size() - cap} more (total ${hpmMatches.size()})" : ""
        throw new IllegalArgumentException("Multiple HPM instances found: [${shown}]${extra} -- pass hpmAppId explicitly to select one")
    }
    return hpmMatches[0]
}

private void _hpmAssertAppIsHpm(String explicitAppId) {
    def parsed = _fetchAppsListTree("hpmAppId validation")
    // Walk the installed-app instance tree looking for the entry with the given id.
    // Early-exit on match: children[] are only enqueued when the current node does NOT match,
    // avoiding unnecessary BFS expansion after the target is found.
    def workQueue = [] + (parsed?.apps ?: [])
    int qi = 0
    def foundEntry = null
    while (qi < workQueue.size() && foundEntry == null) {
        def node = workQueue[qi++]
        def d = node?.data ?: [:]
        if (d.id?.toString() == explicitAppId) {
            foundEntry = d
        } else {
            for (it in (node?.children ?: [])) { workQueue << it }
        }
    }
    if (foundEntry == null) {
        throw new IllegalArgumentException("hpmAppId ${explicitAppId} not found in installed apps -- verify the ID or omit hpmAppId to use auto-discovery")
    }
    def actualType = foundEntry.type?.toString() ?: "unknown"
    if (actualType != "Hubitat Package Manager") {
        throw new IllegalArgumentException("hpmAppId ${explicitAppId} is not Hubitat Package Manager (actual type: ${actualType}) -- verify the ID or omit hpmAppId to use auto-discovery")
    }
}

private Map _hpmFetchManifests(String hpmAppId) {
    def responseText
    try {
        responseText = hubInternalGet("/installedapp/statusJson/${hpmAppId}")
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to fetch HPM statusJson [${e.class.simpleName}]: ${e.message ?: e.toString()}")
    }
    if (!responseText) {
        throw new IllegalArgumentException("Empty response from /installedapp/statusJson/${hpmAppId} -- app may not exist or hub internal API is unavailable")
    }
    def outer
    try {
        outer = new groovy.json.JsonSlurper().parseText(responseText)
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to parse HPM statusJson [${e.class.simpleName}]: ${e.message ?: e.toString()}")
    }
    if (!(outer instanceof Map)) {
        // actualTypeName diagnostic labels: "List", "null", or "non-object" (any non-Map, non-List, non-null scalar).
        def actualTypeName = (outer instanceof List) ? "List" : (outer == null ? "null" : "non-object")
        throw new IllegalArgumentException("Unexpected HPM statusJson shape: expected a JSON object, got ${actualTypeName}")
    }
    // Find the 'manifests' entry in appState[].
    // appState[].value shape varies by firmware: live hubs typically return the value already
    // as a Map (JsonSlurper recursively parsed the inner JSON). Older firmware or large payloads
    // may leave it as a JSON-encoded String. Handle both: if it's already a Map, use it directly.
    def appState = outer.appState ?: []
    def manifestsEntry = appState.find { it?.name?.toString() == "manifests" }
    if (manifestsEntry == null) {
        // HPM installed but no packages tracked yet.
        return [:]
    }
    def rawValue = manifestsEntry.value
    if (rawValue == null) {
        return [:]
    }
    def manifests
    if (rawValue instanceof Map) {
        // JsonSlurper already parsed the inner JSON string into a Map.
        manifests = rawValue
    } else {
        def rawStr = rawValue.toString().trim()
        if (rawStr.isEmpty()) return [:]
        try {
            manifests = new groovy.json.JsonSlurper().parseText(rawStr)
        } catch (Exception e) {
            throw new IllegalArgumentException("Failed to parse HPM manifests value [${e.class.simpleName}]: ${e.message ?: e.toString()}")
        }
    }
    if (!(manifests instanceof Map)) {
        def actualTypeName = (manifests instanceof List) ? "List" : (manifests == null ? "null" : "non-object")
        throw new IllegalArgumentException("Unexpected HPM manifests shape: expected a JSON object keyed by manifest URL, got ${actualTypeName}")
    }
    return manifests
}

def toolListHpmPackages(args) {

    def hpmAppId
    if (args?.hpmAppId != null && args.hpmAppId.toString().trim() != "") {
        hpmAppId = args.hpmAppId.toString().trim()
        if (!hpmAppId.isInteger()) {
            throw new IllegalArgumentException("hpmAppId must be numeric: ${hpmAppId}")
        }
        _hpmAssertAppIsHpm(hpmAppId)
    } else {
        hpmAppId = _hpmDiscoverAppId()
    }

    mcpLog("info", "hpm", "hub_list_hpm_packages hpmAppId=${hpmAppId}")

    def manifests
    try {
        manifests = _hpmFetchManifests(hpmAppId)
    } catch (IllegalArgumentException e) {
        return [success: false, error: e.message, hpmAppId: hpmAppId]
    }

    def skippedMalformed = []
    def packages = manifests.collect { manifestUrl, manifest ->
        if (!(manifest instanceof Map)) {
            mcpLog("warn", "hpm", "hub_list_hpm_packages: skipping malformed manifest entry for URL ${manifestUrl} -- value is not a Map")
            skippedMalformed << manifestUrl?.toString()
            return null
        }
        int skippedAppCount = 0
        int skippedDriverCount = 0
        int skippedFileCount = 0
        def apps = (manifest.apps ?: []).collect { a ->
            if (!(a instanceof Map)) { skippedAppCount++; mcpLog("warn", "hpm", "hub_list_hpm_packages: non-Map app component in '${manifest.packageName}' (value: ${a?.toString()?.take(60) ?: 'null'}) -- skipped"); return null }
            def heId = a.heID
            def heIdStr = null
            def heIdWarning = null
            if (heId instanceof String && heId.trim() == "") {
                // Empty/whitespace-only String heID normalized to null -- surfaces the data quality
                // issue without breaking the consumer (matches drift treatment).
                heIdWarning = "empty heID string '${heId}' normalized to null"
                heId = null
                mcpLog("warn", "hpm", "hub_list_hpm_packages: app '${a.name}' in '${manifest.packageName}' heID is empty/whitespace -- normalized to null")
            }
            // Whitespace-padded String heID (e.g. " 142 ") is normalized to the trimmed value so
            // that heID surfaces correctly to the consumer (matches get_hpm_drift treatment).
            if (heId instanceof String && heId.trim() != heId) {
                def trimmed = heId.trim()
                heIdWarning = "whitespace-padded heID '${heId}' normalized to '${trimmed}'"
                mcpLog("warn", "hpm", "hub_list_hpm_packages: app '${a.name}' in '${manifest.packageName}' heID has surrounding whitespace -- normalized to '${trimmed}'")
                heId = trimmed
            }
            if (heId != null) {
                if (heId instanceof Number || heId instanceof String) {
                    heIdStr = heId.toString()
                } else {
                    heIdWarning = "non-scalar heID (not Number or String) -- heID cleared"
                    mcpLog("warn", "hpm", "hub_list_hpm_packages: app '${a.name}' in '${manifest.packageName}' heID is not a Number or String -- skipping heID")
                }
            }
            def entry = [
                id      : a.id?.toString(),
                name    : a.name?.toString(),
                required: a.required == true,
                version : a.version?.toString(),
                heID    : heIdStr
            ]
            if (heIdWarning) entry._warning = heIdWarning
            entry
        }.findAll { it != null }

        def drivers = (manifest.drivers ?: []).collect { d ->
            if (!(d instanceof Map)) { skippedDriverCount++; mcpLog("warn", "hpm", "hub_list_hpm_packages: non-Map driver component in '${manifest.packageName}' (value: ${d?.toString()?.take(60) ?: 'null'}) -- skipped"); return null }
            def heId = d.heID
            def heIdStr = null
            def heIdWarning = null
            if (heId instanceof String && heId.trim() == "") {
                // Empty/whitespace-only String heID normalized to null -- surfaces the data quality
                // issue without breaking the consumer (matches drift treatment).
                heIdWarning = "empty heID string '${heId}' normalized to null"
                heId = null
                mcpLog("warn", "hpm", "hub_list_hpm_packages: driver '${d.name}' in '${manifest.packageName}' heID is empty/whitespace -- normalized to null")
            }
            // Whitespace-padded String heID normalized to trimmed value (matches app treatment above).
            if (heId instanceof String && heId.trim() != heId) {
                def trimmed = heId.trim()
                heIdWarning = "whitespace-padded heID '${heId}' normalized to '${trimmed}'"
                mcpLog("warn", "hpm", "hub_list_hpm_packages: driver '${d.name}' in '${manifest.packageName}' heID has surrounding whitespace -- normalized to '${trimmed}'")
                heId = trimmed
            }
            if (heId != null) {
                if (heId instanceof Number || heId instanceof String) {
                    heIdStr = heId.toString()
                } else {
                    heIdWarning = "non-scalar heID (not Number or String) -- heID cleared"
                    mcpLog("warn", "hpm", "hub_list_hpm_packages: driver '${d.name}' in '${manifest.packageName}' heID is not a Number or String -- skipping heID")
                }
            }
            def entry = [
                id      : d.id?.toString(),
                name    : d.name?.toString(),
                required: d.required == true,
                version : d.version?.toString(),
                heID    : heIdStr
            ]
            if (heIdWarning) entry._warning = heIdWarning
            entry
        }.findAll { it != null }

        def files = (manifest.files ?: []).collect { f ->
            if (!(f instanceof Map)) { skippedFileCount++; mcpLog("warn", "hpm", "hub_list_hpm_packages: non-Map file component in '${manifest.packageName}' (value: ${f?.toString()?.take(60) ?: 'null'}) -- skipped"); return null }
            [
                id  : f.id?.toString(),
                name: f.name?.toString()
            ]
        }.findAll { it != null }

        def pkg = [
            manifestUrl : manifestUrl?.toString(),
            packageName : manifest.packageName?.toString(),
            version     : manifest.version?.toString(),
            beta        : manifest.beta == true,
            author      : manifest.author?.toString(),
            apps        : apps,
            drivers     : drivers,
            files       : files
        ]
        if (skippedAppCount > 0)    pkg.skippedAppCount    = skippedAppCount
        if (skippedDriverCount > 0) pkg.skippedDriverCount = skippedDriverCount
        if (skippedFileCount > 0)   pkg.skippedFileCount   = skippedFileCount
        pkg
    }.findAll { it != null }

    def cursor = args?.cursor
    def paged = _paginateList(packages, cursor, 25, "hub_list_hpm_packages")
    def result = [
        success   : true,
        hpmAppId  : hpmAppId,
        count     : paged.page.size(),
        packages  : paged.page
    ]
    if (cursor != null) {
        result.total = packages.size()
        if (paged.nextCursor != null) result.nextCursor = paged.nextCursor
    }
    if (skippedMalformed) result.skippedMalformed = skippedMalformed
    return result
}

def toolGetHpmDrift(args) {

    def hpmAppId
    if (args?.hpmAppId != null && args.hpmAppId.toString().trim() != "") {
        hpmAppId = args.hpmAppId.toString().trim()
        if (!hpmAppId.isInteger()) {
            throw new IllegalArgumentException("hpmAppId must be numeric: ${hpmAppId}")
        }
        _hpmAssertAppIsHpm(hpmAppId)
    } else {
        hpmAppId = _hpmDiscoverAppId()
    }

    def packageFilterRaw = args?.packageFilter?.toString()?.trim()
    def packageFilter = packageFilterRaw ?: null

    mcpLog("info", "hpm", "get_hpm_drift hpmAppId=${hpmAppId} packageFilter=${packageFilter ?: 'none'}")

    def manifests
    try {
        manifests = _hpmFetchManifests(hpmAppId)
    } catch (IllegalArgumentException e) {
        return [success: false, error: e.message, hpmAppId: hpmAppId]
    }

    // Build the set of Apps Code definition IDs for orphan-app detection.
    // /hub2/userAppTypes is the dedicated Apps Code registry endpoint -- each entry
    // represents a code definition (whether or not it has any running instances).
    // This is distinct from the userAppTypes[] array embedded in /hub2/appsList,
    // which represents installed instances. Child-app templates (e.g. "MCP Rule")
    // have code definitions here but zero installed instances in the apps[] tree,
    // so orphan detection MUST use this endpoint to avoid false positives on
    // HPM-managed child-app-template packages.
    def installedAppCodeIds = [] as Set
    def orphanDetection = [enabled: true]
    try {
        def userAppTypesText = hubInternalGet("/hub2/userAppTypes")
        if (!userAppTypesText) {
            orphanDetection = [enabled: false, reason: "Empty response from /hub2/userAppTypes -- orphan-app signals were not evaluated this call"]
            mcpLog("warn", "hpm", "get_hpm_drift: empty /hub2/userAppTypes response -- orphan detection disabled")
        } else {
            def userAppTypesParsed = new groovy.json.JsonSlurper().parseText(userAppTypesText)
            if (!(userAppTypesParsed instanceof List)) {
                def actualTypeName = _typeName(userAppTypesParsed)
                def rawPreview = userAppTypesParsed?.toString() ?: ""
                def actualPreview = rawPreview.length() > 200 ? rawPreview.take(200) + " (truncated)" : rawPreview
                orphanDetection = [enabled: false, reason: "Unexpected /hub2/userAppTypes response shape (expected JSON array, got ${actualTypeName}: ${actualPreview}) -- orphan-app signals were not evaluated this call"]
                mcpLog("warn", "hpm", "get_hpm_drift: /hub2/userAppTypes returned non-List shape (${actualTypeName}) -- orphan detection disabled")
            } else {
                for (t in userAppTypesParsed) {
                    def typeId = t?.id?.toString()
                    if (typeId) installedAppCodeIds << typeId
                }
            }
        }
    } catch (Exception e) {
        orphanDetection = [enabled: false, reason: "Failed to fetch /hub2/userAppTypes [${e.class.simpleName}]: ${e.message ?: e.toString()} -- orphan-app signals were not evaluated this call"]
        mcpLog("warn", "hpm", "get_hpm_drift: could not fetch /hub2/userAppTypes for orphan-app detection: ${e.message ?: e.toString()}")
    }

    // Build the set of Drivers Code definition IDs for orphan-driver detection.
    // /hub2/userDeviceTypes is the Drivers Code registry endpoint -- each entry
    // represents a driver code definition (whether or not any devices use it).
    // Note: the endpoint name follows the hub's naming convention (userDeviceTypes, not
    // userDriverTypes); this is the same endpoint used by hub_list_drivers.
    def installedDriverCodeIds = [] as Set
    def orphanDriverDetection = [enabled: true]
    try {
        def userDeviceTypesText = hubInternalGet("/hub2/userDeviceTypes")
        if (!userDeviceTypesText) {
            orphanDriverDetection = [enabled: false, reason: "Empty response from /hub2/userDeviceTypes -- orphan-driver signals were not evaluated this call"]
            mcpLog("warn", "hpm", "get_hpm_drift: empty /hub2/userDeviceTypes response -- orphan driver detection disabled")
        } else {
            def userDeviceTypesParsed = new groovy.json.JsonSlurper().parseText(userDeviceTypesText)
            if (!(userDeviceTypesParsed instanceof List)) {
                def actualTypeName = _typeName(userDeviceTypesParsed)
                def rawPreview = userDeviceTypesParsed?.toString() ?: ""
                def actualPreview = rawPreview.length() > 200 ? rawPreview.take(200) + " (truncated)" : rawPreview
                orphanDriverDetection = [enabled: false, reason: "Unexpected /hub2/userDeviceTypes response shape (expected JSON array, got ${actualTypeName}: ${actualPreview}) -- orphan-driver signals were not evaluated this call"]
                mcpLog("warn", "hpm", "get_hpm_drift: /hub2/userDeviceTypes returned non-List shape (${actualTypeName}) -- orphan driver detection disabled")
            } else {
                for (t in userDeviceTypesParsed) {
                    def typeId = t?.id?.toString()
                    if (typeId) installedDriverCodeIds << typeId
                }
            }
        }
    } catch (Exception e) {
        orphanDriverDetection = [enabled: false, reason: "Failed to fetch /hub2/userDeviceTypes [${e.class.simpleName}]: ${e.message ?: e.toString()} -- orphan-driver signals were not evaluated this call"]
        mcpLog("warn", "hpm", "get_hpm_drift: could not fetch /hub2/userDeviceTypes for orphan-driver detection: ${e.message ?: e.toString()}")
    }

    // Apply optional package filter before drift analysis.
    def filteredManifests = packageFilter
        ? manifests.findAll { url, m -> m instanceof Map && m.packageName?.toString()?.toLowerCase()?.contains(packageFilter.toLowerCase()) }
        : manifests

    def driftEntries = []
    def driftSkippedMalformed = []
    def driftDataQualityWarnings = []
    int totalSignals = 0

    for (Map.Entry kv in filteredManifests) {
        def manifestUrl = kv.key
        def manifest = kv.value
        if (!(manifest instanceof Map)) {
            mcpLog("warn", "hpm", "get_hpm_drift: skipping malformed manifest entry for URL ${manifestUrl} -- value is not a Map")
            driftSkippedMalformed << manifestUrl?.toString()
            continue
        }
        def signals = []
        // Data-quality warnings are collected separately and do NOT roll up into totalDriftSignals.
        // This keeps the contract clean: totalDriftSignals counts actionable drift (missing-required,
        // orphan-app, orphan-driver) and does not inflate for data-quality issues in the manifest.
        def dataQualityWarnings = []
        int skippedAppCount = 0
        int skippedDriverCount = 0

        // missing-required: required=true AND heID is null/absent
        // orphan-app: heID present but not in Apps Code registry (/hub2/userAppTypes endpoint)
        // Both checks share the per-component heID resolution loop below.
        for (a in (manifest.apps ?: [])) {
            if (!(a instanceof Map)) {
                skippedAppCount++
                dataQualityWarnings << [
                    type         : "skipped-malformed-component",
                    componentType: "app",
                    _warning     : "app component entry is not a Map -- skipped"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: non-Map app component in '${manifest.packageName}' (value: ${a?.toString()?.take(60) ?: 'null'}) -- skipped")
                continue
            }
            def heId = a.heID
            // Normalize empty/whitespace-only String heID to null and surface as data-quality warning
            // so the consumer knows the manifest has a blank heID (matches hub_list_hpm_packages treatment).
            if (heId instanceof String && heId.trim() == "") {
                dataQualityWarnings << [
                    type         : "empty-heid",
                    componentType: "app",
                    componentName: a.name?.toString(),
                    componentId  : a.id?.toString(),
                    _warning     : "empty heID string '${heId}' normalized to null"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: app '${a.name}' in '${manifest.packageName}' heID is empty/whitespace -- normalized to null")
                heId = null
            }
            // Whitespace-padded String heID (e.g. " 142 ") would match nothing in the registry
            // via verbatim .toString() lookup. Surface as a data-quality warning and normalize
            // to the trimmed value so the lookup proceeds correctly. The component is KEPT --
            // drift checks continue against the trimmed heID.
            if (heId instanceof String && heId.trim() != heId) {
                def trimmed = heId.trim()
                dataQualityWarnings << [
                    type         : "heid-whitespace-normalized",
                    componentType: "app",
                    componentName: a.name?.toString(),
                    componentId  : a.id?.toString(),
                    _warning     : "whitespace-padded heID '${heId}' normalized to '${trimmed}'"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: app '${a.name}' in '${manifest.packageName}' heID has surrounding whitespace ('${heId}') -- normalized to '${trimmed}'")
                heId = trimmed
            }
            // Type-validate heID at the boundary: Number and String are the only valid scalar types.
            // Non-scalar heID (List, Map, Boolean) cannot be matched against Apps Code IDs and
            // would produce guaranteed false-positive orphan signals via .toString() coercion.
            // The component is DROPPED -- drift checks do not run for this entry.
            if (heId != null && !(heId instanceof Number) && !(heId instanceof String)) {
                mcpLog("warn", "hpm", "get_hpm_drift: app '${a.name}' in '${manifest.packageName}' heID is not a Number or String (value: ${heId?.toString()?.take(60) ?: 'null'}) -- skipping component")
                dataQualityWarnings << [
                    type         : "heid-non-scalar-dropped",
                    componentType: "app",
                    componentName: a.name?.toString(),
                    componentId  : a.id?.toString(),
                    _warning     : "non-scalar heID (not Number or String) -- component skipped"
                ]
                continue
            }
            def heIdNull = heId == null
            // signals[] field-shape convention: orphan-* entries carry `heID` (the orphaned id);
            // missing-required entries omit `heID` because the value is null by definition of the signal.
            if (a.required == true && heIdNull) {
                signals << [
                    type         : "missing-required",
                    componentType: "app",
                    componentName: a.name?.toString(),
                    componentId  : a.id?.toString(),
                    note         : "Component is required but heID is null/absent -- install never completed or component was removed."
                ]
            }
            if (!heIdNull && orphanDetection.enabled) {
                def heIdStr = heId.toString()
                if (!installedAppCodeIds.contains(heIdStr)) {
                    signals << [
                        type         : "orphan-app",
                        componentType: "app",
                        componentName: a.name?.toString(),
                        componentId  : a.id?.toString(),
                        heID         : heIdStr,
                        note         : "HPM tracks heID ${heIdStr} but the app code definition is no longer in Apps Code -- likely deleted via Apps Code without using HPM Uninstall."
                    ]
                }
            }
        }

        // missing-required: required=true AND heID is null/absent (drivers)
        // orphan-driver: heID present but not in Drivers Code registry (/hub2/userDeviceTypes endpoint)
        // signals[] field-shape convention identical to apps loop above: orphan-* carries heID, missing-required omits it.
        for (d in (manifest.drivers ?: [])) {
            if (!(d instanceof Map)) {
                skippedDriverCount++
                dataQualityWarnings << [
                    type         : "skipped-malformed-component",
                    componentType: "driver",
                    _warning     : "driver component entry is not a Map -- skipped"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: non-Map driver component in '${manifest.packageName}' (value: ${d?.toString()?.take(60) ?: 'null'}) -- skipped")
                continue
            }
            def heId = d.heID
            // Normalize empty/whitespace-only String heID to null and surface as data-quality warning.
            if (heId instanceof String && heId.trim() == "") {
                dataQualityWarnings << [
                    type         : "empty-heid",
                    componentType: "driver",
                    componentName: d.name?.toString(),
                    componentId  : d.id?.toString(),
                    _warning     : "empty heID string '${heId}' normalized to null"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: driver '${d.name}' in '${manifest.packageName}' heID is empty/whitespace -- normalized to null")
                heId = null
            }
            // Whitespace-padded String heID (e.g. " 89 ") would produce a guaranteed false-positive
            // orphan-driver signal. Surface as a data-quality warning and normalize to trimmed value.
            // The component is KEPT -- drift checks continue against the trimmed heID.
            if (heId instanceof String && heId.trim() != heId) {
                def trimmed = heId.trim()
                dataQualityWarnings << [
                    type         : "heid-whitespace-normalized",
                    componentType: "driver",
                    componentName: d.name?.toString(),
                    componentId  : d.id?.toString(),
                    _warning     : "whitespace-padded heID '${heId}' normalized to '${trimmed}'"
                ]
                mcpLog("warn", "hpm", "get_hpm_drift: driver '${d.name}' in '${manifest.packageName}' heID has surrounding whitespace ('${heId}') -- normalized to '${trimmed}'")
                heId = trimmed
            }
            // Non-scalar heID cannot be matched against Drivers Code IDs. The component is DROPPED
            // -- drift checks do not run for this entry.
            if (heId != null && !(heId instanceof Number) && !(heId instanceof String)) {
                mcpLog("warn", "hpm", "get_hpm_drift: driver '${d.name}' in '${manifest.packageName}' heID is not a Number or String (value: ${heId?.toString()?.take(60) ?: 'null'}) -- skipping component")
                dataQualityWarnings << [
                    type         : "heid-non-scalar-dropped",
                    componentType: "driver",
                    componentName: d.name?.toString(),
                    componentId  : d.id?.toString(),
                    _warning     : "non-scalar heID (not Number or String) -- component skipped"
                ]
                continue
            }
            def heIdNull = heId == null
            if (d.required == true && heIdNull) {
                signals << [
                    type         : "missing-required",
                    componentType: "driver",
                    componentName: d.name?.toString(),
                    componentId  : d.id?.toString(),
                    note         : "Component is required but heID is null/absent -- install never completed or component was removed."
                ]
            }
            if (!heIdNull && orphanDriverDetection.enabled) {
                def heIdStr = heId.toString()
                if (!installedDriverCodeIds.contains(heIdStr)) {
                    signals << [
                        type         : "orphan-driver",
                        componentType: "driver",
                        componentName: d.name?.toString(),
                        componentId  : d.id?.toString(),
                        heID         : heIdStr,
                        note         : "HPM tracks heID ${heIdStr} but the driver code definition is no longer in Drivers Code -- likely deleted via Drivers Code without using HPM Uninstall."
                    ]
                }
            }
        }

        if (signals || dataQualityWarnings) {
            def entry = [
                manifestUrl : manifestUrl?.toString(),
                packageName : manifest.packageName?.toString(),
                version     : manifest.version?.toString(),
                signals     : signals
            ]
            if (dataQualityWarnings) entry.dataQualityWarnings = dataQualityWarnings
            if (skippedAppCount > 0)    entry.skippedAppCount    = skippedAppCount
            if (skippedDriverCount > 0) entry.skippedDriverCount = skippedDriverCount
            driftEntries << entry
            totalSignals += signals.size()
            if (dataQualityWarnings) driftDataQualityWarnings.addAll(dataQualityWarnings)
        }
    }

    int checked = filteredManifests.size()
    // Count only packages with actionable drift signals (not data-quality-only entries).
    // A package with only dataQualityWarnings contributes to driftEntries[] for visibility
    // but must not appear in the summary as "showing drift" when totalDriftSignals is 0.
    // Note: drift[].length may exceed packagesWithActionableDrift when data-quality-only
    // packages are present -- those entries are included for visibility but not in the count.
    int packagesWithActionableDrift = driftEntries.count { it.signals }
    def summary = packagesWithActionableDrift == 0
        ? "No drift detected across ${checked} tracked package${checked == 1 ? '' : 's'}."
        : "${packagesWithActionableDrift} of ${checked} tracked package${checked == 1 ? '' : 's'} ${packagesWithActionableDrift == 1 ? 'shows' : 'show'} drift (${totalSignals} total signal${totalSignals == 1 ? '' : 's'})."
    // When one or both detection systems were disabled this call, the summary could mislead a
    // consumer that surfaces only the summary string. Append a partial-detection suffix so the
    // human-readable summary matches the structured orphanDetection / orphanDriverDetection fields.
    def partialSuffixParts = []
    if (!orphanDetection.enabled)       partialSuffixParts << "orphanDetection"
    if (!orphanDriverDetection.enabled) partialSuffixParts << "orphanDriverDetection"
    if (partialSuffixParts) {
        def reasonNoun = partialSuffixParts.size() == 1 ? 'reason' : 'reasons'
        summary += " (partial: ${partialSuffixParts.join('/')} disabled this call -- see ${partialSuffixParts.join('/')} ${reasonNoun})"
    }

    def result = [
        success                     : true,
        hpmAppId                    : hpmAppId,
        packagesChecked             : checked,
        packagesWithActionableDrift : packagesWithActionableDrift,
        drift                       : driftEntries,
        totalDriftSignals           : totalSignals,
        summary                     : summary,
        orphanDetection             : orphanDetection,
        orphanDriverDetection       : orphanDriverDetection,
        limitations                 : "Drift detection is heID-presence-only. Per-component source drift (e.g., post-hub_update_app edits) is NOT detected -- HPM stores no source hashes."
    ]
    if (driftSkippedMalformed) result.skippedMalformed = driftSkippedMalformed
    if (driftDataQualityWarnings) result.dataQualityWarnings = driftDataQualityWarnings
    // When a packageFilter was supplied but matched nothing, surface that explicitly so
    // the caller can distinguish "clean hub" from "typo in filter".
    if (packageFilter && checked == 0) {
        result.filterMatchedZero = true
        result.availablePackages = manifests.findAll { url, m -> m instanceof Map }
            .collect { url, m -> m.packageName?.toString() }
            .findAll { it }
    }
    return result
}

// HPM-packages dispatch helper (same case-block-extraction reason as above):
// optionally attaches per-component drift signals when includeDrift=true.
def toolListHpmPackagesWithDrift(args) {
    def listResult = toolListHpmPackages(args)
    if (args.includeDrift == true && listResult instanceof Map) {
        listResult = listResult + [drift: toolGetHpmDrift(args)]
    }
    return listResult
}

def _getAllToolDefinitions_partHpm() {
    return [
        // HPM Package State Tools
        [
            name: "hub_list_hpm_packages",
            description: """List all packages tracked by Hubitat Package Manager (HPM): name, version, beta flag, author, and component inventory (apps/drivers/files) as HPM recorded at install/update time. Requires Read master; HPM must be installed.[[FLAT_TRIM]]
Set includeDrift=true to ALSO cross-reference tracked state against what is actually installed and attach a `drift` block (missing-required / orphan signals). See `hub_get_tool_guide(section='builtin_app_tools_apps')` for the full drift-signal taxonomy, response-field reference, and caveats.[[/FLAT_TRIM]]""",
            inputSchema: [
                type: "object",
                properties: [
                    hpmAppId: [type: "string", description: "HPM's installed-app ID (decimal). Auto-discovered if omitted.[[FLAT_TRIM]] Scans installed apps for type='Hubitat Package Manager'; pass explicitly to skip that discovery call.[[/FLAT_TRIM]]"],
                    includeDrift: [type: "boolean", description: "Also attach a drift cross-reference under a `drift` key.[[FLAT_TRIM]] Signal types: missing-required/orphan-app/orphan-driver.[[/FLAT_TRIM]] Default false; adds 1-2 hub calls.", default: false],
                    packageFilter: [type: "string", description: "Drift mode only (includeDrift=true): case-insensitive substring filter on packageName."],
                    cursor: [type: "string", description: "Opt-in pagination cursor for the packages list. Omit for unbounded; pass \"\" for the first page, iterate nextCursor.[[FLAT_TRIM]] Page size 25 -- HPM entries carry full app/driver/file inventories so each entry can be large.[[/FLAT_TRIM]]"]
                ]
            ]
        ],
    ]
}

def _readOnlyToolNames_partHpm() {
    // Read-only classification membership for this library's tools, contributed to the
    // app's getReadOnlyToolNames() aggregator (issue #209: per-tool metadata lives with
    // the tool). A tool absent from every part list is write+destructive by default.
    return [
        // HPM (read)
        "hub_list_hpm_packages"
    ]
}

def _toolDisplayMeta_partHpm() {
    // Human-facing title/summary per tool (MCP annotations.title + the Advanced per-tool
    // overrides menu) -- merged into the app's getToolDisplayMeta() aggregator (issue #209).
    return [
        hub_list_hpm_packages: [title: "List HPM Packages", summary: "List packages tracked by Hubitat Package Manager, optionally with drift detection."]
    ]
}


// MCP self-admin tools (issue #209 modularization): settings updates + the
// Developer Mode package deploy.

def toolUpdateMcpSettings(args) {
    // IllegalArgumentException (not IllegalStateException) so the dispatcher routes this
    // through handleToolsCall's IllegalArgumentException branch (an isError validation result) — same exception
    // type the other gates throw (requireDestructiveConfirm, the central master gate).
    // Toggle-off is a config refusal, not an unexpected runtime error worth a stack trace.
    if (!settings.enableDeveloperMode) {
        throw new IllegalArgumentException("Developer Mode tools are disabled. Enable 'Developer Mode Tools' in MCP rule app settings to use hub_update_mcp_settings.")
    }
    requireDestructiveConfirm(args.confirm)

    if (!args.settings || !(args.settings instanceof Map) || args.settings.isEmpty()) {
        throw new IllegalArgumentException("settings must be a non-empty map of {settingName: newValue}")
    }

    // Allowlist of SCALAR settings that can be modified via this tool, with their Hubitat input
    // type (matches the input "<key>", "<type>", ... declarations in the mainPage section).
    // useGateways is allowlisted: it only reshapes tools/list
    // (gateway vs flat) — same class as
    // enableCustomRuleEngine, no write-path or lockout risk; clients must reconnect
    // afterward to pick up the new tool surface.
    // enableMandatoryBPS (issue #299) is allowlisted as an ESCAPE HATCH: hub_update_mcp_settings is
    // itself exempt from the best-practice gate, so letting the AI self-disable the (default-ON) gate
    // here is the documented un-lock path, not a footgun. (The reactive hint has no toggle -- always on.)
    // bypassDeviceAllowlist is allowlisted: it is a plain bool preference whose EFFECT is INDEPENDENT
    // of Developer Mode (this tool is dev-mode-gated, but once the flag is ON the bypass works in
    // normal operation). WARNING: when ON it makes the per-device tools (hub_get_device,
    // hub_get_device_attribute, hub_call_device_command, hub_update_device, hub_list_device_events)
    // ignore the device allowlist (settings.selectedDevices) and reach ANY device on the hub by id;
    // default OFF. Native inventory, health, dependents, swap and replacement use the same access policy.
    // selectedDevices is ALSO allowed but is NOT in this scalar map: it is the MCP device-access
    // scope (a capability.* multi-select), so it routes to _validateMcpDeviceScope (atomic id
    // validation + lockout guard + the capability.* List write) rather than the scalar coerce path.
    // enableLocalAccess / enableCloudAccess (issue #453) are allowlisted with a lockout guard below:
    // a call may switch off only the transport it did NOT arrive on, so it can never cut itself off.
    // Excluded:
    //   enableWrite          — would footgun: could disable own write path mid-session
    //   enableDeveloperMode  — lockout protection (must remain UI-only to disable)
    //   disabled_tools / disabled_gateways — could self-disable this tool; UI-only (Advanced page)
    def allowedSettings = [
        "mcpLogLevel":            "enum",
        "debugLogging":           "bool",
        "maxCapturedStates":      "number",
        "loopGuardMax":           "number",
        "loopGuardWindowSec":     "number",
        "enableRead":             "bool",
        "enableCustomRuleEngine": "bool",
        "useGateways":            "bool",
        "enableMandatoryBPS":     "bool",
        "bypassDeviceAllowlist":  "bool",
        "maxConcurrentWrites":    "number",
        "backupEveryRuleWrite":   "bool",
        "enableLocalAccess":      "bool",
        "enableCloudAccess":      "bool",
        "redactAccessTokens":     "bool"
    ]
    // Allowed keys for the not-allowed error message = scalar allowlist + the special selectedDevices key.
    def allowedKeyNames = ((allowedSettings.keySet() + ["selectedDevices"]) as List).sort()

    // Validate, coerce, and stage each update. Validation is fully atomic — every key
    // and every value is checked BEFORE any app.updateSetting() fires, so a single bad
    // entry in a multi-key batch can't leave the hub in a half-applied state. This
    // includes per-key sub-validation that would otherwise only fire during apply
    // (e.g. mcpLogLevel against getLogLevels()).
    //
    // Type coercion is also mandatory: a JSON-RPC client (e.g. a curl-based CI script)
    // may send "true"/"false" or "50" as strings instead of native bool/number. Without
    // coercion, app.updateSetting(key, [type:'bool', value:'false']) writes the string
    // "false", which is truthy in Groovy — silently flipping the toggle to enabled
    // when the caller meant disabled.
    def updates = [:]
    boolean hasDeviceScope = false
    def deviceScopeRaw = null
    for (Map.Entry entry in args.settings) {
        def key = entry.key
        def value = entry.value
        def keyStr = key.toString()
        if (keyStr == "selectedDevices") {
            // Special-cased BECAUSE the device-access scope is not a scalar setting: it is a
            // capability.* multi-select whose value must be written as a List
            // (app.updateSetting("selectedDevices", [type:"capability.*", value:<List>])), which
            // coerceSettingValue cannot produce, and it needs atomic id validation against the hub
            // plus a lockout guard that the scalar keys have no analogue for. So defer its full
            // validation to _validateMcpDeviceScope -- but capture it here so the scalar loop skips it.
            hasDeviceScope = true
            deviceScopeRaw = value
            continue  // continue the each-closure
        }
        if (!allowedSettings.containsKey(keyStr)) {
            throw new IllegalArgumentException("Setting '${keyStr}' is not allowed for self-modification via hub_update_mcp_settings. Allowed: ${allowedKeyNames.join(', ')}")
        }
        def coerced = coerceSettingValue(keyStr, value, allowedSettings.get(keyStr))
        // Per-key sub-validation that the apply step would otherwise discover too late.
        // mcpLogLevel must be one of the configured log levels — if 'blarg' slipped through
        // the enum coerce and only failed inside toolSetLogLevel during apply, any prior
        // app.updateSetting() calls in the same batch would have already landed.
        if (keyStr == "mcpLogLevel" && !getLogLevels().contains(coerced)) {
            throw new IllegalArgumentException("Setting 'mcpLogLevel' must be one of ${getLogLevels()}, got: ${coerced}")
        }
        if (keyStr == "maxConcurrentWrites") {
            BigDecimal numeric = coerced as BigDecimal
            if (numeric < 0 || numeric > 100 || numeric.remainder(BigDecimal.ONE) != BigDecimal.ZERO) {
                throw new IllegalArgumentException("Setting 'maxConcurrentWrites' must be an integer between 0 and 100 (0 disables the cap), got: ${coerced}")
            }
            coerced = numeric.intValue()
        }
        String ownTransportKey = _isCloudRequest() ? "enableCloudAccess" : "enableLocalAccess"
        if (keyStr == ownTransportKey && coerced == false) {
            throw new IllegalArgumentException("Refusing to set '${keyStr}' to false over the connection it controls: this request arrived through it, so the change would lock this client out. Turn it off from the other connection or the MCP Rule Server app page on the hub.")
        }
        updates.put(keyStr, coerced)
    }

    // selectedDevices is VALIDATED FIRST (still no write): _validateMcpDeviceScope does its own
    // atomic id validation (one unknown id throws) and the lockout guard up front, so a bad device
    // list rejects the whole batch before ANY write -- scalar or scope -- lands. A runtime fetch
    // failure returns a [success:false] envelope (no throw); surface it as-is so nothing is written.
    def deviceScopeResult = null
    if (hasDeviceScope) {
        deviceScopeResult = _validateMcpDeviceScope(deviceScopeRaw)
        if (deviceScopeResult?.success != true) {
            return deviceScopeResult
        }
    }

    // ===== APPLY PHASE =====
    // Reached only after ALL validation (scalar coerce/sub-validation + scope) has passed, so this
    // is validate-everything-then-apply: nothing above this line writes hub state.
    //
    // NOT fully atomic: Hubitat exposes no rollback primitive, so once the apply phase begins, a
    // later write throwing leaves earlier writes persisted (e.g. the scope write lands, then a scalar
    // write throws -> the scope change stays). This is a narrow window BECAUSE all validation is
    // already complete by here -- the remaining app.updateSetting calls write pre-validated, type-
    // coerced values. The audit ordering below reflects this: the "applied" lines fire only AFTER all
    // writes complete, so an audit can never over-claim success on a partially-applied batch.

    // Two-phase audit so post-mortem investigators can distinguish "validation accepted N
    // keys" (attempted) from "all N writes landed" (applied). Both fire at WARN.
    mcpLog("warn", "developer-mode", "hub_update_mcp_settings: attempted=${updates}")
    if (hasDeviceScope) {
        mcpLog("warn", "developer-mode", "hub_update_mcp_settings selectedDevices: attempted mode=${deviceScopeResult.mode} resulting=${deviceScopeResult.resultIds} added=${deviceScopeResult.added} removed=${deviceScopeResult.removed}")
        // WRITE the device-access scope: re-scope the selectedDevices capability multi-select. The
        // single-device wizard paths write [type:"capability.*", value:<id>]; the multi-select takes
        // the SAME type with a List value. Ids are the String form the hub accepts. Done here (in the
        // apply phase) rather than inside the validate helper so no write happens until every
        // validation passed. The "applied" audit for this is deferred to AFTER the scalar loop below.
        app.updateSetting("selectedDevices", [type: "capability.*", value: deviceScopeResult.resultIds])
    }

    // Apply each scalar update via app.updateSetting() — the documented Hubitat sandbox API for
    // self-modifying app settings. mcpLogLevel needs special handling:
    // The small logging config and JVM threshold mirror are updated together.
    //
    // Apply order is intentional: app.updateSetting calls first, then mcpLogLevel last via
    // toolSetLogLevel. If toolSetLogLevel ever evolves to throw on an unexpected condition,
    // the rest of the batch has already landed. Per-key validation above is the primary
    // safeguard; this ordering is belt-and-suspenders.
    for (Map.Entry entry in updates) {
        def key = entry.key
        def value = entry.value
        if (key == "mcpLogLevel") {
            // Delegate to existing helper — it updates both state cache + setting
            toolSetLogLevel([level: value.toString()])
        } else {
            app.updateSetting(key, [type: allowedSettings.get(key), value: value])
        }
    }

    // "applied" audits fire only now -- after EVERY write (scope + scalars) has completed -- so a
    // scalar write that throws mid-loop can never leave a falsely-reassuring "applied" line behind.
    mcpLog("warn", "developer-mode", "hub_update_mcp_settings: applied=${updates}")
    if (hasDeviceScope) {
        mcpLog("warn", "developer-mode", "hub_update_mcp_settings selectedDevices: applied mode=${deviceScopeResult.mode} authorizedCount=${deviceScopeResult.resultIds.size()}")
    }

    def updateCount = updates.size() + (hasDeviceScope ? 1 : 0)
    def settingWord = updateCount == 1 ? "setting" : "settings"
    // The base "...may need to reconnect to refresh cached tool schemas..." advisory only applies
    // when a scalar key that reshapes tools/list actually changed. Append it conditionally so a
    // device-scope-only (or non-schema scalar) batch doesn't carry a spurious schema-reconnect
    // note -- and so a combined scalar+scope batch doesn't double up (the device-scope message
    // already carries its own device-visibility reconnect advisory).
    // Keep this set in sync with any allowlisted setting that reshapes tools/list (the catalog or
    // its advertised schemas). Only allowlisted keys can appear in `updates`, so enableWrite /
    // enableDeveloperMode are intentionally omitted -- they are excluded from allowedSettings and
    // can never land here.
    def schemaAffectingKeys = ["enableRead", "enableCustomRuleEngine", "useGateways"] as Set
    def touchedSchemaKey = updates.keySet().any { schemaAffectingKeys.contains(it) }
    def message = "Updated ${updateCount} ${settingWord}."
    if (touchedSchemaKey) {
        message += " MCP clients (Claude Code, etc.) may need to reconnect to refresh cached tool schemas if you toggled an enable* flag or useGateways."
    }
    def result = [
        success: true,
        updated: updates,
        message: message
    ]
    if (hasDeviceScope) {
        // Fold the device-scope outcome under its own sub-key so a caller sees the resulting
        // authorized set + added/removed diff (and the applied mode) alongside the scalar updates.
        result.selectedDevices = [
            mode: deviceScopeResult.mode,
            authorizedDeviceIds: deviceScopeResult.authorizedDeviceIds,
            authorizedCount: deviceScopeResult.authorizedCount,
            added: deviceScopeResult.added,
            removed: deviceScopeResult.removed
        ]
        result.message = result.message + " " + deviceScopeResult.message
    }
    return result
}

// VALIDATE + COMPUTE a device-access scope change to selectedDevices (no write). Used by
// toolUpdateMcpSettings when the settings batch carries a selectedDevices key. selectedDevices is
// one of the self-admin settings, but it routes here instead of the generic scalar coerce/allowlist
// path BECAUSE its wire format is a capability.* multi-select (it needs a List write,
// app.updateSetting("selectedDevices", [type:"capability.*", value:<List>]), which coerceSettingValue
// cannot produce) and its safety semantics (atomic id validation against the hub + a self-lockout
// guard) have no analogue among the scalar settings. NO dev-mode/confirm gate inside -- the caller
// already gated those.
//
// This function ONLY validates + computes; it does NOT call app.updateSetting and does NOT emit the
// "applied" audit. The caller performs the write in its apply phase, so nothing is written until
// EVERY validation (scalar + scope) has passed (true all-validate-then-all-apply atomicity).
//
// Accepts the structured value {mode: "replace"|"add"|"remove" (default "replace"),
// ids: [<id strings>] (required), allowEmpty: <bool, default false>}, OR a bare array shorthand
// (selectedDevices: ["1","2"] == {mode:"replace", ids:["1","2"]}). replace sets the authorized set
// to exactly ids; add unions; remove subtracts. All three are idempotent for fixed ids.
//
// Returns [success:true, mode, resultIds, added, removed, authorizedDeviceIds, authorizedCount,
// message] on success; returns [success:false, error, note] for a runtime fetch failure; throws
// IllegalArgumentException for caller-recoverable validation errors. Touches no hub state.
private Map _validateMcpDeviceScope(scopeValue) {
    // Accept a bare array (replace shorthand) or a structured {mode, ids, allowEmpty} object.
    def mode = "replace"
    def rawIds
    def allowEmpty = false
    if (scopeValue instanceof List) {
        rawIds = scopeValue
    } else if (scopeValue instanceof Map) {
        mode = (scopeValue.mode == null) ? "replace" : scopeValue.mode.toString().trim()
        rawIds = scopeValue.ids
        allowEmpty = (scopeValue.allowEmpty == true)
    } else {
        throw new IllegalArgumentException("selectedDevices must be an array of device ID strings, or an object {mode, ids, allowEmpty}")
    }

    if (!(mode in ["replace", "add", "remove"])) {
        throw new IllegalArgumentException("selectedDevices mode must be one of: replace, add, remove (got: '${mode}')")
    }
    if (rawIds == null || !(rawIds instanceof List)) {
        throw new IllegalArgumentException("selectedDevices ids is required and must be an array of device ID strings")
    }
    // Normalize every requested id to its String form up front (the hub returns Long ids; MCP
    // callers send strings/ints). Reject a non-scalar or blank-after-trim element before any hub call.
    def requestedIds = []
    for (raw in rawIds) {
        if (raw == null || raw instanceof Map || raw instanceof List) {
            throw new IllegalArgumentException("selectedDevices ids entries must be device ID strings or integers, got: ${raw}")
        }
        def s = raw.toString().trim()
        if (!s) {
            throw new IllegalArgumentException("selectedDevices ids entries must be non-empty device IDs")
        }
        if (!requestedIds.contains(s)) requestedIds << s
    }

    // Current authorized set = the ids on the selectedDevices input. Normally a
    // List<DeviceWrapper>; tolerate raw String/Number ids defensively too. FAIL LOUD on an element
    // that resolves to neither (no .id, not a scalar) -- silently dropping it would shrink the scope
    // without telling anyone (this is the current-scope read, so it guards against corrupt stored
    // state). Per the AGENTS.md error contract: surface, don't swallow.
    def currentIds = (settings.selectedDevices ?: []).collect { dev ->
        def id = (dev instanceof String || dev instanceof Number) ? dev.toString() : dev?.id?.toString()
        if (id == null) {
            throw new IllegalArgumentException("settings.selectedDevices contains an unrecognized element (neither a device with an id nor a String/Number id): ${dev}. Nothing was changed.")
        }
        id
    } as List
    def currentSet = currentIds as Set

    // ATOMIC validation: for replace/add, every requested id must resolve to a real hub device
    // (validated against the hub-wide device inventory -- the only view of every device,
    // authorized or not; the one exception is an already-authorized id on an add against an
    // incomplete inventory, below). Validate ALL before any write so a single bad id can't leave a
    // half-applied scope. remove does NOT validate membership BECAUSE removing an id that isn't
    // present (or no longer exists on the hub) is a harmless no-op, and forcing an unknown-id read
    // fetch there would block a legitimate cleanup of a since-deleted device.
    if (mode in ["replace", "add"] && !requestedIds.isEmpty()) {
        // The same inventory as hub_list_devices scope='all' (_fetchAllHubDeviceRecords): the
        // /hub2/devicesList tree unioned with the /hub2/vrb/devices feed where the old
        // capabilities endpoint is gone. Only ids matter here, and capabilities being partial
        // does not affect validation -- but the ID SET can be partial too: whenever the two
        // sources disagree about it (the feed lists a device the tree lacks, the tree could not be
        // read or answered empty) the inventory is flagged idsComplete:false, and an id it does not
        // contain is "could not validate", never "unknown" -- rejecting off a knowingly incomplete
        // set would send the operator to hub_list_devices(scope='all'), which returns the same
        // incomplete set.
        // isError:true on the failure paths so handleToolsCall hoists them onto the JSON-RPC
        // envelope -- a failed validation that wrote nothing must reach the client AS an error,
        // not a quiet result.
        def inventory = _fetchAllHubDeviceRecords("developer-mode", "hub_update_mcp_settings selectedDevices")
        if (inventory.failure == "fetch") {
            return [success: false, isError: true, error: "Failed to fetch the all-hub device list (${inventory.source}) to validate selectedDevices: ${inventory.fetchError}", note: "Endpoint may be unavailable on this firmware; nothing was changed."]
        }
        if (inventory.failure) {
            return [success: false, isError: true, error: "Unexpected ${inventory.source} response; cannot validate selectedDevices.", note: "Hub firmware may have changed the endpoint contract; nothing was changed."]
        }
        def hubDeviceIds = (inventory.records.findAll { it instanceof Map }.collect { it.id?.toString() }.findAll { it != null }) as Set
        def unknown = requestedIds.findAll { !hubDeviceIds.contains(it) }
        // An incomplete inventory must not refuse an add over ids that are already authorized
        // (re-adding them is a no-op). A complete inventory still rejects stale ids, including
        // authorized ones.
        if (inventory.idsComplete == false && mode == "add") {
            unknown = unknown.findAll { !currentSet.contains(it) }
        }
        if (!unknown.isEmpty()) {
            if (inventory.idsComplete == false) {
                return [success: false, isError: true,
                        error: "Could not validate device id(s) ${unknown.join(', ')}: the all-hub device inventory is incomplete, so they may be real devices it omitted. ${inventory.partialNote ?: ''}".toString().trim(),
                        note: "Nothing was changed. Retry once /hub2/devicesList answers; hub_list_devices(scope='all') reports the same inventory and its capabilitiesNote says what is missing."]
            }
            throw new IllegalArgumentException("Unknown device id(s): ${unknown.join(', ')}. Use hub_list_devices(scope='all') to see valid ids. Nothing was changed.")
        }
    }

    // Compute the resulting set per mode. add uses a Set-backed union (LinkedHashSet) so the dedupe
    // is O(n) instead of O(n*m) -- current ids first (insertion order), then the new requested ids.
    def resultIds
    switch (mode) {
        case "replace": resultIds = new ArrayList(requestedIds); break
        case "add":     def u = new LinkedHashSet(currentIds); u.addAll(requestedIds); resultIds = new ArrayList(u); break
        case "remove":  resultIds = currentIds.findAll { !requestedIds.contains(it) }; break
    }
    def resultSet = resultIds as Set

    // Self-lockout guard: an empty resulting set blinds the MCP server to every selected device
    // (only MCP-managed virtual devices would remain reachable). Same footgun class as why
    // enableWrite/enableDeveloperMode are excluded from the scalar allowlist -- require an explicit
    // allowEmpty:true to proceed.
    if (resultSet.isEmpty() && !allowEmpty) {
        throw new IllegalArgumentException("Refusing to empty the MCP device-access scope: the resulting set is empty, which blinds the MCP server to every selected device. Pass selectedDevices.allowEmpty:true to confirm you intend to clear the scope.")
    }

    def added = (resultSet - currentSet) as List
    def removed = (currentSet - resultSet) as List

    // Proper singular/plural for the human-readable message (1 device vs 2 devices).
    def dw = { n -> n == 1 ? "device" : "devices" }
    return [
        success: true,
        mode: mode,
        resultIds: resultIds,
        authorizedDeviceIds: resultIds,
        authorizedCount: resultIds.size(),
        added: added,
        removed: removed,
        message: "MCP device-access scope updated (mode=${mode}): ${resultIds.size()} ${dw(resultIds.size())} authorized, ${added.size()} ${dw(added.size())} added, ${removed.size()} ${dw(removed.size())} removed. Device visibility changed -- MCP clients may need to reconnect to refresh which devices are exposed."
    ]
}

// Coerce + validate a single setting value into the type the Hubitat input expects.
// Throws IllegalArgumentException for unrepresentable values (rather than silently
// substituting a default — that would mask the caller's intent and recreate the same
// kind of footgun the bool string-truthiness bug is fixing).
//
// - bool: accepts native Boolean, plus case-insensitive "true"/"false" strings.
// - number: accepts native Number, plus integer/decimal-formatted strings.
// - enum: passed through; downstream (e.g. toolSetLogLevel) does its own enum-membership
//         check against a tool-specific allowed list.
private coerceSettingValue(String key, value, String type) {
    if (value == null) {
        throw new IllegalArgumentException("Setting '${key}' value cannot be null")
    }
    switch (type) {
        case "bool":
            if (value instanceof Boolean) return value
            def s = value.toString().toLowerCase()
            if (s == "true") return true
            if (s == "false") return false
            throw new IllegalArgumentException("Setting '${key}' expects a boolean (true/false), got: ${_describeValueForError(value)}")

        case "number":
            if (value instanceof Number) return value
            def s = value.toString()
            if (s.isInteger()) return s.toInteger()
            if (s.isLong()) return s.toLong()
            if (s.isBigDecimal()) return s.toBigDecimal()
            throw new IllegalArgumentException("Setting '${key}' expects a number, got: ${_describeValueForError(value)}")

        case "enum":
            // Pass through as String — downstream validates against tool-specific enum set.
            return value.toString()

        default:
            // Defensive: unknown type from the allowlist map should not reach here.
            return value
    }
}

// Canonical raw-source base for the MCP package. Per-call URLs are "${base}/${ref}/${path}";
// mirrors packageManifest.json's location (.../Hubitat-local-MCP-server/main/hubitat-mcp-server.groovy).
// Overridable per call via baseUrl for forks / CI branches on a different remote.
def getPackageSourceBase() {
    return "https://raw.githubusercontent.com/kingpanther13/Hubitat-local-MCP-server"
}

// Re-anchor a packageManifest.json item location to the deploy `ref`. Manifest locations
// are full raw URLs committed against a fixed branch (e.g. .../main/bundles/mcp-libraries.zip);
// strip the scheme://host/owner/repo/<branch>/ prefix to the repo-relative path, then rebuild
// against base+ref. This is what lets hub_update_package install an UNMERGED PR's artifacts --
// HPM repair trusts the manifest's branch-pinned URL; we can't. Same 4-segment prefix-strip as
// .github/scripts/mcp_watchdog_deploy.sh (that one hard-codes the raw.githubusercontent.com host;
// this regex is host-agnostic). Returns null when the location is not in the expected
// scheme://host/owner/repo/ref/<path> shape, so the caller fails closed.
def _reanchorToRef(location, String base, String ref) {
    if (!(location instanceof String) || !location.trim()) return null
    def loc = location.trim()
    def rel = loc.replaceFirst(/^https?:\/\/[^\/]+\/[^\/]+\/[^\/]+\/[^\/]+\//, '')
    if (rel == loc || !rel) return null
    return "${base}/${ref}/${rel}".toString()
}

// Bot-published bundle artifact URL for a ref (the bundle-artifacts branch). PRs stopped
// rebuilding the committed bundles/*.zip (the post-merge workflow owns it on main), so the
// publish-bundle-artifact workflow builds the zip on every library-touching push and stores
// it under shas/<full-sha>/ and branches/<branch>/ -- the fresh-zip source that lets this
// tool install an unmerged PR's libraries commit by commit. The zip KEEPS its manifest
// basename inside the artifact path: the hub appears to key the bundle entity on the zip
// filename, so a renamed zip would import as a SECOND entity (duplicate libraries) instead
// of updating the existing one. Returns null when the manifest location shape is unusable.
def _bundleArtifactUrlForRef(location, String base, String ref) {
    if (!(location instanceof String) || !location.trim() || !ref) return null
    def loc = location.trim()
    def rel = loc.replaceFirst(/^https?:\/\/[^\/]+\/[^\/]+\/[^\/]+\/[^\/]+\//, '')
    if (rel == loc || !rel) return null
    def baseName = rel.tokenize('/').last()
    // Full 40-hex refs key by SHA; everything else is treated as a branch name. A SHORT
    // sha has no artifact path (the workflow stores full SHAs only) -- it probes the
    // branches/ path, misses, and falls back to the committed zip.
    def keyPath = (ref ==~ /[0-9a-f]{40}/) ? "shas/${ref}" : "branches/${ref}"
    return "${base}/bundle-artifacts/${keyPath}/${baseName}".toString()
}

// Probe the artifact's tiny .size marker (written atomically alongside the zip by the
// publish workflow) instead of downloading the ~1MB zip just to check existence. An
// integer body means the zip is there; a 404 (throws), an HTML error page, or any
// non-integer body means no artifact -- the caller falls back to the committed zip.
def _bundleArtifactExists(String artifactUrl) {
    try {
        def r = _httpFetchUrl("${artifactUrl}.size")
        return ((r?.status as Integer) == 200) && (r?.body?.toString()?.trim() ==~ /\d+/)
    } catch (Exception e) {
        // A legitimate miss (404) and a transient probe failure (rate limit, network blip) both
        // land here; log so a fallback caused by a TRANSIENT failure is at least diagnosable
        // instead of silently indistinguishable from "no artifact published for this ref".
        mcpLog("warn", "developer-mode", "_bundleArtifactExists: probe of ${artifactUrl}.size failed (${e.toString()}) -- treating as no artifact; the bundle leg falls back to the committed zip")
        return false
    }
}

// Parse "#include namespace.Name" directives from Groovy source. Returns an ordered,
// de-duplicated list of include tokens ("namespace.Name") in first-seen order so the
// install order is deterministic across runs.
def _parseIncludeDirectives(String source) {
    def tokens = []
    def seen = [] as Set
    def matcher = (source =~ /(?m)^[ \t]*#include[ \t]+([A-Za-z0-9_]+\.[A-Za-z0-9_]+)[ \t]*$/)
    while (matcher.find()) {
        def tok = matcher.group(1)
        if (!seen.contains(tok)) { seen << tok; tokens << tok }
    }
    return tokens
}

// Resolve the MCP server's own Apps Code CLASS id (distinct from the running INSTANCE
// id) by matching definition()'s namespace+name against /hub2/userAppTypes -- the same
// lookup the e2e deploy script does. Returns the id String, or null when it can't be
// resolved (the caller fails closed and writes nothing).
def _resolveSelfAppClassId() {
    try {
        def responseText = hubInternalGet("/hub2/userAppTypes")
        if (!responseText) return null
        def parsed = new groovy.json.JsonSlurper().parseText(responseText)
        if (!(parsed instanceof List)) return null
        def match = parsed.find { it?.namespace == "mcp" && it?.name == "MCP Rule Server" }
        return match?.id?.toString()
    } catch (Exception e) {
        // Reached from the code-update path too (not just hub_update_package); keep the label neutral.
        mcpLog("warn", "hub-admin", "_resolveSelfAppClassId: self app-class lookup failed (${e.toString()}) -- caller must handle the unavailable class identity")
        return null
    }
}

// Public package-deploy boundary. A real repair is scheduled and acknowledged
// immediately so the MCP/Hubitat cloud request never has to remain open for the
// minutes-long bundle + app repair. dryRun stays synchronous because it performs
// no writes and is expected to return the complete plan.
def toolUpdatePackage(args) {
    if (!settings.enableDeveloperMode) {
        throw new IllegalArgumentException("Developer Mode tools are disabled. Enable 'Developer Mode Tools' in MCP rule app settings to use hub_update_package.")
    }
    def ref = args?.ref
    if (!(ref instanceof String) || !ref.trim()) {
        throw new IllegalArgumentException("ref is required: a branch, tag, or commit SHA to deploy (e.g. 'main' or a PR head SHA).")
    }
    ref = ref.trim()
    if (args?.dryRun == true) return _updatePackageBody(args as Map, ref, true)

    requireDestructiveConfirm(args?.confirm)
    long startedAt = now()
    String requestId = "pkg-${java.util.UUID.randomUUID()}".toString()
    def storedArgs = [ref: ref, confirm: true]
    if (args?.baseUrl instanceof String && args.baseUrl.trim()) storedArgs.baseUrl = args.baseUrl.trim()
    Map refusal = null
    synchronized (WRITE_RESERVATION_LOCK) {
        _packageSweepMarkerLocked()
        def inFlight = _writeStateValueLocked("packageDeployInFlight")
        if (inFlight instanceof Map) {
            def summary = [ref: inFlight.ref, requestId: inFlight.requestId,
                           startedAt: inFlight.startedAt]
            if (inFlight.startedAt != null) {
                try { summary.elapsedMs = now() - (inFlight.startedAt as Long) }
                catch (Exception ignored) { }
            }
            refusal = [
                success: false, isError: true, status: "duplicate_in_flight",
                inFlight: summary,
                error: "A package deploy (ref '${inFlight.ref}') is already running on this hub. Nothing was changed.",
                note: "Do not re-run the deploy. Watch hub_get_info.lastSelfDeploy for a record whose requestId matches the original acceptance response."
            ]
        }
        if (refusal == null) {
            _writeStateSetLocked("packageDeployInFlight", [
                requestId: requestId, ref: ref, startedAt: startedAt,
                phase: "queued", expiresAt: startedAt + _packageDeployRecoveryMs(),
                args: storedArgs
            ])
        }
    }
    if (refusal != null) return refusal
    try {
        runIn(1, "runPackageDeploy", [data: [requestId: requestId]])
    } catch (Exception scheduleErr) {
        synchronized (WRITE_RESERVATION_LOCK) {
            def current = _writeStateValueLocked("packageDeployInFlight")
            if (current instanceof Map && current.requestId?.toString() == requestId) {
                _writeStateSetLocked("packageDeployInFlight", null)
                try { atomicState.remove("packageDeployInFlight") } catch (Exception ignored) { }
            }
        }
        return [success: false, isError: true, status: "schedule_failed", ref: ref,
                error: "Package deploy could not be scheduled: ${scheduleErr.message}. Nothing was changed.",
                note: "The in-flight marker was released, so this call is safe to retry with the same ref. If it keeps failing, the hub's scheduler is refusing jobs -- check hub_get_logs, then deploy each app with hub_update_app instead."]
    }
    return [
        success: true,
        status: "in_progress",
        ref: ref,
        requestId: requestId,
        startedAt: startedAt,
        message: "Package deploy accepted and is running in the background.",
        note: "Do not submit it again. Read hub_get_info.lastSelfDeploy until its requestId matches this response; success/error then carries the final outcome."
    ]
}

// Scheduled worker for the real repair. The scheduled requestId prevents an old
// delayed invocation from running or clearing a newer deploy marker.
def runPackageDeploy(Map job = [:]) {
    String requestId = job?.requestId?.toString()
    Map marker = null
    synchronized (WRITE_RESERVATION_LOCK) {
        def current = _writeStateValueLocked("packageDeployInFlight")
        if (current instanceof Map && current.requestId?.toString() == requestId
                && current.args instanceof Map && current.ref
                && !_writeExecutionLiveLocked(requestId)) {
            marker = [:] + (current as Map)
            marker.phase = "running"
            marker.expiresAt = now() + _packageDeployRecoveryMs()
            _writeStateSetLocked("packageDeployInFlight", marker)
            LIVE_WRITE_EXECUTIONS.add(requestId)
        }
    }
    if (marker == null) return
    def result = null
    try {
        Map workerContext = [requestId: requestId, packageRef: marker.ref.toString()]
        result = _updatePackageBody(marker.args as Map, marker.ref.toString(), false, workerContext)
        def last = atomicState.lastSelfDeploy
        if (!(last instanceof Map) || last.requestId?.toString() != requestId) {
            atomicState.lastSelfDeploy = [
                success: result?.success == true,
                error: result?.success == true ? null : (result?.error ?: result?.message ?: "Package deploy failed"),
                sourceMode: "package",
                ref: marker.ref,
                requestId: requestId,
                packageResult: result,
                at: now()
            ]
        }
    } catch (Exception e) {
        mcpLog("error", "developer-mode", "Background package deploy for ref ${marker.ref} failed: ${e.message}")
        // Same guard as the success path: when the self-app leg already stamped this
        // requestId, a throw from a LATER statement must not flip that persisted
        // success into a failure the client would then re-deploy.
        def last = atomicState.lastSelfDeploy
        if (!(last instanceof Map) || last.requestId?.toString() != requestId) {
            atomicState.lastSelfDeploy = [success: false, error: e.message ?: e.toString(),
                                          sourceMode: "package", ref: marker.ref,
                                          requestId: requestId, at: now()]
        }
    } finally {
        synchronized (WRITE_RESERVATION_LOCK) {
            try {
                def current = _writeStateValueLocked("packageDeployInFlight")
                if (current instanceof Map && current.requestId?.toString() == requestId) {
                    _writeStateSetLocked("packageDeployInFlight", null)
                    atomicState.remove("packageDeployInFlight")
                }
            } catch (Exception ignored) {
            } finally {
                LIVE_WRITE_EXECUTIONS.remove(requestId)
            }
        }
    }
}

// Deterministic deploy body used by the scheduled worker and synchronous dry-run.
def _updatePackageBody(Map args, String ref, boolean dryRun, Map packageWorkerContext = null) {

    def base = (args?.baseUrl instanceof String && args.baseUrl.trim())
        ? args.baseUrl.trim().replaceAll('/+$', '')
        : getPackageSourceBase()
    // .toString() throughout: _fetchSourceFromUrl / hub_install_bundle / hub_update_app
    // reject a GString importUrl (instanceof String is false for GStringImpl).
    def appUrl = "${base}/${ref}/hubitat-mcp-server.groovy".toString()

    // Fetch the SELF app source at ref first, ONLY to read its #include directives for the
    // bundle-coverage guard below. A fetch failure is a clean abort -- nothing written.
    def appSource
    try {
        appSource = _fetchSourceFromUrl(appUrl)
    } catch (Exception e) {
        return [
            success: false, aborted: true, abortReason: "app_source_fetch_failed", ref: ref, appUrl: appUrl,
            error: "Failed to fetch app source at ref '${ref}' (${appUrl}): ${e.message ?: e.toString()}. Nothing was changed."
        ]
    }
    def includeTokens = _parseIncludeDirectives(appSource)

    // Fetch packageManifest.json AT THE REF -- the authoritative list of what to deploy
    // (HPM's manifest, but at the PR ref so an unmerged PR installs). Fail closed on a
    // fetch or parse error: deploying without the manifest could miss a bundle or app.
    def manifestUrl = "${base}/${ref}/packageManifest.json".toString()
    def manifestText
    try {
        manifestText = _fetchSourceFromUrl(manifestUrl)
    } catch (Exception e) {
        return [
            success: false, aborted: true, abortReason: "manifest_fetch_failed", ref: ref, manifestUrl: manifestUrl,
            error: "Failed to fetch packageManifest.json at ref '${ref}' (${manifestUrl}): ${e.message ?: e.toString()}. Nothing was changed."
        ]
    }
    def manifest
    try {
        manifest = new groovy.json.JsonSlurper().parseText(manifestText)
    } catch (Exception e) {
        manifest = null
    }
    if (!(manifest instanceof Map)) {
        return [
            success: false, aborted: true, abortReason: "manifest_unparseable", ref: ref, manifestUrl: manifestUrl,
            error: "packageManifest.json at ref '${ref}' was not a JSON object. Nothing was changed."
        ]
    }

    // Plan the bundle leg: prefer the bot-published per-ref artifact (fresh for any
    // same-repo ref -- see _bundleArtifactUrlForRef). The fallback depends on the
    // MANIFEST SHAPE AT THE REF, which is what keeps old refs working unchanged:
    //   * unified-delivery manifests (location on the bundle-artifacts branch) fall
    //     back to that location AS-IS -- the branches/main zip, exactly what HPM users
    //     currently install; correct whenever the ref's libraries match current main,
    //     surfaced via bundleFreshnessWarning otherwise.
    //   * legacy manifests (in-tree location) fall back to the zip COMMITTED at the
    //     ref via _reanchorToRef -- correct whenever the ref did not change libraries/
    //     relative to its base.
    def manifestBundles = (manifest.bundles instanceof List) ? manifest.bundles : []
    def plannedBundles = []
    for (b in manifestBundles) {
        def loc = (b?.location instanceof String) ? b.location.trim() : null
        def entry
        if (loc && loc.contains("/bundle-artifacts/")) {
            entry = [name: (b?.name ?: b?.id), url: loc, source: "manifest-current"]
        } else {
            def url = _reanchorToRef(loc, base, ref)
            if (!url) {
                return [
                    success: false, aborted: true, abortReason: "bundle_location_unusable", ref: ref,
                    error: "Bundle '${b?.name ?: b?.id ?: '?'}' in packageManifest.json has an unusable location '${b?.location}' (expected a scheme://host/owner/repo/ref/<path> raw URL or a bundle-artifacts URL). Nothing was changed."
                ]
            }
            entry = [name: (b?.name ?: b?.id), url: url, source: "committed-at-ref"]
        }
        def artifactUrl = _bundleArtifactUrlForRef(loc, base, ref)
        if (artifactUrl && _bundleArtifactExists(artifactUrl)) {
            entry.url = artifactUrl
            entry.source = "bundle-artifacts"
        }
        // SHA guard: a SHA-shaped ref (hex) with NO per-ref artifact would fall back to the manifest's
        // branches/main zip -- i.e. deliver MAIN's libraries, not this commit's (silently wrong, and
        // exactly how an abbreviated/typo'd SHA loads the wrong bundle). A pushed commit ALWAYS has a
        // per-SHA artifact (publish-bundle-artifact builds one per push, keyed by FULL sha), so a
        // SHA-shaped ref with none is abbreviated, unpushed, or typo'd -- fail loudly instead of
        // installing the wrong bundle. (Branch/tag refs legitimately fall back to branches/main with a
        // freshness warning; only commit-SHA refs are guarded, since that's where a hallucinated value bites.)
        if (entry.source == "manifest-current" && ref != null && (ref.toString().trim() ==~ /(?i)^[0-9a-f]{7,40}$/)) {
            return [
                success: false, aborted: true, abortReason: "no_bundle_artifact_for_ref", ref: ref,
                bundle: (b?.name ?: b?.id), artifactUrlProbed: artifactUrl,
                error: "No per-ref bundle artifact exists for ref '${ref}' (probed ${artifactUrl ?: 'n/a'}); the manifest's bundle points at branches/main, so installing it would deliver MAIN's libraries, not this ref's. Pass the FULL 40-char commit SHA of a PUSHED commit (not an abbreviation), or push the branch so its bundle artifact is built. Nothing was changed."
            ]
        }
        plannedBundles << entry
    }

    // Coverage guard (mirrors mcp_watchdog_deploy.sh): if the app #includes libraries but
    // the manifest declares NO bundle to deliver them, a deploy would leave the #includes
    // unresolved and the app would not compile. Refuse before any write.
    if (!includeTokens.isEmpty() && plannedBundles.isEmpty()) {
        return [
            success: false, aborted: true, abortReason: "bundle_required_but_undeclared", ref: ref, includes: includeTokens,
            error: "App source #includes ${includeTokens.size()} library(ies) (${includeTokens.join(', ')}) but packageManifest.json at ref '${ref}' declares no bundle to deliver them. A bundle-less deploy would leave the #includes unresolved and the app would not compile. Nothing was changed."
        ]
    }

    // Plan the app leg: resolve every manifest app's Apps Code CLASS id by namespace+name
    // (one /hub2/userAppTypes fetch). The SELF app (mcp / "MCP Rule Server", the running
    // parent) is flagged so it can be deployed LAST -- its recompile drops the in-flight
    // response (#237), so it must be the final act with the rest already in place.
    def manifestApps = (manifest.apps instanceof List) ? manifest.apps : []
    def appTypes
    try {
        def typesText = hubInternalGet("/hub2/userAppTypes")
        appTypes = typesText ? new groovy.json.JsonSlurper().parseText(typesText) : null
    } catch (Exception e) {
        appTypes = null
    }
    if (!(appTypes instanceof List)) {
        return [
            success: false, aborted: true, abortReason: "app_class_unresolved", ref: ref,
            error: "Could not list Apps Code classes via /hub2/userAppTypes to resolve the manifest's apps. Nothing was changed; the app remains updatable via hub_update_app."
        ]
    }
    def plannedApps = []
    for (a in manifestApps) {
        def match = appTypes.find { it?.namespace == a?.namespace && it?.name == a?.name }
        def classId = match?.id?.toString()
        def url = _reanchorToRef(a?.location, base, ref)
        if (!classId || !url) {
            return [
                success: false, aborted: true, abortReason: "app_class_unresolved", ref: ref,
                error: "Could not resolve app '${a?.namespace}:${a?.name}' (class id: ${classId ?: 'unresolved'}, url: ${url ?: 'unusable location'}). Nothing was changed; the app remains updatable via hub_update_app."
            ]
        }
        plannedApps << [
            name: a?.name, namespace: a?.namespace, classId: classId, url: url,
            isSelf: (a?.namespace == "mcp" && a?.name == "MCP Rule Server")
        ]
    }
    // Non-self apps first, the self app last (so the self recompile is the final act).
    def orderedApps = plannedApps.findAll { !it.isSelf } + plannedApps.findAll { it.isSelf }

    if (dryRun) {
        return [
            success: true, dryRun: true, ref: ref, appUrl: appUrl, includes: includeTokens,
            plannedBundles: plannedBundles, plannedApps: orderedApps,
            message: "Dry run: would install ${plannedBundles.size()} bundle(s) then deploy ${orderedApps.size()} app(s) (self app last) to ref ${ref}. No changes made."
        ]
    }

    // BUNDLES FIRST (override). HPM repair installs every manifest bundle via the hub's
    // uploadZipFromUrl endpoint, which overwrites the libraries in place. Abort the WHOLE
    // deploy on the first failure, BEFORE touching any app, so an app is never saved
    // against a missing/stale library. We trust the hub's success signal (no separate
    // library-presence re-read): uploadZipFromUrl unpacks + registers the libraries
    // SYNCHRONOUSLY before returning success -- the same signal HPM relies on -- and the
    // self app #includes them, so the final backstop is its compile: a missing #include
    // makes the self app save fail (app_update_failed/threw, reported), never silently land.
    def bundleResults = []
    for (b in plannedBundles) {
        def r
        try {
            r = toolInstallBundle([importUrl: b.url, confirm: true])
        } catch (Exception e) {
            mcpLog("warn", "developer-mode", "hub_update_package: bundle ${b.url} install threw: ${e.toString()}")
            return [
                success: false, aborted: true, abortReason: "bundle_install_threw", ref: ref, bundles: bundleResults,
                error: "Bundle ${b.name ?: b.url} failed to install: ${e.message ?: e.toString()}. Apps NOT touched -- they remain as-is and updatable via hub_update_app."
            ]
        }
        def ok = (r?.success == true)
        bundleResults << [name: b.name, url: b.url, source: b.source, success: ok, error: (ok ? null : (r?.error ?: r?.message))]
        if (!ok) {
            return [
                success: false, aborted: true, abortReason: "bundle_install_failed", ref: ref, bundles: bundleResults,
                error: "Bundle ${b.name ?: b.url} install reported failure: ${r?.error ?: r?.message ?: 'unknown'}. Apps NOT touched -- they remain as-is and updatable via hub_update_app."
            ]
        }
    }

    // APPS LAST, the self app last of all. Each non-self app must succeed before the self
    // app is touched (fail-closed: a child-app failure never advances to the self deploy,
    // so the running server is left as-is and updatable). Reuse hub_update_app's exact
    // update path (auto-backup + post-save verify + #237 compile-error capture).
    def appResults = []
    for (a in orderedApps) {
        def r
        try {
            def updateArgs = [appId: a.classId, importUrl: a.url, confirm: true]
            r = _toolUpdateAppCode(updateArgs, a.isSelf ? packageWorkerContext : null)
        } catch (Exception e) {
            if (a.isSelf) {
                // A self-update recompiles the running server mid-call, so the response can
                // be lost even though the save landed. Surface it: the bundle(s) and other
                // apps are already in place, and hub_update_app remains available to retry.
                appResults << [name: a.name, namespace: a.namespace, classId: a.classId, isSelf: true, success: false, error: (e.message ?: e.toString())]
                return [
                    success: false, partial: true, abortReason: "app_update_threw", ref: ref,
                    bundles: bundleResults, apps: appResults,
                    error: "Bundle(s) and other apps installed, but the self app update call did not return cleanly (likely the self-update recompile): ${e.message ?: e.toString()}. Verify with hub_get_source; re-run hub_update_app(importUrl) if needed."
                ]
            }
            mcpLog("warn", "developer-mode", "hub_update_package: app ${a.namespace}:${a.name} update threw: ${e.toString()}")
            return [
                success: false, aborted: true, abortReason: "app_update_threw", ref: ref,
                bundles: bundleResults, apps: appResults,
                error: "App ${a.namespace}:${a.name} update threw before the self app was touched: ${e.message ?: e.toString()}. The self (server) app was NOT touched -- it remains as-is and updatable via hub_update_app."
            ]
        }
        def ok = (r?.success == true)
        appResults << [name: a.name, namespace: a.namespace, classId: a.classId, isSelf: a.isSelf, success: ok, app: r]
        if (!ok) {
            if (a.isSelf) {
                // Self app is last; a clean failure return (not a throw) is surfaced as-is. Same
                // partial state as the throw path above (bundles + other apps landed, self did not
                // update), so flag partial=true too -- the difference is only threw vs returned-false.
                mcpLog("warn", "developer-mode", "hub_update_package: ref=${ref} self app update reported failure")
                return [
                    success: false, partial: true, ref: ref, includes: includeTokens, bundles: bundleResults, apps: appResults, app: r,
                    message: "Bundle(s) + other apps installed; the self (server) app update reported failure -- see apps[].app.error. hub_update_app remains available to retry."
                ]
            }
            return [
                success: false, aborted: true, abortReason: "app_update_failed", ref: ref,
                bundles: bundleResults, apps: appResults,
                error: "App ${a.namespace}:${a.name} update reported failure: ${r?.error ?: r?.message ?: 'unknown'}. The self (server) app was NOT touched -- it remains as-is and updatable via hub_update_app."
            ]
        }
    }

    mcpLog("info", "developer-mode", "hub_update_package: ref=${ref} bundles=${bundleResults.size()} apps=${appResults.size()} repaired")
    def result = [
        success: true, ref: ref, includes: includeTokens, bundles: bundleResults, apps: appResults,
        message: "Package repaired to ref ${ref}: ${bundleResults.size()} bundle(s) + ${appResults.size()} app(s) deployed (self app last)."
    ]
    // Whenever a bundle leg FELL BACK from the per-ref artifact, say so. The wording keys
    // on what was actually installed: "manifest-current" = the manifest's bundle-artifacts
    // branches/main zip (exactly what HPM users install; only wrong if this ref's libraries
    // differ from current main); "committed-at-ref" = a legacy ref's in-tree zip (only
    // wrong if the ref changed library code relative to its base).
    if (bundleResults.any { it.source == "manifest-current" }) {
        if (ref == "main") {
            result.bundleFreshnessWarning = "The per-ref artifact probe failed, so the bundle leg installed the manifest's branches/main zip directly -- for ref=main that is the correct, current bundle (the same bytes HPM users install). Noted only because the probe failing may indicate a transient raw.githubusercontent issue."
            mcpLog("warn", "developer-mode", "hub_update_package: ref=main artifact probe failed; installed the manifest's branches/main zip directly (correct bytes for main)")
        } else {
            result.bundleFreshnessWarning = "Ref '${ref}': no bundle-artifacts zip was found for this ref, so the bundle leg installed CURRENT MAIN's bundle (the manifest's branches/main zip). That is only correct if this ref's libraries match current main. If this ref changed library code, push it to this repo (publish-bundle-artifact stores a fresh zip per push, keyed by branch and full SHA) and re-run."
            mcpLog("warn", "developer-mode", "hub_update_package: non-main ref '${ref}' fell back to current main's bundle -- wrong if the ref changed library code")
        }
    } else if (bundleResults.any { it.source == "committed-at-ref" }) {
        result.bundleFreshnessWarning = "Ref '${ref}' (legacy manifest): no bundle-artifacts zip was found for this ref, so the bundle leg installed the zip COMMITTED at the ref. That is only stale if this ref CHANGED library code without rebuilding the zip."
        mcpLog("warn", "developer-mode", "hub_update_package: legacy ref '${ref}' fell back to the committed bundle zip -- stale if the ref changed library code")
    }
    return result
}

def _getAllToolDefinitions_partSelfAdmin() {
    return [
        [
            name: "hub_update_mcp_settings",
            description: "Update one or more of the MCP rule app's own settings (toggles, log levels, tuning, the device-access scope) in place — self-administer the app without the Hubitat UI. Gated on enableDeveloperMode + the Write master + confirm=true + a recent backup; every successful write is logged at WARN for audit.[[FLAT_TRIM]] Changing an enable* toggle or useGateways reshapes tools/list, and changing selectedDevices changes which devices are visible, so MCP clients may need to reconnect to refresh cached schemas / device visibility.[[/FLAT_TRIM]]",
            inputSchema: [
                type: "object",
                properties: [
                    settings: [type: "object", description: "Map of setting key → new value (e.g. {\"mcpLogLevel\":\"warn\",\"enableCustomRuleEngine\":true}). Unlisted keys are rejected. bypassDeviceAllowlist (bool, default OFF): DANGEROUS escape hatch — when ON native device reads, writes, commands, inventory, health, dependents, swaps and replacements reach ANY hub device by id, IGNORING selectedDevices. Allowlisted keys: mcpLogLevel, debugLogging, maxCapturedStates, loopGuardMax, loopGuardWindowSec, enableRead, enableCustomRuleEngine, useGateways, enableMandatoryBPS, bypassDeviceAllowlist, maxConcurrentWrites, backupEveryRuleWrite, enableLocalAccess, enableCloudAccess, redactAccessTokens, selectedDevices.[[FLAT_TRIM]] enableLocalAccess / enableCloudAccess (bool): allow requests over the LAN / Hubitat cloud endpoint; a call cannot turn off the connection it arrived on.[[/FLAT_TRIM]] mcpLogLevel: debug|info|warn|error. maxConcurrentWrites: integer 0-100[[FLAT_TRIM]] (default 2; 0 disables the server-side all-write concurrency cap)[[/FLAT_TRIM]]. backupEveryRuleWrite (bool, default OFF): ON takes a fresh File Manager backup before every native-app edit instead of reusing a same-app baseline for one hour. bypassDeviceAllowlist is independent of Developer Mode; see hub_get_tool_guide(section='hub_admin_write_system'). selectedDevices = the device-access scope[[FLAT_TRIM]]: {mode:replace|add|remove, ids:[device id strings]}; a bare array is shorthand for a destructive replace[[/FLAT_TRIM]] — see hub_get_tool_guide(section='hub_admin_write_system') for per-mode semantics."],
                    confirm: [type: "boolean", description: "REQUIRED: must be true to confirm the operation"]
                ],
                required: ["settings", "confirm"]
            ]
        ],
        [
            name: "hub_update_package",
            description: """Developer Mode self-deploy: full HPM-repair of the MCP package at a git ref in one call -- OVERRIDES whatever is installed, anchored to packageManifest.json AT `ref` so an UNMERGED PR installs.[[FLAT_TRIM]] (Plain HPM Repair only reads the PUBLISHED manifest, so it can't reach an unmerged PR's artifacts.)[[/FLAT_TRIM]]

Gated on enableDeveloperMode[[FLAT_TRIM]] (the tool is hidden from tools/list when Developer Mode is off)[[/FLAT_TRIM]] + the Write master + confirm=true + a recent backup. Use dryRun=true to fetch + parse + plan with ZERO writes (no confirm/backup needed)[[FLAT_TRIM]] and see exactly which bundles and apps would deploy[[/FLAT_TRIM]].

A real deploy is accepted quickly with `status: "in_progress"` and runs in the background; do NOT submit it again while one is in flight.[[FLAT_TRIM]] The background run uses Hubitat's own scheduler, so neither the cloud relay nor the MCP client's request timeout has to stay open for the minutes-long repair; a concurrent second deploy is refused. Poll hub_get_info.lastSelfDeploy until its `requestId` matches the acceptance response; that bound record's `success`/`error` fields carry the outcome. No client extension or custom token is required.[[/FLAT_TRIM]]
""",
            inputSchema: [
                type: "object",
                properties: [
                    ref: [type: "string", description: "Branch, tag, or commit SHA to deploy (e.g. 'main' or a PR head SHA)."],
                    dryRun: [type: "boolean", description: "OPTIONAL. When true, report the deploy plan with NO writes (skips the confirm/backup gate). Default false."],
                    baseUrl: [type: "string", description: "OPTIONAL raw-source base override (no trailing slash); defaults to the canonical repo.[[FLAT_TRIM]] Per-call URLs are built as <baseUrl>/<ref>/<path>. Use for forks / CI branches on a different remote.[[/FLAT_TRIM]]"],
                    confirm: [type: "boolean", description: "REQUIRED for a real deploy (omit for dryRun). Must be true; confirms a recent backup exists and the user approved the self-deploy."],
                    args: [type: "object"]
                ],
                required: ["ref"]
            ]
        ],
    ]
}

def _idempotentWriteToolNames_partSelfAdmin() {
    // Retry-safe writes (MCP idempotentHint) for this library's tools -- contributed to the
    // app's getIdempotentWriteToolNames() aggregator; see the classification rules there.
    return [
        // MCP self-admin + logging (selectedDevices (replace/add/remove), when carried in the
        // settings batch, is idempotent too -- re-delivery converges on the same authorized set
        // for all three modes)
        "hub_update_mcp_settings",
        // Developer Mode self-deploy (full repair to a ref converges, while the
        // public boundary refuses a duplicate that is already in flight)
        "hub_update_package"
    ]
}

def _openWorldToolNames_partSelfAdmin() {
    // Tools in this library that reach BEYOND the hub to the open internet (MCP
    // openWorldHint) -- contributed to the app's getOpenWorldToolNames() aggregator.
    return [
        "hub_update_package"
    ]
}

def _developerModeOnlyToolNames_partSelfAdmin() {
    // Developer-Mode-only tools in this library (catalog-hidden until the toggle is on) --
    // contributed to the app's getDeveloperModeOnlyToolNames() aggregator.
    //
    // Invariant: exactly ONE self-admin tool stays catalog-VISIBLE (runtime-refused when the
    // toggle is off) to serve as the hub_manage_mcp gateway anchor -- it keeps the gateway
    // present on tools/list and gives the operator the "Developer Mode is off; enable it"
    // discoverability surface. hub_update_mcp_settings is that anchor, so it is deliberately
    // absent from this list. Every OTHER self-admin tool hides when the toggle is off (the
    // anchor already provides discoverability), so they go here.
    return [
        "hub_update_package"
    ]
}

def _toolDisplayMeta_partSelfAdmin() {
    // Human-facing title/summary per tool (MCP annotations.title + the Advanced per-tool
    // overrides menu) -- merged into the app's getToolDisplayMeta() aggregator (issue #209).
    return [
        // MCP self-administration (Developer Mode)
        hub_update_mcp_settings: [title: "Update MCP Settings", summary: "Update the MCP app's own settings + device-access scope (Developer Mode)."],
        hub_update_package: [title: "Deploy MCP Package", summary: "Full repair-install of the MCP package at a git ref (Developer Mode)."]
    ]
}


// App cloner / export / import tools (issue #209 modularization). Closure-free
// and separable from the native-RM wizard cluster (now in McpNativeRulesLib).

private Map _appClonerInit(Integer sourceAppId) {
    def resp
    try {
        resp = hubInternalGetRaw("/installedapp/sysAppApi/appCloner/app/${sourceAppId}")
    } catch (Exception e) {
        throw new IllegalStateException("appCloner entry failed for source ${sourceAppId}: ${e.message}. The source app may not exist or appCloner may be unavailable.")
    }
    def loc = resp?.location
    if (!loc) {
        throw new IllegalStateException("appCloner entry returned no Location header for source ${sourceAppId} (status=${resp?.status})")
    }
    // regex covers two redirect shapes seen across firmwares (apps/api/* current, installedapp/configure/* older)
    def m = (loc =~ /\/(?:apps\/api|installedapp\/configure)\/(\d+)/)
    Integer clonerId = m.find() ? (m[0][1] as Integer) : null
    if (clonerId == null) {
        throw new IllegalStateException("Unexpected appCloner Location: ${loc}")
    }
    // Cloner state machine validates `referrer`/`url` against the session that
    // opened the cloner. Use the running hub's IP — hardcoding fails for any
    // other deployment. Falls back to 127.0.0.1 (the loopback the parent app
    // already uses for hubInternal* calls) if location.hub.localIP is null.
    String hubIp = null
    try { hubIp = location?.hub?.localIP?.toString() } catch (Exception ignored) { /* fall through */ }
    if (!hubIp) hubIp = "127.0.0.1"
    String sourceContextUrl = loc.startsWith("http") ? loc : "http://${hubIp}${loc}"
    String configUrl = "http://${hubIp}/installedapp/configure/${clonerId}/main".toString()
    // CRITICAL: follow the redirect target. The cloner's `app(sourceId)`
    // mapping renders the source-context page and sets internal state
    // (state.cloneSource, etc.). Without this GET, the cloner accepts our
    // form POSTs but its state machine never knows what rule to clone, so
    // cloneRuleButton/importNow clicks register but no new rule appears.
    // The Location is OAuth-token-protected (/apps/api/<clonerId>/app/<sourceId>
    // ?access_token=...) — split path + query so HTTPBuilder doesn't URL-encode
    // the `?` and break the access_token lookup.
    def relPath = loc.replaceFirst(/^https?:\/\/[^\/]+/, '')
    def parts = relPath.split(/\?/, 2)
    def justPath = parts[0]
    def query = [:]
    if (parts.length > 1) {
        for (kv in parts[1].split('&')) {
            def eq = kv.indexOf('=')
            if (eq > 0) query[kv.substring(0, eq)] = kv.substring(eq + 1)
        }
    }
    try {
        hubInternalGet(justPath, query)
    } catch (Exception followErr) {
        // Source-context render is load-bearing — clone/import will silently
        // produce no new rule without it. Surface the failure instead of
        // letting the wizard fire and reporting "no new child appeared".
        throw new IllegalStateException("appCloner source-context render failed for source ${sourceAppId} (cloner ${clonerId}): ${followErr.message}. Without this step the cloner state machine never seeds state.cloneSource and subsequent clicks silently produce no rule.")
    }
    pauseExecution(1000)
    // Mimic browser flow: fetch the configPage JSON before any settings POSTs.
    // Without this, file-text widgets (`settings[ruleUpload]`) silently drop
    // their values — the cloner accepts the POST (200, ruleUpload key
    // registered) but stores null. Required for hub_import_native_app.
    try {
        hubInternalGet("/installedapp/configure/json/${clonerId}/main", [:])
    } catch (Exception primeErr) {
        throw new IllegalStateException("appCloner configPage prime failed for cloner ${clonerId}: ${primeErr.message}. Without this step settings[ruleUpload] writes are silently dropped on the import path.")
    }
    return [clonerAppId: clonerId, referrer: sourceContextUrl, configUrl: configUrl]
}

private Map _appClonerSubmitForm(Integer clonerAppId, String currentPage, String formState, String referrer, String configUrl, Map extras = null) {
    // Build a form-refresh body that mirrors the Hubitat UI's POST shape
    // for the cloner's current rendering state. Each formState corresponds
    // to a distinct view the cloner can render at /main:
    //   "source"        — initial source-context view (3 buttons)
    //   "confirmation"  — after cloneRuleButton: "Clone..." + Cancel
    //   "importRule"    — after navigation: name editor + importNow button
    // Each POST must emit the input triplets matching the rendered view —
    // sending the WRONG view's fields stalls the state machine silently.
    def pageBreadcrumbs = currentPage == "main" ? "[]" : '["main"]'
    def body = [
        formAction: "update",
        id: clonerAppId.toString(),
        version: "1",
        appTypeId: "",
        appTypeName: "",
        currentPage: currentPage,
        pageBreadcrumbs: pageBreadcrumbs,
        // The cloner state machine validates that subsequent form POSTs
        // come from the source-authorized session. The UI's referrer is the
        // OAuth-tokened source-context URL (.../apps/api/<cloner>/app/
        // <source>?access_token=...); without it the cloner silently rejects
        // state transitions. Captured during _appClonerInit.
        referrer: referrer ?: "",
        url: configUrl ?: "",
        _cancellable: "false"
    ]
    switch (formState) {
        case "source":
            body["exportRuleButton.type"] = "button"
            body["exportRuleButton.multiple"] = "false"
            body["settings[exportRuleButton]"] = ""
            body["ruleUpload.type"] = "file-text"
            body["ruleUpload.multiple"] = "false"
            body["settings[ruleUpload]"] = ""
            body["cloneRuleButton.type"] = "button"
            body["cloneRuleButton.multiple"] = "false"
            body["settings[cloneRuleButton]"] = ""
            break
        case "confirmation":
            body["cancelUpload.type"] = "button"
            body["cancelUpload.multiple"] = "false"
            body["settings[cancelUpload]"] = ""
            break
        case "importRule":
            // importRule fields are dynamic per source — caller passes them via extras
            break
        default:
            break
    }
    if (extras) body.putAll(extras)
    // A navigation submit (an _action_* marker) is one the UI validates first: refuse it where the
    // cloner's own page would, with the values this POST is about to send overlaid on its current ones.
    if (extras?.keySet()?.any { it.toString().startsWith("_action_") }) {
        def navCfg = null
        try { navCfg = _rmFetchConfigJson(clonerAppId, currentPage) } catch (Exception readExc) {
            // An unreadable page cannot be checked; the cloner's own flow verifies the transition.
            mcpLog("debug", "rm-native", "appCloner: page read for the navigation check on ${currentPage} failed (${readExc.message}); submitting unchecked")
        }
        if (navCfg?.configPage instanceof Map) {
            def navValues = (navCfg.settings instanceof Map) ? new LinkedHashMap(navCfg.settings as Map) : [:]
            for (Map.Entry entry in extras) {
                def k = entry.key
                def v = entry.value
                def m = (k.toString() =~ /^settings\[(.+)\]$/)
                if (m.find()) navValues.put(m[0][1], v)
            }
            def navSchema = _rmCollectInputSchema(navCfg.configPage as Map)
            _requireUiNavigationValid(clonerAppId, "leaving cloner page '${currentPage}'".toString(), navSchema, navValues)
            // The page submits an unset input's defaultValue with the navigation; send what the check accepted.
            def defaults = navSchema.findAll { k, meta ->
                meta?.disabled != true && meta?.type != "button" && meta?.defaultValue != null && _uiValueIsEmpty(navValues.get(k), meta as Map)
            }.collectEntries { k, meta -> [(k): meta.defaultValue] }
            if (defaults) {
                def defaultBody = _rmBuildSettingsBody(clonerAppId, defaults, navSchema)
                defaultBody.remove("id")
                body.putAll(defaultBody)
            }
        }
    }
    // URL-encode manually — HTTPBuilder's Map auto-encoder mangles backslash
    // sequences inside form-urlencoded bodies, so JSON content with embedded
    // `\"` (e.g. canonical exports' multi-select enum encoding) loses its
    // escaping on the wire and the cloner silently rejects the upload.
    StringBuilder sb = new StringBuilder()
    boolean first = true
    for (Map.Entry entry in body) {
        def k = entry.key
        def v = entry.value
        if (!first) sb.append('&')
        first = false
        sb.append(URLEncoder.encode(k.toString(), "UTF-8"))
        sb.append('=')
        sb.append(v == null ? "" : URLEncoder.encode(v.toString(), "UTF-8"))
    }
    def resp = hubInternalPostFormRaw("/installedapp/update/json", sb.toString())
    if (resp == null) {
        // Closure never ran -> network call produced no response. Don't coerce
        // to [:] (export's "no JSON content" error would point at the wrong
        // root cause). Bubble so callers see the real failure.
        throw new IllegalStateException("appCloner POST /installedapp/update/json returned no response (cloner ${clonerAppId}, currentPage=${currentPage}, formState=${formState}). Network call failed before delivering a status.")
    }
    return resp
}

private Integer _appClonerFindActionHrefIdx(Integer clonerAppId, String pageName, String targetActionName) {
    // Hubitat assigns action_href elements a session-scoped numeric id at
    // render time — the same logical button gets a different number on the
    // post-clone confirmation page (low — usually 0) than on the post-upload
    // restore-or-import page (high — observed 55 live), and the cloner's
    // server-side dispatcher matches on the EXACT `<action>|<idx>` pair.
    // Fetch the page JSON and regex out the current id; without this the
    // navigate POST hits a no-op and the importNow click later fires on
    // the wrong page (silent failure — settings persist but no rule).
    def pn = pageName ?: "main"
    String body = null
    try {
        def resp = hubInternalGet("/installedapp/configure/json/${clonerAppId}/${pn}", [:])
        body = (resp instanceof Map) ? (resp.data?.toString()) : (resp?.toString())
    } catch (Exception e) {
        mcpLog("warn", "rm-native", "appCloner: fetch state for href discovery failed: ${e.message}")
        return null
    }
    if (!body) return null
    def m = (body =~ /_action_href_name\|${java.util.regex.Pattern.quote(targetActionName)}\|(\d+)/)
    return m.find() ? (m[0][1] as Integer) : null
}

private void _appClonerCommitImportRule(Integer clonerAppId, Integer sourceAppId, String newName, String referrer, String configUrl) {
    // Step 3: navigate /main → /main/importRule via _action_href_name. The
    // cloner is in either confirmation (post-clone) or restore-or-import
    // (post-upload) state — both expose an importRule action_href but at
    // different session-scoped indices.
    // The cloner re-renders asynchronously after a state-transition POST;
    // poll the page state a few times to give the action_href button time
    // to appear. Fail loudly if it never shows — the import path silently
    // no-ops when this idx is wrong (the very symptom we're fighting).
    Integer hrefIdx = null
    for (int attempt = 0; attempt < 4 && hrefIdx == null; attempt++) {
        if (attempt > 0) pauseExecution(500)
        hrefIdx = _appClonerFindActionHrefIdx(clonerAppId, "main", "importRule")
    }
    if (hrefIdx == null) {
        throw new IllegalStateException("appCloner importRule action_href not found on cloner ${clonerAppId} main page after 4 polls (~2s). The cloner did not transition to the expected confirmation/restore-or-import state — clicking importNow now would silently no-op.")
    }
    _appClonerSubmitForm(clonerAppId, "main", "confirmation", referrer, configUrl, [
        ("_action_href_name|importRule|${hrefIdx}".toString()): "",
        ("params_for_action_href_name|importRule|${hrefIdx}".toString()): ""
    ])
    pauseExecution(500)

    // Step 4 (optional): override the cloner's default new-app label. The
    // setting name is dynamic per source: settings[newName<sourceId>].
    def newNameField = "settings[newName${sourceAppId}]".toString()
    def newNameTypeKey = "newName${sourceAppId}.type".toString()
    def newNameMultKey = "newName${sourceAppId}.multiple".toString()
    if (newName) {
        _appClonerSubmitForm(clonerAppId, "importRule", "importRule", referrer, configUrl, [
            (newNameField): newName,
            (newNameTypeKey): "text",
            (newNameMultKey): "false"
        ])
    }

    // Step 5: click importNow — fires the actual create. The button is
    // named `importNow` regardless of which path (clone vs import) brought
    // us here. Same double-click pattern: first click drops, second commits.
    def btnBody = [
        id: clonerAppId.toString(),
        name: "importNow",
        ("settings[importNow]".toString()): "clicked",
        ("importNow.type".toString()): "button"
    ]
    def finalExtras = [
        (newNameField): (newName ?: ""),
        (newNameTypeKey): "text",
        (newNameMultKey): "false",
        ("importNow.type".toString()): "button",
        ("importNow.multiple".toString()): "false",
        ("settings[importNow]".toString()): ""
    ]
    for (int attempt = 0; attempt < 2; attempt++) {
        def resp = hubInternalPostForm("/installedapp/btn", btnBody)
        if (resp?.status != null && resp.status >= 400) {
            throw new IllegalStateException("appCloner importNow click failed: status=${resp.status}")
        }
        pauseExecution(500)
        // Form refresh on importRule that the UI fires after the click.
        // Body includes newName and importNow fields. The actual create
        // commits on the hub side during the second pass's form refresh.
        _appClonerSubmitForm(clonerAppId, "importRule", "importRule", referrer, configUrl, finalExtras)
        pauseExecution(500)
    }
}

private Map _appClonerSnapshotChildren(Integer parentAppId) {
    // A missing baseline makes existing siblings look newly created. Never start
    // the wizard unless discovery can exclude every app already under the parent.
    try {
        def cfg = _rmFetchConfigJson(parentAppId)
        if (!(cfg.childApps instanceof List)) {
            throw new IllegalStateException("missing childApps list")
        }
        return [ids: cfg.childApps.collect { it?.id?.toString() }.findAll { it }]
    } catch (Exception e) {
        return [success: false, isError: true,
                error: "Cannot read the child-app snapshot for parent ${parentAppId}: ${e.message}".toString(),
                note: "Nothing was created. Restore access to the parent app and retry the clone/import."]
    }
}

private Integer _appClonerDiscoverNewChild(Integer parentAppId, Set<String> preCloneIds, String sourceLabel, String hint) {
    if (parentAppId == null) return null
    def afterCfg
    try {
        afterCfg = _rmFetchConfigJson(parentAppId)
    } catch (Exception e) {
        mcpLog("warn", "rm-native", "appCloner: parent ${parentAppId} fetch after commit failed: ${e.message}")
        return null
    }
    def afterIds = ((afterCfg?.childApps ?: []) as List).collect { it?.id?.toString() }.findAll { it }
    def added = afterIds.findAll { !preCloneIds.contains(it) }
    if (added.isEmpty()) return null
    if (added.size() == 1) return added[0] as Integer
    // Concurrent creations can appear in the same diff. Only an unambiguous
    // requested name identifies our result; a prefix or largest ID is a guess.
    def candidates = (afterCfg.childApps as List).findAll { added.contains(it?.id?.toString()) }
    def hintMatches = hint ? candidates.findAll { (it.label?.toString() ?: "") == hint } : []
    if (hintMatches.size() == 1) return hintMatches[0].id as Integer
    mcpLog("warn", "rm-native", "appCloner: ambiguous new children ${added} for '${hint ?: sourceLabel}'; no app selected")
    return null
}

private boolean _appClonerCleanup(Integer clonerAppId) {
    if (clonerAppId == null) return false
    try {
        _rmForceDeleteApp(clonerAppId)
        mcpLog("debug", "rm-native", "appCloner: cleaned up temporary cloner ${clonerAppId}")
        return true
    } catch (Exception e) {
        mcpLog("warn", "rm-native", "appCloner: cleanup of temporary cloner ${clonerAppId} failed: ${e.message} -- a hidden 'Export/Import/Clone' app may remain; delete via hub_delete_native_app(appId=${clonerAppId}, force=true)")
        return false
    }
}

private void _appClonerClickClone(Integer clonerAppId, String referrer, String configUrl) {
    // Hubitat can swallow the first click; repeat both the click and form refresh.
    def btnBody = [
        id: clonerAppId.toString(),
        name: "cloneRuleButton",
        ("settings[cloneRuleButton]".toString()): "clicked",
        ("cloneRuleButton.type".toString()): "button"
    ]
    for (int attempt = 0; attempt < 2; attempt++) {
        hubInternalPostForm("/installedapp/btn", btnBody)
        pauseExecution(500)
        _appClonerSubmitForm(clonerAppId, "main", "source", referrer, configUrl, null)
        pauseExecution(500)
    }
}

def toolCloneNativeApp(args) {
    requireDestructiveConfirm(args?.confirm as Boolean)
    def _srcRaw = (args?.sourceAppId != null) ? args.sourceAppId : args?.appId
    if (_srcRaw == null) throw new IllegalArgumentException("sourceAppId (or appId) is required")
    def sourceAppId = normalizeRuleId(_srcRaw)
    def newName = args?.newName?.toString()?.trim()

    def sourceCfg
    try {
        sourceCfg = _rmFetchConfigJson(sourceAppId)
    } catch (Exception sourceErr) {
        mcpLog("warn", "rm-native", "hub_clone_native_app: source ${sourceAppId} config fetch failed: ${sourceErr.message}")
        sourceCfg = null
    }
    if (!sourceCfg?.app) {
        throw new IllegalArgumentException("Source app ${sourceAppId} not found or unreadable")
    }
    def sourceLabel = sourceCfg.app.label?.toString()
    Integer parentAppId = null
    try {
        parentAppId = (sourceCfg.app.parentAppId != null) ? (sourceCfg.app.parentAppId.toString() as Integer) : null
    } catch (NumberFormatException ignored) {
        mcpLog("warn", "rm-native", "hub_clone_native_app: source ${sourceAppId} parentAppId not numeric: ${sourceCfg.app.parentAppId}")
    }

    if (parentAppId == null) {
        throw new IllegalArgumentException("Source app ${sourceAppId} has no numeric parentAppId. MCP cannot safely discover its clone; pass a child of the target parent app.")
    }
    _requireUnprotectedAppMutation(parentAppId, "clone or import a child app under")
    Map snapshot = _appClonerSnapshotChildren(parentAppId)
    if (snapshot.isError == true) return snapshot
    def preIds = snapshot.ids as Set

    def initRes = _appClonerInit(sourceAppId)
    Integer clonerAppId = initRes.clonerAppId
    String referrer = initRes.referrer
    String configUrl = initRes.configUrl

    try {
        _appClonerClickClone(clonerAppId, referrer, configUrl)

        // Steps 3-5: navigate importRule, optional rename, click importNow.
        _appClonerCommitImportRule(clonerAppId, sourceAppId, newName, referrer, configUrl)

        Integer newAppId = _appClonerDiscoverNewChild(parentAppId, preIds, sourceLabel, newName)

        String note = newAppId
            ? "Cloned source ${sourceAppId} -> new app ${newAppId}${newName ? " (renamed to '${newName}')" : ""}. Use hub_set_native_app (or hub_set_rule for RM rules) to further customize."
            : "Clone fired but no new child appeared under parent ${parentAppId}. Re-check via hub_list_apps (scope='instances') shortly."
        def result = [
            success: newAppId != null,
            sourceAppId: sourceAppId,
            clonerAppId: clonerAppId,
            newAppId: newAppId,
            note: note
        ]
        if (newAppId == null) {
            // Cloner fired but child discovery returned no match. Surface the
            // structured isError/error fields callers branching on the
            // file-wide error contract expect (handleToolsCall flags isError
            // on the JSON-RPC envelope; LLM clients use it to route retries).
            result.isError = true
            result.error = note
        }
        if (args?.stageDisabled == true && newAppId != null) {
            _appClonerApplyStageDisabled(result, newAppId, args?.__reqT0 as Long)
        } else if (args?.stageDisabled == true) {
            // Discovery-miss: the clone may well EXIST and be live -- the caller
            // asked for stage-inactive and must hear that it never ran.
            _appClonerStagingDiscoveryMiss(result, "clone")
        }
        return result
    } finally {
        // Reap the transient cloner on every path. The cloned rule is already a
        // child of the RM parent (discovered above), not of the cloner, so this
        // is safe. Prevents accumulating hidden 'Export/Import/Clone' apps (BUG-8).
        _appClonerCleanup(clonerAppId)
    }
}

def toolExportNativeApp(args) {
    def _srcRaw = (args?.sourceAppId != null) ? args.sourceAppId : args?.appId
    if (_srcRaw == null) throw new IllegalArgumentException("sourceAppId (or appId) is required")
    def sourceAppId = normalizeRuleId(_srcRaw)
    def saveAs = args?.saveAs?.toString()?.trim()

    def sourceCfg
    try {
        sourceCfg = _rmFetchConfigJson(sourceAppId)
    } catch (Exception sourceErr) {
        mcpLog("warn", "rm-native", "hub_export_native_app: source ${sourceAppId} config fetch failed: ${sourceErr.message}")
        sourceCfg = null
    }
    if (!sourceCfg?.app) {
        throw new IllegalArgumentException("Source app ${sourceAppId} not found or unreadable")
    }
    def sourceLabel = sourceCfg.app.label?.toString() ?: "app-${sourceAppId}"

    def exported = _appClonerExportJson(sourceAppId)
    String jsonContent = exported.json
    Integer clonerAppId = exported.clonerAppId
    def result = [
        success: true,
        sourceAppId: sourceAppId,
        sourceLabel: sourceLabel,
        clonerAppId: clonerAppId,
        contentLength: jsonContent.length(),
        jsonContent: jsonContent,
        note: "Exported source ${sourceAppId} via appCloner. Pass jsonContent to hub_import_native_app to re-create the rule."
    ]
    if (saveAs) {
        try {
            uploadHubFile(saveAs, jsonContent.getBytes("UTF-8"))
            result.savedAs = saveAs
            String hubIp = null
            try { hubIp = location?.hub?.localIP?.toString() } catch (Exception ignored) { /* fall through */ }
            if (hubIp) {
                result.savedUrl = "http://${hubIp}/local/${saveAs}"
            } else {
                // Don't emit a literally-broken http://<HUB_IP>/... URL — flag
                // the lookup failure instead.
                mcpLog("warn", "rm-native", "hub_export_native_app: location.hub.localIP unavailable; savedUrl omitted from result")
            }
        } catch (Exception fileErr) {
            result.saveError = fileErr.message
            mcpLog("warn", "rm-native", "hub_export_native_app: saveAs '${saveAs}' upload failed: ${fileErr.message}")
        }
    }
    return result
}

// Hubitat's App Cloner export of one app: [json, clonerAppId]. Throws when the cloner renders none.
Map _appClonerExportJson(Integer sourceAppId) {
    def initRes = _appClonerInit(sourceAppId)
    Integer clonerAppId = initRes.clonerAppId
    String referrer = initRes.referrer
    String configUrl = initRes.configUrl

    try {
        // Step 2: click exportRuleButton, then capture the form-refresh response.
        // Unlike clone (which writes persistent state and needs a double-click
        // to commit the state transition), export's serialized JSON is rendered
        // INTO the form-refresh POST response itself as
        // configPage.sections[].input[].filecontent — session-keyed and not
        // persisted to the cloner's settings. So we must capture the response
        // body of the same POST that fires the click rather than fetching the
        // cloner's state in a subsequent request (different session = bare view,
        // no JSON). One click is sufficient here.
        def btnBody = [
            id: clonerAppId.toString(),
            name: "exportRuleButton",
            ("settings[exportRuleButton]".toString()): "clicked",
            ("exportRuleButton.type".toString()): "button"
        ]
        hubInternalPostForm("/installedapp/btn", btnBody)
        pauseExecution(500)
        def refreshResp = _appClonerSubmitForm(clonerAppId, "main", "source", referrer, configUrl, null)
        String jsonContent = _appClonerExtractJsonFromResponse(refreshResp?.data)
        if (!jsonContent) {
            // Distinguish an unreadable response body (the struct read path returns
            // data:null on a 2xx when the body read fails mid-stream) from a genuine
            // no-content case, so the operator isn't sent chasing the wrong root cause.
            def reason
            if (refreshResp?.data == null) {
                reason = "the cloner response body was empty/unreadable (status ${refreshResp?.status})"
            } else {
                // A consistent no-content extraction here is a KNOWN failure for a source
                // rule that has a Required Expression: appCloner does not render downloadable
                // export content for such rules, so there is no filecontent to extract. Name
                // that cause and a workaround up front (it is the common trigger), then fall
                // back to the generic wire-format explanation for rules without one.
                reason = "no JSON content could be extracted (looked for configPage.sections[].input[].filecontent). " +
                    "Known cause: if the source rule has a Required Expression, appCloner export currently fails for it -- " +
                    "delete the Required Expression in the Rule Machine UI, export, then re-add it (no MCP tool removes a " +
                    "Required Expression: replaceRequiredExpression only swaps one for another); or edit the rule in place " +
                    "via hub_set_rule instead of export/import. " +
                    "If the rule has NO Required Expression, the cloner wire format may have changed"
            }
            throw new IllegalStateException("appCloner export fired but ${reason} for cloner ${clonerAppId}")
        }
        return [json: jsonContent, clonerAppId: clonerAppId]
    } finally {
        // Reap the transient cloner on every path (success or throw) so repeated
        // exports don't accumulate hidden 'Export/Import/Clone' apps (BUG-8).
        _appClonerCleanup(clonerAppId)
    }
}

private String _appClonerExtractJsonFromResponse(String responseBody) {
    if (!responseBody || !(responseBody instanceof String)) return null
    def parsed
    try { parsed = new groovy.json.JsonSlurper().parseText(responseBody) }
    catch (Exception e) {
        mcpLog("debug", "rm-native", "appCloner: response JSON parse failed: ${e.message}")
        return null
    }
    def sections = (parsed instanceof Map) ? parsed?.configPage?.sections : null
    if (!(sections instanceof List)) return null
    for (section in sections) {
        // The filecontent lives on input[] entries (download-type inputs)
        // and is mirrored in body[] entries. Either works.
        for (key in ["input", "inputs", "body"]) {
            def items = section?."${key}"
            if (!(items instanceof List)) continue
            for (item in items) {
                def fc = (item instanceof Map) ? item.filecontent : null
                if (fc instanceof String && fc.contains("appReplacements") && fc.startsWith("{")) {
                    // Hubitat appCloner over-escapes multi-select enum values
                    // by one extra level when generating the download payload —
                    // its `filecontent` has `\\"` (2 backslashes + quote) where
                    // canonical JSON requires `\"` (1 backslash + quote). The
                    // result is malformed JSON that won't round-trip back into
                    // import. The pattern `\\"` is unreachable in valid JSON
                    // (a literal `\` + `"` would encode as `\\\"`), so we can
                    // safely collapse it.
                    return fc.replace('\\\\"', '\\"')
                }
            }
        }
    }
    return null
}

def toolImportNativeApp(args) {
    requireDestructiveConfirm(args?.confirm as Boolean)
    if (args?.parentHintAppId == null) {
        throw new IllegalArgumentException("parentHintAppId is required (any existing rule's id under the target parent — used to seed the cloner)")
    }
    def parentHintAppId = normalizeRuleId(args.parentHintAppId)
    def newName = args?.newName?.toString()?.trim()

    String jsonContent = args?.jsonContent?.toString()
    if (!jsonContent && args?.fromFile) {
        try {
            def bytes = downloadHubFile(args.fromFile.toString())
            jsonContent = new String(bytes, "UTF-8")
        } catch (Exception e) {
            throw new IllegalArgumentException("Cannot read fromFile '${args.fromFile}': ${e.message}")
        }
    }
    if (!jsonContent) {
        throw new IllegalArgumentException("jsonContent or fromFile is required")
    }

    // Parse to verify shape + extract original source id (for the dynamic
    // newName<id> field on the importRule sub-page).
    def parsed
    try { parsed = new groovy.json.JsonSlurper().parseText(jsonContent) }
    catch (Exception e) { throw new IllegalArgumentException("jsonContent is not valid JSON: ${e.message}") }
    def appReplacements = (parsed instanceof Map) ? parsed.appReplacements : null
    if (!(appReplacements instanceof Map) || appReplacements.isEmpty()) {
        throw new IllegalArgumentException("jsonContent does not contain an appReplacements map — not an appCloner export")
    }
    Integer originalSourceId = null
    try {
        originalSourceId = ((appReplacements.keySet() as List)[0]).toString() as Integer
    } catch (Exception e) {
        throw new IllegalArgumentException("Could not extract original source id from appReplacements: ${e.message}")
    }
    def originalLabel = appReplacements.get(originalSourceId.toString())?.appLabel?.toString()

    // Snapshot pre-import children of the target parent.
    def parentHintCfg
    try {
        parentHintCfg = _rmFetchConfigJson(parentHintAppId)
    } catch (Exception hintErr) {
        mcpLog("warn", "rm-native", "hub_import_native_app: parentHintAppId ${parentHintAppId} fetch failed: ${hintErr.message}")
        parentHintCfg = null
    }
    if (!parentHintCfg?.app) {
        throw new IllegalArgumentException("parentHintAppId ${parentHintAppId} not found or unreadable")
    }
    Integer parentAppId = null
    try {
        parentAppId = (parentHintCfg.app.parentAppId != null) ? (parentHintCfg.app.parentAppId.toString() as Integer) : null
    } catch (NumberFormatException nfe) {
        mcpLog("warn", "rm-native", "hub_import_native_app: parentHintAppId ${parentHintAppId} parentAppId not numeric: ${parentHintCfg.app.parentAppId}; new-child discovery will be skipped")
    }
    if (parentAppId == null) {
        // Without a parent we can't diff children to identify the new rule.
        // Refuse rather than firing the wizard and reporting a false failure.
        throw new IllegalArgumentException("parentHintAppId ${parentHintAppId} has no numeric parentAppId — pass a hint that's a child of the target parent app (e.g. an existing RM rule for an RM import).")
    }
    _requireUnprotectedAppMutation(parentAppId, "clone or import a child app under")
    Map snapshot = _appClonerSnapshotChildren(parentAppId)
    if (snapshot.isError == true) return snapshot
    def preIds = snapshot.ids as Set

    def initRes = _appClonerInit(parentHintAppId)
    Integer clonerAppId = initRes.clonerAppId
    try {
        // For import the cloner's state machine validates session against the
        // local config URL (the page the user uploaded from). The OAuth source-
        // context URL the init returns is correct for clone (that's where the
        // cloneRuleButton lives) but trips a session check on the import path.
        // Verified live: same wire shape with OAuth referrer → no rule created;
        // with local-URL referrer → rule created. Use configUrl for both.
        String referrer = initRes.configUrl
        String configUrl = initRes.configUrl

        // Step 2: stage the JSON via settings[ruleUpload]= — single POST. The
        // UI fires this exactly once (file picker change → FileReader → one
        // jsonSubmit). A second pass is harmful here: the cloner has already
        // transitioned to restore-or-import state and the source-state form
        // body no longer matches.
        _appClonerSubmitForm(clonerAppId, "main", "source", referrer, configUrl, [
            ("settings[ruleUpload]".toString()): jsonContent
        ])
        // Cloner needs ~2s to JSON-parse large uploads + transition to
        // restore-or-import; <1s races on multi-KB exports.
        pauseExecution(2000)

        // Steps 3-5: navigate importRule, optional rename, click importNow.
        _appClonerCommitImportRule(clonerAppId, originalSourceId, newName, referrer, configUrl)

        Integer newAppId = _appClonerDiscoverNewChild(parentAppId, preIds, originalLabel, newName)

        String note = newAppId
            ? "Imported '${originalLabel ?: 'app'}' as new app ${newAppId}${newName ? " (renamed to '${newName}')" : ""}. Use hub_set_native_app (or hub_set_rule for RM rules) to further customize."
            : "Import fired but no new child appeared under parent ${parentAppId}. Re-check via hub_list_apps (scope='instances') shortly."
        def result = [
            success: newAppId != null,
            clonerAppId: clonerAppId,
            newAppId: newAppId,
            originalSourceId: originalSourceId,
            originalLabel: originalLabel,
            contentLength: jsonContent.length(),
            note: note
        ]
        if (newAppId == null) {
            // Wizard fired but child discovery returned no match. Same shape as
            // toolCloneNativeApp on the soft-failure path — see comment there.
            result.isError = true
            result.error = note
        }
        if (args?.stageDisabled == true && newAppId != null) {
            _appClonerApplyStageDisabled(result, newAppId, args?.__reqT0 as Long)
        } else if (args?.stageDisabled == true) {
            _appClonerStagingDiscoveryMiss(result, "import")
        }
        return result
    } finally {
        // Reap the transient cloner on every path. The imported rule is already a
        // child of the target parent (discovered above), not of the cloner.
        // Prevents accumulating hidden 'Export/Import/Clone' apps (BUG-8).
        _appClonerCleanup(clonerAppId)
    }
}

private Map _appClonerStagePlan(Integer newAppId) {
    // Enumerate every descendant BEFORE disabling anything: a parent's flag can
    // hide deeper levels. The primary traversal is recursive; the fallback is BFS.
    // Child Button Rules can subscribe independently, so staging only the parent
    // would leave live automation behind. A clone/import remains active until disabled.
    List failures = []
    List targets = []
    // Primary enumeration: ONE /hub2/appsList read carries the complete nested
    // app tree -- no per-node configPage render (which for a cloned Button
    // Controller with N children turned one read into N+1 expensive renders on
    // the same per-app load counters the sticky limiter watches).
    try {
        def responseText = hubInternalGet("/hub2/appsList")
        def parsed = new groovy.json.JsonSlurper().parseText(responseText)
        Map root = null
        def findNode
        findNode = { List nodes ->
            for (def n : (nodes ?: [])) {
                if (n?.data?.id?.toString() == newAppId.toString()) { root = n; return }
                findNode(n?.children as List)
                if (root != null) return
            }
        }
        findNode(parsed?.apps as List)
        if (root == null) throw new IllegalStateException("app ${newAppId} not present in /hub2/appsList")
        Set visited = [] as Set
        def collect
        collect = { Map node ->
            def nid = node?.data?.id?.toString()
            if (!nid?.isInteger() || visited.contains(nid)) return
            visited << nid
            targets << nid.toInteger()
            (node?.children as List ?: []).each { c -> if (c instanceof Map) collect(c) }
        }
        collect(root)
    } catch (Exception treeErr) {
        // Fallback: per-node configure/json BFS (the pre-appsList mechanism).
        mcpLog("warn", "rm-native", "stageDisabled: /hub2/appsList enumeration failed (${treeErr.message}) -- falling back to per-node configure/json BFS")
        targets = []
        Set visited = [] as Set
        List queue = [newAppId]
        while (queue) {
            Integer tid = queue.remove(0)
            if (visited.contains(tid)) continue
            visited << tid
            targets << tid
            try {
                def cfg = _rmFetchConfigJson(tid)
                for (c in ((cfg?.childApps ?: []) as List)) {
                    def cid = c?.id?.toString()
                    if (cid?.isInteger()) queue << cid.toInteger()
                }
            } catch (Exception childErr) {
                failures << [appId: tid, kind: "childEnumeration", error: "child enumeration failed for app ${tid}: ${childErr.message} -- its DESCENDANTS (if any) were not discovered and were NOT disabled; app ${tid} itself is still attempted below"]
            }
        }
    }
    return [targets: targets.unique(), failures: failures]
}

private Map _appClonerDisableTargets(List targets, Long reqT0, List staged, List failures) {
    // Each disable includes read-back. Retain unattempted IDs when the budget
    // expires so the result/checkpoint keeps the committed app and a safe remedy.
    List stageRemaining = []
    for (int i = 0; i < targets.size(); i++) {
        if (i > 0 && _timeBudgetExceeded(reqT0)) {
            stageRemaining = targets.subList(i, targets.size()).collect { it }
            break
        }
        def tid = targets[i]
        def dres
        try { dres = toolSetAppDisabled([appId: tid, disabled: true]) }
        catch (Exception dErr) { dres = [success: false, error: dErr.message ?: dErr.toString()] }
        if (dres?.success == true) staged << tid
        else failures << [appId: tid, kind: "disable", error: dres?.error ?: "disable read-back mismatch"]
    }
    return [staged: staged.unique(), failures: failures, remaining: stageRemaining]
}

private void _appClonerFinishStaging(Map result, Integer newAppId, Map outcome) {
    // Staging is the requested safety property, but creation already committed.
    // Report partial failure with a disable remedy; retrying creation makes duplicates.
    List staged = outcome.staged
    List failures = outcome.failures
    List stageRemaining = outcome.remaining
    result.stagedDisabled = staged
    if (failures || stageRemaining) {
        if (failures) result.stageFailures = failures
        if (stageRemaining) result.stageRemaining = stageRemaining
        result.partial = true
        result.success = false
        result.isError = true
        def newAppItselfFailed = failures.any { it.kind == "disable" && it.appId == newAppId }
        def remainderText = stageRemaining ? "Response budget ran out before ${stageRemaining.size()} app(s) were disabled (${stageRemaining.join(', ')}). " : ""
        result.error = "stageDisabled did NOT fully land: ${failures.size()} failure(s)${stageRemaining ? " + ${stageRemaining.size()} not yet attempted" : ""} -- see stageFailures/stageRemaining. ${newAppItselfFailed ? "The NEW APP ITSELF (${newAppId}) is still ENABLED and live. " : ""}${remainderText}The clone/import DID commit (newAppId=${newAppId}) -- do NOT re-issue this call (that would create a duplicate app); disable the listed apps via hub_set_app_disabled(appId=<id>, disabled=true) instead."
        result.note = "${result.note} STAGING ${stageRemaining ? 'INCOMPLETE' : 'FAILED'} -- see error/stageFailures."
    } else {
        result.note = "${result.note} Staged inactive: ${staged.size()} app(s) disabled (the new app${staged.size() > 1 ? ' + descendants' : ''}); re-enable with hub_set_app_disabled(disabled=false)."
    }
}

private void _appClonerApplyStageDisabled(Map result, Integer newAppId, Long reqT0 = null) {
    Map plan = _appClonerStagePlan(newAppId)
    Map outcome = _appClonerDisableTargets(plan.targets as List, reqT0, [], plan.failures as List)
    _appClonerFinishStaging(result, newAppId, outcome)
}

private void _appClonerStagingDiscoveryMiss(Map result, String operationLabel) {
    result.stagedDisabled = []
    result.success = false
    result.isError = true
    result.error = "${result.error ?: ''} stageDisabled was requested but could NOT run: no newAppId was discovered. If the ${operationLabel} did land, it is ENABLED and live -- find it via hub_list_apps (scope='instances') and disable it with hub_set_app_disabled. Do NOT re-issue creation: it may already have committed.".toString().trim()
}

private Map _appClonerCappedStaging(Map cp) {
    // The latest returned checkpoint includes the final slice's disables. The
    // generic MRTR aggregate has no cloner ledger, and terminal storage drops cp.
    Map result = (cp.baseResult instanceof Map) ? ([:] + cp.baseResult) : [:]
    _appClonerFinishStaging(result, cp.newAppId as Integer, [
        staged: (cp.stagedDisabled ?: []) as List,
        failures: (cp.stageFailures ?: []) as List,
        remaining: (cp.stageTargets ?: []) as List
    ])
    return result
}

private Map _rmReadBackupSnapshot(Map entry) {
    def fileName = entry.fileName
    def jsonBytes
    try {
        jsonBytes = downloadHubFile(fileName)
    } catch (Exception e) {
        throw new IllegalArgumentException("Cannot read RM backup file '${fileName}': ${e.message}")
    }
    def snapshot
    try {
        snapshot = new groovy.json.JsonSlurper().parseText(new String(jsonBytes, "UTF-8"))
    } catch (Exception e) {
        throw new IllegalArgumentException("Cannot parse RM backup file '${fileName}': ${e.message}")
    }
    if (snapshot?.schemaVersion != 1) {
        throw new IllegalArgumentException("Unsupported RM backup schemaVersion: ${snapshot?.schemaVersion} (expected 1)")
    }

    return snapshot as Map
}

// Hubitat's App Cloner export of an app, kept in its backup so a restore can bring back app
// state (triggers, actions, IF conditions) that a settings replay cannot. A rule with a Required
// Expression is never exported (the cloner renders nothing for it).
Map _rmNativeExportForBackup(Integer appId) {
    try {
        return [json: _appClonerExportJson(appId).json]
    } catch (Exception e) {
        mcpLog("warn", "rm-native", "Backup for app ${appId}: App Cloner export failed (${e.message}); this backup restores by settings replay")
        return [error: e.message ?: e.toString()]
    }
}

// Restore through Hubitat's own App Cloner import: an exact copy (settings and app state) as a NEW
// app, then the old app is deleted. Returns [fallback: reason] for the settings replay when the
// export cannot be used: unparseable, no Rule Machine rule left to seed the import, or a device that
// no longer exists (an import would not reuse it). Throws IllegalArgumentException, before anything
// is created, when the old rule cannot be deleted because of app protection.
// The copy an earlier native restore of this backup produced, when it still exists: returned rather
// than importing or recreating again. Null when there is none.
Map _rmPriorNativeCopy(Map entry, Integer savedId, boolean exists, String fileName) {
    def recorded = entry?.restoredAppId
    Integer priorCopy = recorded?.toString()?.isInteger() ? (recorded.toString() as Integer) : null
    if (priorCopy == null || priorCopy == savedId) return null
    // The hub answers {} for an id that no longer exists.
    if (!_rmReadRuleState(priorCopy)) return null
    def out = [type: "rm-rule", ruleId: priorCopy, originalRuleId: savedId, restoredVia: "nativeImport", backupFile: fileName, alreadyRestored: true]
    if (exists) {
        out.success = false
        out.partial = true
        out.error = "This backup was already imported as app ${priorCopy}, and rule ${savedId} still exists.".toString()
        out.note = "Nothing was created. Keep one of the two: delete rule ${savedId} and enable app ${priorCopy} (hub_set_app_disabled(disabled=false)), or delete app ${priorCopy}, then retry the restore.".toString()
    } else if (entry?.restoredKeepDisabled != true && _rmIsAppDisabled(priorCopy) != false) {
        // A copy the restore meant to enable is disabled (the earlier run stopped before its re-enable),
        // or its state could not be read.
        Boolean disabled = _rmIsAppDisabled(priorCopy)
        out.success = false
        out.partial = true
        out.error = (disabled == true ?
            "This backup was already restored as app ${priorCopy}, but that app is still disabled." :
            "This backup was already restored as app ${priorCopy}, but whether that app is enabled could not be read.").toString()
        out.note = "Nothing was created. Check app ${priorCopy} with hub_list_apps(scope='instances') and enable it with hub_set_app_disabled(disabled=false) if it is disabled.".toString()
    } else {
        out.success = true
        out.note = "This backup was already restored as app ${priorCopy}; nothing was created. To restore it again, delete app ${priorCopy} first.".toString()
    }
    return out
}

private Map _rmRestoreViaNativeImport(Map snapshot, Integer savedId, boolean exists, String fileName, String backupKey = null) {
    def parsed
    try { parsed = new groovy.json.JsonSlurper().parseText(snapshot.nativeExport.toString()) } catch (Exception e) {
        mcpLog("warn", "rm-native", "Restore of app ${savedId}: the backup's App Cloner export does not parse (${e.message}); restoring by settings replay")
        return [fallback: "the backup's App Cloner export could not be parsed"]
    }
    def gone = [:]
    def deadDevices = ((parsed?.deviceReplacements instanceof Map) ? (parsed.deviceReplacements as Map).keySet() : [])
        .collect { it.toString() }.findAll { _rmDeviceGone(it, gone) }
    if (deadDevices) {
        mcpLog("info", "rm-native", "Restore of app ${savedId}: device(s) ${deadDevices} no longer exist, so the App Cloner import is skipped for the settings replay")
        return [fallback: "device(s) ${deadDevices.join(', ')} named by the App Cloner export no longer exist".toString()]
    }
    Integer hint = exists ? savedId : null
    if (hint == null) {
        try {
            def kids = _appClonerSnapshotChildren(_discoverParentAppId(snapshot?.appType ?: "rule_machine"))
            hint = (kids?.ids ?: []).collect { it.toString() }.find { it.isInteger() }?.toInteger()
        } catch (Exception e) {
            mcpLog("warn", "rm-native", "Restore of app ${savedId}: finding a Rule Machine rule to seed the import failed (${e.message})")
            hint = null
        }
        if (hint == null) return [fallback: "no Rule Machine rule was found to seed the App Cloner import"]
    }
    // The old rule is deleted after the import, so its protection is checked before anything is created.
    if (exists) {
        try { _requireUnprotectedAppDeletion(savedId) } catch (IllegalArgumentException protExc) {
            throw new IllegalArgumentException("Cannot restore rule ${savedId} as a new copy, because the old rule could not then be deleted: ${protExc.message} Pass preserveRuleId:true to restore it in place instead.".toString(), protExc)
        }
    }
    def label = snapshot?.appLabel ?: "rule ${savedId}"
    def imp
    try {
        imp = toolImportNativeApp([jsonContent: snapshot.nativeExport, parentHintAppId: hint, stageDisabled: true, confirm: true])
    } catch (Exception impExc) {
        mcpLog("error", "rm-native", "Restore of app ${savedId}: the App Cloner import threw (${impExc.message})")
        imp = [success: false, clonerAppId: -1, error: impExc.message ?: impExc.toString()]
    }
    Integer newId = imp?.newAppId as Integer
    if (newId == null) {
        def out = [success: false, type: "rm-rule", ruleId: savedId, originalRuleId: savedId, restoredVia: "nativeImport", backupFile: fileName]
        if (imp?.clonerAppId == null) {
            // The import never started, so nothing was created.
            out.error = "The App Cloner import of the backup could not start: ${imp?.error ?: imp?.note}".toString()
            out.note = (exists ? "Nothing was created or deleted. Retry, or pass preserveRuleId:true to restore rule ${savedId} in place by settings replay." :
                "Nothing was created. Retry the restore.").toString()
            return out
        }
        // The import ran, but its copy was not found: it may exist, enabled and running.
        out.partial = true
        out.error = "The App Cloner import of the backup ran, but its new app could not be identified: ${imp?.error ?: imp?.note}".toString()
        out.note = ("A copy labelled '${label}' may now exist under Rule Machine, enabled. Find it with hub_list_apps(scope='instances') and disable or delete it before anything else. " +
            (exists ? "Rule ${savedId} was NOT deleted. " : "") + "Do not retry the restore until you have checked.").toString()
        return out
    }
    if (imp?.success != true) {
        // A copy exists but may not be disabled, so the caller decides what stays.
        def failed = [success: false, partial: true, type: "rm-rule", ruleId: savedId, originalRuleId: savedId, importedAppId: newId,
                      restoredVia: "nativeImport", backupFile: fileName,
                      error: "The backup was imported as app ${newId}, but staging it failed: ${imp?.error ?: imp?.note}".toString(),
                      note: (exists ?
                          "Rule ${savedId} was NOT deleted, and app ${newId} may be running alongside it. Delete app ${newId} (hub_delete_native_app) to go back to rule ${savedId}, or delete rule ${savedId} to keep the copy. Do not retry the restore before one of them is gone." :
                          "App ${newId} is the restored rule, but it may not be disabled as intended. Check it with hub_get_app_config(appId=${newId}); do not retry the restore, which would create another copy.").toString()]
        if (imp?.stageFailures) failed.stageFailures = imp.stageFailures
        return failed
    }
    // The copy replaces the old rule only once it matches the backup: same triggers and actions, not broken.
    String mismatch = _rmNativeCopyMismatch(newId, snapshot)
    if (mismatch) {
        def dropped
        try { dropped = toolDeleteNativeApp([appId: newId, force: true, confirm: true])?.success == true } catch (Exception dropExc) {
            mcpLog("warn", "rm-native", "Restore of app ${savedId}: deleting the mismatched copy ${newId} threw (${dropExc.message})")
            dropped = false
        }
        def failed = [success: false, type: "rm-rule", ruleId: savedId, originalRuleId: savedId, restoredVia: "nativeImport", backupFile: fileName,
                      error: "The App Cloner copy of the backup does not match it: ${mismatch}.".toString(),
                      note: ((dropped ? "The copy was deleted" : "The copy is app ${newId}, left disabled; delete it with hub_delete_native_app") +
                          (exists ? ", and rule ${savedId} was not changed." : ".") +
                          (exists ? " Pass preserveRuleId:true to restore by settings replay instead." : "")).toString()]
        if (!dropped) { failed.partial = true; failed.importedAppId = newId }
        return failed
    }
    // A rule disabled now stays disabled through the restore.
    boolean liveDisabled = exists && _rmIsAppDisabled(savedId) == true
    _rmRecordNativeRestore(backupKey, newId, liveDisabled || snapshot?.configJson?.app?.disabled == true)
    def out = [success: true, type: "rm-rule", ruleId: newId, originalRuleId: savedId, recreated: true,
               restoredVia: "nativeImport", backupFile: fileName]
    if (exists) {
        def del
        try { del = toolDeleteNativeApp([appId: savedId, confirm: true]) } catch (Exception delExc) {
            del = [success: false, error: delExc.message ?: delExc.toString()]
        }
        if (del?.success != true) {
            out.success = false
            out.partial = true
            out.error = "The backup was imported as app ${newId}, but the old rule ${savedId} could not be deleted: ${del?.hubMessage ?: del?.error}".toString()
            out.note = "App ${newId} is the restored copy and is left DISABLED so the two never run together. Delete rule ${savedId} (hub_delete_native_app, force:true if it has children), then enable ${newId} with hub_set_app_disabled(disabled=false).".toString()
            return out
        }
        out.replacedRuleBackup = del?.backup?.backupKey
    }
    // The import is staged disabled; leave it disabled when the app was disabled at backup time or before the restore.
    def reenableFailed = []
    if (liveDisabled) out.leftDisabled = true
    if (snapshot?.configJson?.app?.disabled != true && !liveDisabled) {
        def failed = (imp.stagedDisabled ?: [newId]).findAll { id ->
            try { toolSetAppDisabled([appId: id, disabled: false])?.success != true } catch (Exception enableExc) {
                mcpLog("warn", "rm-native", "Restore of app ${savedId}: re-enabling app ${id} threw (${enableExc.message})")
                true
            }
        }
        if (failed) {
            reenableFailed = failed
            out.success = false
            out.partial = true
            out.error = "The backup was restored as app ${newId}, but app(s) ${failed} could not be re-enabled.".toString()
        }
    }
    out.note = ("Restored with Hubitat's App Cloner import as a NEW app ${newId} -- an exact copy of the backup, triggers and actions included" +
        (exists ? "; the old rule ${savedId} was deleted" : "") +
        ". Update anything that referenced rule ${savedId} (Run Rule actions, dashboards)." +
        (exists ? " Pass preserveRuleId:true to restore in place by settings replay instead." : "") +
        (reenableFailed ? " Re-enable app(s) ${reenableFailed} with hub_set_app_disabled(disabled=false)." : "") +
        (liveDisabled ? " Rule ${savedId} was disabled, so app ${newId} is left disabled too." : "")).toString()
    return out
}

// Null when the imported copy matches the backup's Rule Machine state (trigger and action ids, not
// broken); otherwise why not. Unreadable counts as a mismatch, since the old rule goes next.
String _rmNativeCopyMismatch(Integer copyId, Map snapshot) {
    def snap = [:]
    for (it in (snapshot?.statusJson?.appState ?: [])) { if (it instanceof Map && it.name != null) snap.put(it.name.toString(), it.value) }
    def copy = _rmReadRuleState(copyId)
    if (!copy) return "app ${copyId}'s state could not be read".toString()
    if (copy.broken == true) return "app ${copyId} reads as broken".toString()
    def keys = { m -> (m instanceof Map) ? (m as Map).keySet().collect { it.toString() }.sort() : [] }
    def list = { l -> (l instanceof List) ? (l as List).collect { it.toString() } : [] }
    def problems = []
    if (keys(copy.capabstrue) != keys(snap.capabstrue)) problems << "triggers ${keys(copy.capabstrue)} vs the backup's ${keys(snap.capabstrue)}".toString()
    if (list(copy.actionList) != list(snap.actionList)) problems << "actions ${list(copy.actionList)} vs the backup's ${list(snap.actionList)}".toString()
    return problems ? problems.join("; ") : null
}

// Record on the backup entry the app a native restore created (and whether it is meant to stay
// disabled), so a retry returns it instead of importing again.
void _rmRecordNativeRestore(String backupKey, Integer newId, boolean keepDisabled = false) {
    if (!backupKey) return
    try {
        _withBackupLock("record restore of ${backupKey}") {
            Map manifest = _itemBackupManifest()
            if (manifest[backupKey] instanceof Map) {
                (manifest[backupKey] as Map).restoredAppId = newId
                (manifest[backupKey] as Map).restoredKeepDisabled = keepDisabled
                _commitItemBackupManifest(manifest)
            }
        }
    } catch (Exception e) {
        mcpLog("warn", "rm-native", "Recording that backup ${backupKey} was restored as app ${newId} failed (${e.message}); a retry would import it again")
    }
}

private Map _rmRestoreFromBackup(Map entry, Map preparedSnapshot = null, boolean preserveRuleId = true, String backupKey = null) {
    def fileName = entry.fileName
    Map snapshot = preparedSnapshot != null ? preparedSnapshot : _rmReadBackupSnapshot(entry)
    def savedId = snapshot.ruleId as Integer
    def savedSettings = (snapshot?.configJson?.settings ?: [:]) as Map
    def savedLabel = snapshot?.appLabel

    // Backup snapshots from before the appType-aware code path stored
    // type="rm-rule" without an appType field. Treat those as RM (the
    // only app type the original snapshots covered) for the recreate
    // path. Future snapshots can carry an explicit savedAppType field.
    def savedAppType = snapshot?.appType ?: "rule_machine"
    if (savedAppType == "visual_rule") {
        // Visual Rules don't speak the classic createchild + settings-replay protocol below
        // (incl. the configure/json exists-probe, which Vue children may not serve); their
        // snapshots carry the captured VRB definition and replay through the ruleBuilder
        // endpoints (impl in McpVisualRulesLib).
        return _vrbRestoreFromSnapshot(snapshot, fileName?.toString())
    }

    _requireUnprotectedAppMutation(savedId, "restore settings for")
    def exists = true
    try {
        _rmFetchConfigJson(savedId)
    } catch (Exception e) {
        def liveApps = _collectLiveApps()
        if (liveApps == null || liveApps.containsKey(savedId)) {
            String detail = liveApps == null ? "the app inventory could not confirm its absence" : "it is still present in the app inventory"
            mcpLog("warn", "rm-native", "Restore target ${savedId} could not be inspected (${e.message}); ${detail}")
            return [success: false, type: "rm-rule", ruleId: savedId, originalRuleId: savedId,
                    error: "Cannot restore rule ${savedId}: its configuration could not be read and ${detail}.",
                    note: "No replacement was created and no settings were changed. Inspect hub_list_apps and hub_get_app_config(appId=${savedId}), then retry when the rule is readable or its deletion is confirmed."]
        }
        exists = false
    }
    def reg = _appTypeRegistry()[savedAppType]
    if (!reg) {
        throw new IllegalArgumentException("Backup references unknown appType '${savedAppType}'. Supported: ${_appTypeRegistry().keySet().join(', ')}")
    }
    String nativeSkipped = null
    def priorCopy = _rmPriorNativeCopy(entry, savedId, exists, fileName?.toString())
    if (priorCopy && (!exists || !preserveRuleId)) return priorCopy
    // A deleted rule gets a new id either way, so it comes back through the exact copy when the backup has one.
    if ((!preserveRuleId || !exists) && snapshot?.nativeExport) {
        if (savedAppType != "rule_machine") {
            nativeSkipped = "App Cloner restore is used for Rule Machine rules only"
        } else {
            def nativeOut = _rmRestoreViaNativeImport(snapshot, savedId, exists, fileName?.toString(), backupKey)
            if (nativeOut?.fallback) nativeSkipped = nativeOut.fallback.toString()
            else return nativeOut
        }
    }

    // Finish the way the app type commits: Rule Machine's updateRule, or for an app without that
    // button (Basic Rule, Button Controller) the page's Done -- clicking updateRule there stores it
    // as a pending action delete and the page then fails to load.
    String commitButton = reg.containsKey("commitButton") ? reg.commitButton : _resolveCommitButton(snapshot?.configJson?.app?.appType?.name?.toString())
    def ruleId
    if (exists) {
        ruleId = savedId
        // A disabled app renders no page, and a settings write against it reports success having
        // changed nothing -- the restore would then claim "restored in place". Same gate as an edit.
        _rmRejectDisabledAppEdit(ruleId, "restore")
    } else {
        def parentId = _discoverParentAppId(savedAppType)
        _requireUnprotectedAppMutation(parentId, "restore a child app under")
        ruleId = _rmCreateChildApp(parentId, reg.namespace, reg.appName)
        try {
            def firstPage = _rmFetchConfigJson(ruleId)
            def firstSchema = _rmCollectInputSchema(firstPage?.configPage)
            def seedBody = _rmBuildSettingsBody(ruleId, [origLabel: savedLabel ?: "restored-app-${savedId}"], firstSchema)
            hubInternalPostForm("/installedapp/update/json", seedBody)
            if (commitButton) _rmClickAppButton(ruleId, commitButton)
        } catch (Exception e) {
            try { _rmForceDeleteApp(ruleId) } catch (Exception ce) {
                mcpLog("warn", "rm-native", "_rmRestoreFromBackup: orphan cleanup of newly-created app ${ruleId} failed after recreate error (${ce.message}) -- app may be left in an empty-label state; clean up manually via hub_delete_native_app(appId=${ruleId})")
            }
            throw new IllegalArgumentException("Restore failed during app recreate (appType=${savedAppType}): ${e.message}")
        }
    }

    // Schema sourcing: configPage covers only the main page, but classic
    // apps (especially RM) keep most device pickers on sub-pages whose
    // schema isn't in the main configPage. Without their type+multiple
    // metadata, _rmBuildSettingsBody can't emit the .multiple=true
    // sidecar — exactly the poisoning we're trying to avoid. Supplement
    // from the snapshotted statusJson.appSettings, which carries the
    // live marshal flags for every setting regardless of which page
    // declared it. Page-derived entries take precedence (they include
    // `required` and other UI-only metadata) so this is additive only.
    def savedSchema = _rmCollectInputSchema(snapshot?.configJson?.configPage) ?: [:]
    for (s in snapshot?.statusJson?.appSettings) {
        def n = s?.name?.toString()
        if (n && !savedSchema.containsKey(n)) {
            savedSchema.put(n, [
                name: n,
                type: s?.type?.toString(),
                multiple: s?.multiple == true
            ])
        }
    }
    // Two steps that fail differently: a rejected replay leaves the rule as it was (nothing is
    // committed on a 4xx/5xx), while a failed updateRule click after a committed replay leaves the
    // restored settings in place with subscriptions not yet rebuilt. Name the step, and log it --
    // a caller reading only the envelope could not tell the two apart (seen live: a 500 on rule 37).
    // A button input has no persisted value: RM keeps its row buttons (edit/insert/cut/disable, and
    // the bare "1"/"2"/"3" condition-row buttons) in settings with an empty value, and replaying
    // those through the update endpoint is at best a no-op and at worst a press. The replay of one
    // such snapshot answered 500 on a live 2.5.1.177 hub; the same shapes replay cleanly without
    // the button rows. Replay only value-bearing inputs.
    def replaySettings = savedSettings.findAll { k, v -> savedSchema.get(k.toString())?.type != "button" }
    def skippedButtons = (savedSettings.keySet() - replaySettings.keySet()).collect { it.toString() }.sort()
    // A device picker is snapshotted as configure/json renders it, an {id: label} map.
    // statusJson's deviceIdsForDeviceList (the id list the hub stores for the picker) is used when
    // the snapshot carries it; otherwise the map's keys are the id list.
    // An EMPTY id list is not authoritative (every sibling reader falls back on empty or absent):
    // trusting it would post an empty picker and report the key applied.
    def liveDeviceIds = [:]
    for (st in snapshot?.statusJson?.appSettings) {
        def n = st?.name?.toString()
        if (n && st?.deviceIdsForDeviceList instanceof List && st.deviceIdsForDeviceList) liveDeviceIds.put(n, st.deviceIdsForDeviceList)
    }
    def skippedMaps = []
    // A device deleted since the backup must not go back into a picker: RM's pages then dereference
    // a null device and stop rendering (seen live on fw 2.5.2.129).
    def deviceGone = [:]
    def skippedDevices = []
    replaySettings = replaySettings.collectEntries { k, v ->
        String key = k.toString()
        boolean isPicker = _isDevicePickerType(savedSchema.get(key)?.type)
        if (!isPicker) {
            // A Map that is NOT a device picker cannot be replayed through the settings endpoint as
            // its keys; rewriting it silently would be a value change reported as applied.
            if (v instanceof Map) { skippedMaps << key; return [:] }
            return [(key): v]
        }
        def ids = liveDeviceIds.containsKey(key) ? liveDeviceIds.get(key) : _devicePickerIds(v)
        if (ids instanceof List) {
            ids = ids.collect { it?.toString() }
            def gone = ids.findAll { _rmDeviceGone(it, deviceGone) }
            if (gone) {
                skippedDevices << [key: key, ids: gone]
                ids = ids - gone
                if (!ids) return [:]
            }
        }
        return [(key): ids]
    }
    boolean isRm = savedAppType == "rule_machine"
    def settingsCleared = []
    def clearMiss = null
    def commitMiss = null
    String step = "settings replay"
    try {
        _rmUpdateAppSettings(ruleId, replaySettings, savedSchema)
        if (exists && !isRm) {
            // A replay writes back only the backup's keys; a key the app gained later would stay and
            // mix with the restored values. Rule Machine's own removal handles its rows (reconcile below).
            try { settingsCleared = _rmClearSettingsNotInBackup(ruleId, savedSettings) } catch (Exception clearExc) {
                mcpLog("warn", "rm-native", "restore of app ${ruleId}: emptying settings the backup did not have failed (${clearExc.message})")
                clearMiss = clearExc.message ?: clearExc.toString()
            }
        }
        if (commitButton) {
            step = "the final ${commitButton} click".toString()
            _rmClickAppButton(ruleId, commitButton)
        } else {
            step = "the closing Done"
            def done = _rmSubmitMainPageDone(ruleId)
            if (done?.done != true) commitMiss = done?.reason ?: "the page's Done did not commit"
        }
    } catch (Exception e) {
        mcpLog("error", "rm-native", "restore of rule ${ruleId} from ${fileName} failed during ${step}: ${e.message}")
        return [
            success: false,
            type: "rm-rule",
            ruleId: ruleId,
            originalRuleId: savedId,
            failedStep: step,
            restoredVia: "settingsReplay",
            nativeImportSkipped: nativeSkipped,
            error: "Restore applied partially; failed during ${step}: ${e.message}",
            note: (step == "settings replay"
                ? "Rule ${ruleId} exists but may have incomplete settings. Inspect with hub_get_app_config(appId=${ruleId}) and compare against hub_get_backup(backupKey) before retrying."
                : (commitButton == "updateRule"
                    ? "The settings were replayed but the rule's updateRule did not fire, so its subscriptions may still reflect the pre-restore state. Open the rule and click Update Rule, or call hub_set_rule(appId=${ruleId}, button='updateRule')."
                    : "The settings were replayed but the app's ${commitButton ?: 'Done'} did not run, so its subscriptions may still reflect the pre-restore state. Open the app and click ${commitButton ?: 'Done'}, or call hub_set_native_app(appId=${ruleId}${commitButton ? ", button='" + commitButton + "'" : ''}).")).toString()
        ]
    }

    // A skipped BUTTON is nothing lost -- a button input holds no state. A skipped MAP is saved
    // state this restore did not put back, so the envelope says partial: a caller that reads
    // success:true and stops would leave the rule short of its snapshot without being told.
    def out = [
        success: true,
        type: "rm-rule",
        ruleId: ruleId,
        originalRuleId: savedId,
        recreated: !exists,
        restoredVia: "settingsReplay",
        backupFile: fileName,
        settingsApplied: replaySettings.keySet().toList(),
        settingsSkipped: skippedButtons.collect { key -> [key: key, reason: "button input excluded from replay"] }
            + skippedMaps.collect { key -> [key: key, reason: "map value without a device-picker schema; not replayable through the settings endpoint"] }
            + skippedDevices.collect { sd -> [key: sd.key, reason: "device(s) ${sd.ids.join(', ')} no longer exist on the hub; left out of the replay".toString()] },
        note: exists ? "Settings restored in place." : "Rule was deleted; recreated with new id ${ruleId} and replayed settings."
    ]
    if (settingsCleared) {
        out.settingsCleared = settingsCleared
        out.note = "${out.note} Settings the app gained after the backup were emptied: ${settingsCleared.join(', ')}.".toString()
    }
    if (clearMiss) {
        out.partial = true
        out.note = "${out.note} Settings the app gained after the backup could not be emptied (${clearMiss}); compare hub_get_app_config(appId=${ruleId}, includeSettings=true) with hub_get_backup.".toString()
    }
    if (commitMiss) {
        out.success = false
        out.partial = true
        out.error = "Settings were replayed, but the app's closing Done did not commit: ${commitMiss}".toString()
        out.note = "${out.note} Open the app and click Done so its subscriptions match the restored settings.".toString()
    }
    if (nativeSkipped) {
        out.nativeImportSkipped = nativeSkipped
        out.note = "${out.note} The backup's App Cloner copy was not used: ${nativeSkipped}.".toString()
    }
    if (skippedDevices) {
        out.partial = true
        out.note = "${out.note} Device(s) deleted since the backup were left out: ${skippedDevices.collect { "${it.key} (${it.ids.join(', ')})" }.join(', ')}. Pick replacements with hub_set_rule if the rule needs them.".toString()
    }
    if (skippedMaps) {
        out.partial = true
        out.note = "${out.note} ${skippedMaps.size()} saved setting(s) could NOT be replayed (see settingsSkipped): ${skippedMaps.join(', ')}. Inspect with hub_get_app_config(appId=${ruleId}) and set them by hand if the rule needs them.".toString()
    }
    // A Required Expression lives in RM app state, which the settings replay cannot write: bring it
    // back to the snapshot's expression explicitly, and never report success over a missing gate.
    // Both live in Rule Machine's own app state; other app types have neither.
    def reOutcome = [:]
    def structure = [:]
    if (isRm) {
        try {
            reOutcome = _rmRestoreRequiredExpression(ruleId, snapshot)
        } catch (Exception reExc) {
            reOutcome = [requiredExpressionRestored: false, requiredExpressionError: reExc.message ?: reExc.toString()]
        }
        try {
            structure = _rmReconcileRuleStructure(ruleId, snapshot)
        } catch (Exception stExc) {
            structure = [structureRestored: false, structureError: stExc.message ?: stExc.toString()]
        }
    }
    if (reOutcome) out.putAll(reOutcome)
    if (structure) out.putAll(structure)
    if (out.leftoverConditionIds && structure?.removedConditionIds) {
        def gone = (structure.removedConditionIds as List)*.toString()
        out.leftoverConditionIds = (out.leftoverConditionIds as List).findAll { !gone.contains(it.toString()) }
        if (!out.leftoverConditionIds) out.remove("leftoverConditionIds")
    }
    if (structure?.structureRestored == false) {
        out.success = false
        out.partial = true
        out.error = "Settings were restored, but the rule's triggers/actions do not match the backup: ${structure.structureError}".toString()
        out.note = "${out.note} Triggers and actions live in Rule Machine state, which a settings replay cannot rebuild -- add the missing ones with hub_set_rule(addTriggers / addActions), checking hub_get_app_config(appId=${ruleId}) against hub_get_backup.".toString()
    } else if (structure?.removedTriggers || structure?.removedActions || structure?.removedConditionIds) {
        out.note = "${out.note} Removed what the backup did not have (triggers ${structure.removedTriggers ?: []}, actions ${structure.removedActions ?: []}, conditions ${structure.removedConditionIds ?: []}).".toString()
    }
    if (reOutcome?.requiredExpressionRestored == false) {
        out.success = false
        out.partial = true
        out.error = [out.error, "Settings were restored, but the rule's Required Expression does not match the backup: ${reOutcome.requiredExpressionError}"].findAll { it }.join(" ").toString()
        out.note = "${out.note} The Required Expression was NOT restored -- inspect it with hub_get_app_config(appId=${ruleId}) and rebuild it with hub_set_rule(addRequiredExpression or replaceRequiredExpression).".toString()
    } else if (reOutcome?.requiredExpressionRemoved == true) {
        out.note = "${out.note} The backup had no Required Expression, so the rule's expression was removed.".toString()
    } else if (reOutcome?.requiredExpressionRestored == true) {
        out.note = "${out.note} Required Expression confirmed to match the backup.".toString()
    }
    return out
}

// Empty every non-button setting the app has that the backup does not, through the same update
// endpoint as the replay (an emptied setting reads as unset; the hub keeps no way to delete one).
// Returns the keys emptied.
List _rmClearSettingsNotInBackup(Integer appId, Map savedSettings) {
    def status = _rmFetchStatusJson(appId)
    if (!(status?.appSettings instanceof List)) return []
    def saved = savedSettings.keySet().collect { it.toString() } as Set
    def extra = (status.appSettings as List).findAll { rec ->
        def n = rec?.name?.toString()
        // A device picker reports its devices in deviceIdsForDeviceList, with a null value.
        boolean hasValue = (rec?.value != null && rec?.value != "") ||
            (rec?.deviceIdsForDeviceList instanceof List && !(rec.deviceIdsForDeviceList as List).isEmpty())
        n && !saved.contains(n) && rec?.type?.toString() != "button" && hasValue
    }
    if (!extra) return []
    def body = [id: appId.toString()]
    for (rec in extra) {
        def n = rec.name.toString()
        body["settings[${n}]".toString()] = ""
        if (rec.type) body["${n}.type".toString()] = rec.type.toString()
        body["${n}.multiple".toString()] = (rec.multiple == true).toString()
    }
    _rmPostSettings(appId, body)
    return extra.collect { it.name.toString() }.sort()
}

// True only when the hub positively says the device is gone (404 or an empty object). An empty or
// unreadable answer keeps the id: dropping a live device from a restore is worse than keeping it.
private boolean _rmDeviceGone(String id, Map cache) {
    if (!id) return false
    if (cache.containsKey(id)) return cache.get(id) as boolean
    boolean gone = false
    try {
        def txt = hubInternalGet("/device/fullJson/${id}")
        if (txt) {
            def parsed = new groovy.json.JsonSlurper().parseText(txt)
            gone = (parsed instanceof Map) && parsed.isEmpty()
        }
    } catch (Exception e) {
        // Without a status, only the hub's own "status code: 404 ... Not Found" wording counts.
        Integer status = _httpStatusOf(e)
        def msg = e.message ?: ""
        gone = (status != null) ? status == 404 : (msg ==~ /(?s).*status code:? 404\b.*/ && msg.contains("Not Found"))
    }
    cache.put(id, gone)
    return gone
}

def _getAllToolDefinitions_partAppCloner() {
    return [
        [
            name: "hub_clone_native_app",
            description: """Clone any classic native automation app (RM rule, Room Lighting, Button Controller, Basic Rule, Notifier, etc.) using Hubitat's first-party appCloner, then surgically edit fields via hub_set_rule (RM rules) or hub_set_native_app (other classic apps).[[FLAT_TRIM]] A lower-overhead alternative to rebuilding via the wizard: clone an existing rule that has the shape you want. Preserves the full rule shape (conditions, expressions, IF/THEN/ELSE structure). The clone completes in tens of seconds for typical rules.[[/FLAT_TRIM]] Returns newAppId on success. Requires the Write master + confirm=true (+ a recent backup).""",
            inputSchema: [
                type: "object",
                properties: [
                    sourceAppId: [type: "integer", description: "Installed-app ID of the rule/app to clone. (alias: appId) Either sourceAppId or appId is required."],
                    appId: [type: "integer", description: "Alias for sourceAppId."],
                    newName: [type: "string", description: "Label for the new cloned app.[[FLAT_TRIM]] If omitted, the cloner default ('<source-label> clone') is kept.[[/FLAT_TRIM]]"],
                    stageDisabled: [type: "boolean", description: "true = disable the new app AND every DESCENDANT under it right after the clone. Staged-migration safety: a clone of an ACTIVE rule lands ACTIVE, and a cloned Button Controller's child Button Rules react to live button events. Re-enable via hub_set_app_disabled(disabled=false)."],
                    confirm: [type: "boolean", description: "Must be true."]
                ],
                // "sourceAppId OR appId" can't be a schema-level anyOf (Anthropic's
                // input_schema validator rejects top-level anyOf/oneOf/allOf); enforced
                // at runtime in toolCloneNativeApp. sourceAppId's description documents the OR.
                required: ["confirm"]
            ]
        ],
        [
            name: "hub_export_native_app",
            description: """Export any classic native automation app to its canonical JSON shape via Hubitat's first-party appCloner — a self-contained document that round-trips cleanly through hub_import_native_app.[[FLAT_TRIM]] The exported JSON is the same format Hubitat's UI 'Export' button produces. Use for: (1) backup before risky edits, (2) edit-as-text workflows that materialize the rule, mutate the JSON, and re-import as a new rule, (3) hub-to-hub transfer.[[/FLAT_TRIM]] Pass saveAs to also write the JSON to the hub's File Manager[[FLAT_TRIM]] (e.g. for HPM-style distribution)[[/FLAT_TRIM]]. Requires the Write master (no confirm/backup required).[[FLAT_TRIM]] Export instantiates a cloner app and persists, so it counts as a write.[[/FLAT_TRIM]]""",
            inputSchema: [
                type: "object",
                properties: [
                    sourceAppId: [type: "integer", description: "Installed-app ID of the rule/app to export. (alias: appId)"],
                    appId: [type: "integer", description: "Alias for sourceAppId."],
                    saveAs: [type: "string", description: "Optional File Manager filename (.json or .txt). When provided, the export is also written to /local/<saveAs>."],
                ]
            ]
        ],
        [
            name: "hub_import_native_app",
            description: """Create a new rule/app from a previously-exported JSON via Hubitat's first-party appCloner.[[FLAT_TRIM]] Pair with hub_export_native_app for round-trip edits or backup/restore workflows.[[/FLAT_TRIM]] Pass jsonContent (the exported JSON string) OR fromFile (a File Manager filename written by hub_export_native_app). Pass parentHintAppId — any existing rule id under the target parent the imported rule should land under[[FLAT_TRIM]] (e.g. another RM rule for an RM import); the cloner needs it to seed itself[[/FLAT_TRIM]]. Requires the Write master + confirm=true (+ a recent backup).""",
            inputSchema: [
                type: "object",
                properties: [
                    jsonContent: [type: "string", description: "The exported JSON content. Either jsonContent or fromFile is required."],
                    fromFile: [type: "string", description: "File Manager filename to read the JSON from."],
                    parentHintAppId: [type: "integer", description: "Any existing rule's id under the target parent app.[[FLAT_TRIM]] Used purely to seed the cloner instance — has no semantic effect on the imported rule beyond placing it under the same parent.[[/FLAT_TRIM]]"],
                    newName: [type: "string", description: "Label for the imported app.[[FLAT_TRIM]] If omitted, the cloner default ('<original-label> import') is kept.[[/FLAT_TRIM]]"],
                    stageDisabled: [type: "boolean", description: "true = disable the new app AND every DESCENDANT under it right after the import (staged-migration safety: an import lands ACTIVE). Re-enable via hub_set_app_disabled(disabled=false)."],
                    confirm: [type: "boolean", description: "Must be true."]
                ],
                // "jsonContent OR fromFile" is enforced at runtime in
                // toolImportNativeApp (throws IllegalArgumentException) rather
                // than via a schema-level anyOf: Anthropic's MCP input_schema
                // validator rejects top-level anyOf/oneOf/allOf with HTTP 400
                // (first surfaced via Haiku 4.5; Sonnet/Opus accept the same
                // shape, but the constraint applies to every model going
                // forward). Tool + property descriptions document the OR for
                // LLM tool-selection.
                required: ["parentHintAppId", "confirm"]
            ]
        ],
    ]
}

def _idempotentWriteToolNames_partAppCloner() {
    // Retry-safe writes (MCP idempotentHint) for this library's tools -- contributed to the
    // app's getIdempotentWriteToolNames() aggregator; see the classification rules there.
    return [
        // Native rules / classic apps
        "hub_export_native_app"
    ]
}

def _toolDisplayMeta_partAppCloner() {
    // Human-facing title/summary per tool (MCP annotations.title + the Advanced per-tool
    // overrides menu) -- merged into the app's getToolDisplayMeta() aggregator (issue #209).
    return [
        hub_clone_native_app: [title: "Clone Native App", summary: "Clone an existing classic app."],
        hub_export_native_app: [title: "Export Native App", summary: "Export a classic app to JSON, optionally saving it to the File Manager."],
        hub_import_native_app: [title: "Import Native App", summary: "Import previously exported app JSON as a new instance."]
    ]
}

private Map _mrtrCloneNativeAppSlice(Map rec, Map outerArgs) {
    Map args = _mrtrLeafArguments(rec.outerTool?.toString(), rec.leafTool?.toString(), outerArgs) as Map
    // Deep copy: the staging phases append to the checkpoint's own lists, and a
    // shallow copy would land those appends in the shared requestState record
    // before the slice decides what to store.
    Map cp = (rec.checkpoint instanceof Map) ? _mrtrCopyMap(rec.checkpoint as Map) : null
    if (cp == null) {
        requireDestructiveConfirm(args?.confirm as Boolean)
        def rawSource = (args?.sourceAppId != null) ? args.sourceAppId : args?.appId
        if (rawSource == null) throw new IllegalArgumentException("sourceAppId (or appId) is required")
        Integer sourceAppId = normalizeRuleId(rawSource)
        String newName = args?.newName?.toString()?.trim()
        def sourceCfg
        try { sourceCfg = _rmFetchConfigJson(sourceAppId) }
        catch (Exception sourceErr) {
            mcpLog("warn", "rm-native", "hub_clone_native_app: source ${sourceAppId} config fetch failed: ${sourceErr.message}")
            sourceCfg = null
        }
        if (!sourceCfg?.app) throw new IllegalArgumentException("Source app ${sourceAppId} not found or unreadable")
        String sourceLabel = sourceCfg.app.label?.toString()
        Integer parentAppId = null
        try {
            parentAppId = sourceCfg.app.parentAppId != null ? sourceCfg.app.parentAppId.toString() as Integer : null
        } catch (NumberFormatException ignored) {
            mcpLog("warn", "rm-native", "hub_clone_native_app: source ${sourceAppId} parentAppId not numeric: ${sourceCfg.app.parentAppId}")
        }
        if (parentAppId == null) {
            throw new IllegalArgumentException("Source app ${sourceAppId} has no numeric parentAppId. MCP cannot safely discover its clone; pass a child of the target parent app.")
        }
        _requireUnprotectedAppMutation(parentAppId, "clone or import a child app under")
        Map snapshot = _appClonerSnapshotChildren(parentAppId)
        if (snapshot.isError == true) return snapshot
        def preIds = snapshot.ids
        def initRes = _appClonerInit(sourceAppId)
        cp = [phase: "clone_clicks", clonerAppId: initRes.clonerAppId,
              referrer: initRes.referrer, configUrl: initRes.configUrl,
              sourceAppId: sourceAppId, sourceLabel: sourceLabel,
              parentAppId: parentAppId, preIds: preIds, newName: newName,
              stageDisabled: args?.stageDisabled == true]
        return _mrtrControl("clone_native_app", cp)
    }

    Integer clonerAppId = cp.clonerAppId as Integer
    try {
        if (cp.phase != "stage_disable") _requireUnprotectedAppMutation(cp.parentAppId, "clone or import a child app under")
        if (cp.phase == "clone_clicks") {
            _appClonerClickClone(clonerAppId, cp.referrer?.toString(), cp.configUrl?.toString())
            cp.phase = "clone_commit"
            return _mrtrControl("clone_native_app", cp)
        }
        if (cp.phase == "clone_commit") {
            _appClonerCommitImportRule(clonerAppId, cp.sourceAppId as Integer,
                cp.newName?.toString(), cp.referrer?.toString(), cp.configUrl?.toString())
            Integer newAppId = _appClonerDiscoverNewChild(cp.parentAppId as Integer,
                (cp.preIds ?: []) as Set, cp.sourceLabel?.toString(), cp.newName?.toString())
            String note = newAppId
                ? "Cloned source ${cp.sourceAppId} -> new app ${newAppId}${cp.newName ? " (renamed to '${cp.newName}')" : ""}. Use hub_set_native_app (or hub_set_rule for RM rules) to further customize."
                : "Clone fired but no new child appeared under parent ${cp.parentAppId}. Re-check via hub_list_apps (scope='instances') shortly."
            def baseResult = [success: newAppId != null, sourceAppId: cp.sourceAppId,
                              clonerAppId: clonerAppId, newAppId: newAppId, note: note]
            if (newAppId == null) {
                baseResult.isError = true
                baseResult.error = note
                if (cp.stageDisabled == true) _appClonerStagingDiscoveryMiss(baseResult, "clone")
                _appClonerCleanup(clonerAppId)
                return baseResult
            }
            if (cp.stageDisabled != true) {
                _appClonerCleanup(clonerAppId)
                return baseResult
            }
            def stagePlan = _appClonerStagePlan(newAppId)
            cp.phase = "stage_disable"
            cp.newAppId = newAppId
            cp.stageTargets = stagePlan.targets
            cp.stageFailures = stagePlan.failures
            cp.stagedDisabled = []
            cp.baseResult = baseResult
            return _mrtrControl("clone_native_app", cp)
        }
        if (cp.phase == "stage_disable") return _mrtrAppClonerStageSlice(cp, "clone")
        throw new IllegalStateException("Unknown clone continuation phase '${cp.phase}'")
    } catch (Exception e) {
        try { _appClonerCleanup(clonerAppId) } catch (Exception ignored) { }
        throw e
    }
}

private Map _mrtrImportNativeAppSlice(Map rec, Map outerArgs) {
    Map args = _mrtrLeafArguments(rec.outerTool?.toString(), rec.leafTool?.toString(), outerArgs) as Map
    // Deep copy: the staging phases append to the checkpoint's own lists, and a
    // shallow copy would land those appends in the shared requestState record
    // before the slice decides what to store.
    Map cp = (rec.checkpoint instanceof Map) ? _mrtrCopyMap(rec.checkpoint as Map) : null
    if (cp == null) {
        requireDestructiveConfirm(args?.confirm as Boolean)
        if (args?.parentHintAppId == null) {
            throw new IllegalArgumentException("parentHintAppId is required (any existing rule's id under the target parent — used to seed the cloner)")
        }
        Integer parentHintAppId = normalizeRuleId(args.parentHintAppId)
        String newName = args?.newName?.toString()?.trim()
        String jsonContent = args?.jsonContent?.toString()
        if (!jsonContent && args?.fromFile) {
            try { jsonContent = new String(downloadHubFile(args.fromFile.toString()), "UTF-8") }
            catch (Exception e) { throw new IllegalArgumentException("Cannot read fromFile '${args.fromFile}': ${e.message}") }
        }
        if (!jsonContent) throw new IllegalArgumentException("jsonContent or fromFile is required")
        def parsed
        try { parsed = new groovy.json.JsonSlurper().parseText(jsonContent) }
        catch (Exception e) { throw new IllegalArgumentException("jsonContent is not valid JSON: ${e.message}") }
        def replacements = (parsed instanceof Map) ? parsed.appReplacements : null
        if (!(replacements instanceof Map) || replacements.isEmpty()) {
            throw new IllegalArgumentException("jsonContent does not contain an appReplacements map — not an appCloner export")
        }
        Integer originalSourceId
        try { originalSourceId = ((replacements.keySet() as List)[0]).toString() as Integer }
        catch (Exception e) { throw new IllegalArgumentException("Could not extract original source id from appReplacements: ${e.message}") }
        String originalLabel = replacements.get(originalSourceId.toString())?.appLabel?.toString()
        def hintCfg
        try { hintCfg = _rmFetchConfigJson(parentHintAppId) }
        catch (Exception hintErr) {
            mcpLog("warn", "rm-native", "hub_import_native_app: parentHintAppId ${parentHintAppId} config fetch failed: ${hintErr.message}")
            hintCfg = null
        }
        if (!hintCfg?.app) throw new IllegalArgumentException("parentHintAppId ${parentHintAppId} not found or unreadable")
        Integer parentAppId = null
        try { parentAppId = hintCfg.app.parentAppId?.toString() as Integer }
        catch (NumberFormatException ignored) {
            mcpLog("warn", "rm-native", "hub_import_native_app: parentHintAppId ${parentHintAppId} parentAppId not numeric: ${hintCfg.app.parentAppId}")
        }
        if (parentAppId == null) {
            throw new IllegalArgumentException("parentHintAppId ${parentHintAppId} has no numeric parentAppId — pass a child of the target parent app")
        }
        _requireUnprotectedAppMutation(parentAppId, "clone or import a child app under")
        Map snapshot = _appClonerSnapshotChildren(parentAppId)
        if (snapshot.isError == true) return snapshot
        def preIds = snapshot.ids
        def initRes = _appClonerInit(parentHintAppId)
        Integer clonerAppId = initRes.clonerAppId as Integer
        try {
            String configUrl = initRes.configUrl?.toString()
            _appClonerSubmitForm(clonerAppId, "main", "source", configUrl, configUrl,
                [("settings[ruleUpload]".toString()): jsonContent])
            pauseExecution(2000)
            cp = [phase: "import_commit", clonerAppId: clonerAppId,
                  referrer: configUrl, configUrl: configUrl,
                  parentAppId: parentAppId, preIds: preIds,
                  originalSourceId: originalSourceId, originalLabel: originalLabel,
                  contentLength: jsonContent.length(), newName: newName,
                  stageDisabled: args?.stageDisabled == true]
            return _mrtrControl("import_native_app", cp)
        } catch (Exception e) {
            try { _appClonerCleanup(clonerAppId) } catch (Exception ignored) { }
            throw e
        }
    }

    Integer clonerAppId = cp.clonerAppId as Integer
    try {
        if (cp.phase != "stage_disable") _requireUnprotectedAppMutation(cp.parentAppId, "clone or import a child app under")
        if (cp.phase == "import_commit") {
            _appClonerCommitImportRule(clonerAppId, cp.originalSourceId as Integer,
                cp.newName?.toString(), cp.referrer?.toString(), cp.configUrl?.toString())
            Integer newAppId = _appClonerDiscoverNewChild(cp.parentAppId as Integer,
                (cp.preIds ?: []) as Set, cp.originalLabel?.toString(), cp.newName?.toString())
            String note = newAppId
                ? "Imported '${cp.originalLabel ?: 'app'}' as new app ${newAppId}${cp.newName ? " (renamed to '${cp.newName}')" : ""}. Use hub_set_native_app (or hub_set_rule for RM rules) to further customize."
                : "Import fired but no new child appeared under parent ${cp.parentAppId}. Re-check via hub_list_apps (scope='instances') shortly."
            def baseResult = [success: newAppId != null, clonerAppId: clonerAppId,
                              newAppId: newAppId, originalSourceId: cp.originalSourceId,
                              originalLabel: cp.originalLabel, contentLength: cp.contentLength,
                              note: note]
            if (newAppId == null) {
                baseResult.isError = true
                baseResult.error = note
                if (cp.stageDisabled == true) _appClonerStagingDiscoveryMiss(baseResult, "import")
                _appClonerCleanup(clonerAppId)
                return baseResult
            }
            if (cp.stageDisabled != true) {
                _appClonerCleanup(clonerAppId)
                return baseResult
            }
            def stagePlan = _appClonerStagePlan(newAppId)
            cp.phase = "stage_disable"
            cp.newAppId = newAppId
            cp.stageTargets = stagePlan.targets
            cp.stageFailures = stagePlan.failures
            cp.stagedDisabled = []
            cp.baseResult = baseResult
            return _mrtrControl("import_native_app", cp)
        }
        if (cp.phase == "stage_disable") return _mrtrAppClonerStageSlice(cp, "import")
        throw new IllegalStateException("Unknown import continuation phase '${cp.phase}'")
    } catch (Exception e) {
        try { _appClonerCleanup(clonerAppId) } catch (Exception ignored) { }
        throw e
    }
}

private Map _mrtrAppClonerStageSlice(Map cp, String operationLabel) {
    List targets = (cp.stageTargets instanceof List) ? cp.stageTargets as List : []
    List staged = (cp.stagedDisabled instanceof List) ? cp.stagedDisabled as List : []
    List failures = (cp.stageFailures instanceof List) ? cp.stageFailures as List : []
    Map outcome = _appClonerDisableTargets(targets, now(), staged, failures)
    List remaining = outcome.remaining
    if (remaining) {
        cp.stageTargets = remaining
        cp.stagedDisabled = staged
        cp.stageFailures = failures
        return _mrtrControl("${operationLabel}_native_app".toString(), cp)
    }
    def result = (cp.baseResult instanceof Map) ? ([:] + cp.baseResult) : [:]
    _appClonerFinishStaging(result, cp.newAppId as Integer, outcome)
    _appClonerCleanup(cp.clonerAppId as Integer)
    return result
}

// probe build marker 0.0.4
private String _probeBuildMarkerMcpAppClonerLib() { return "McpAppClonerLib-0.0.4" }


// Discovery tools (issue #209 modularization): BM25 tool search + the tool-guide
// dispatcher. getToolGuideSections() keeps the section MAP here (sandbox-lint's
// guide-pointer/TOOL_GUIDE.md parity checks anchor on it); a section's text may
// delegate to its domain library's method, which the lint follows to that file.

def toolSearchTools(args) {
    def query = args.query
    if (!query?.trim()) return [error: "query is required"]
    _cleanupRetiredToolState()
    def maxResults = args.maxResults != null ? Math.max(0, args.maxResults as Integer) : 5

    // The index (full corpus + per-doc tokens, index-aligned) is a pure function of the static
    // tool surface (definitions, gateway config, display meta) and lives in a class static, not in
    // atomicState: persisted, the two lists were ~244 KB of app state, and Hubitat re-serialises app
    // state on every execution, so every tool call paid for the search index. A static rebuilds
    // once per class load (a code deploy, a hub reboot) or when updated() clears it on a settings
    // save, and is otherwise free. Visibility filtering is applied per request so toggle changes
    // take effect without touching the index.
    //
    // The content fingerprint is what decides freshness: a code deploy recompiles the class
    // without firing updated(), contributors cannot bump currentVersion() (bot-only), so a version
    // stamp cannot tell a changed description from an unchanged one. On a warm class the
    // fingerprint is memoized, so the hit path does no catalog work at all; when it must be
    // computed, the catalog is walked ONCE and handed to both the fingerprint and the rebuild.
    def allDefs = null
    String corpusFp = TOOL_SEARCH_CORPUS_FP
    if (corpusFp == null) {
        allDefs = getAllToolDefinitions()
        corpusFp = toolSearchCorpusFingerprint(allDefs)
        TOOL_SEARCH_CORPUS_FP = corpusFp
    }
    def corpus = null
    def docTokensAll = null
    synchronized (TOOL_SEARCH_INDEX) {
        if (TOOL_SEARCH_INDEX.fingerprint != corpusFp || !(TOOL_SEARCH_INDEX.corpus instanceof List) ||
                !(TOOL_SEARCH_INDEX.tokens instanceof List) || TOOL_SEARCH_INDEX.tokens.size() != TOOL_SEARCH_INDEX.corpus.size()) {
            def built = buildToolSearchCorpus(allDefs)
            // Tokenize every corpus entry once, in corpus order, so tokens[i] is the tokenization
            // of corpus[i]. Plain List<List<String>> (sandbox-safe; whole-value single assignment).
            def tokens = built.collect { bm25Tokenize(_bm25DocText(it)) }
            TOOL_SEARCH_INDEX.clear()
            TOOL_SEARCH_INDEX.putAll([fingerprint: corpusFp, corpus: built, tokens: tokens])
        }
        corpus = TOOL_SEARCH_INDEX.corpus
        docTokensAll = TOOL_SEARCH_INDEX.tokens
    }

    // Apply the SAME visibility filter that getToolDefinitions() uses so that
    // hub_search_tools never surfaces tools the LLM cannot actually invoke. Both
    // consume getHiddenToolNames() -- the single source of truth covering the
    // Read/Write masters, the custom-engine mode, and the #114 advanced overrides --
    // so the catalog and the search corpus cannot drift (this also closes the
    // pre-#113 gap where built-in-app-gated tools leaked into search).
    def searchHideByName = getHiddenToolNames()
    // Filter corpus to only tools the current toggle state allows. Co-filter the cached
    // full-corpus tokens in the SAME pass so docTokens[k] stays aligned with visibleCorpus[k]
    // (docTokensAll[i] is the tokenization of corpus[i]; selecting both by the same surviving
    // index i preserves the pairing). A plain findAll would drop the original index, so
    // iterate with eachWithIndex and push both lists together.
    def visibleCorpus = []
    def docTokens = []
    int i = -1
    for (entry in corpus) {
        i++
        if (searchHideByName.contains(entry.name)) continue
        visibleCorpus << entry
        docTokens << docTokensAll[i]
    }

    // Tokenize the query (docs already tokenized from the cache above)
    def queryTokens = bm25Tokenize(query)

    if (!queryTokens) return [results: [], message: "No searchable terms in query"]

    // BM25 scoring
    def scores = bm25Score(docTokens, queryTokens)

    // Rank and return top results
    def ranked = []
    int idx = -1
    for (score in scores) {
        idx++
        if (score > 0) ranked << [index: idx, score: score]
    }
    ranked.sort { -it.score }
    // Dedup by tool name: a tool listed in more than one gateway (multi-gateway
    // membership) yields one corpus entry per membership and would otherwise
    // occupy several result slots for the same tool. Keep the highest-scoring
    // entry per tool (ranked is already sorted by descending score).
    def seenSearchNames = [] as Set
    ranked = ranked.findAll { r ->
        def nm = visibleCorpus[r.index].name
        if (seenSearchNames.contains(nm)) return false
        seenSearchNames << nm
        return true
    }
    if (ranked.size() > maxResults) ranked = ranked.take(maxResults)

    def gatewayConfig = getGatewayConfig()
    def displayMeta = getToolDisplayMeta()
    def results = ranked.collect { r ->
        def tool = visibleCorpus[r.index]
        def entry = [
            tool: _externalToolName(tool.name as String),
            description: _withGuideFirst(tool.name as String, tool.description as String),
            relevance: Math.round(r.score * 100) / 100.0
        ]
        // Defensive: a corpus entry can lack a title if a gateway lists a tool name
        // with no display-meta entry (the rebuild guard above already self-heals the
        // pre-title cached-corpus case).
        if (tool.title) entry.title = tool.title
        if (tool.gateway) {
            // Keep cached ranking vocabulary stable, but disclose only currently available routing context.
            def config = gatewayConfig.get(tool.gateway)
            def intro = _visibleGatewayIntro(tool.gateway, gatewayConfig, searchHideByName, displayMeta)
            entry.description = _withGuideFirst(tool.name as String, "${config.summaries.get(tool.name) ?: ''} [${intro}]".toString())
            entry.gateway = _externalToolName(tool.gateway as String)
            entry.callAs = "Call via ${_externalToolName(tool.gateway as String)}(tool=\"${_externalToolName(tool.name as String)}\", args={...})"
        } else {
            entry.callAs = "Call directly: ${_externalToolName(tool.name as String)}({...})"
        }
        return entry
    }

    return [
        query: query,
        resultsCount: results.size(),
        // Count DISTINCT tools, not corpus rows: a tool in N gateways (the
        // read/write split lists every read in both a hub_read_* and a
        // hub_manage_* gateway) yields N corpus entries, so visibleCorpus.size()
        // over-reports the tool count. results is deduped by name the same way.
        totalToolsSearched: visibleCorpus*.name.toSet().size(),
        results: results
    ]
}

// Content fingerprint of everything the BM25 corpus tokenizes -- tool names, descriptions,
// param keys, friendly titles, gateway summaries and search hints. Walks the same three
// sources buildToolSearchCorpus does, folding each field into a 64-bit rolling hash rather
// than materializing the ~98 KB concatenation of this catalog, and skipping the per-entry
// regex tokenize and corpus map allocation. Returns the hash as a decimal String.
//
// A hash admits collisions that exact string equality would not: two different catalogs can
// in principle fold to the same value, and no field framing changes that. Accepted here --
// the cost of a collision is one stale corpus until the next code deploy, against walking
// and holding ~98 KB on a memory-constrained hub. The length-prefixing in _fpField is a
// separate concern: it stops adjacent fields from being reordered or re-split into the same
// input, which is a structural ambiguity rather than a hash property.
//
// NOT pure: applyDescriptionTransform rewrites the
// descriptions of the defs list IN PLACE. A caller that passes its own list gets it back
// already stripped, and a later applyDescriptionTransform(defs, true) on that same list is a
// no-op -- which would ship every [[FLAT_TRIM]] block inline and blow the flat catalog's
// size cap. Pass a list you do not intend to strip again, or fetch a fresh one.
def toolSearchCorpusFingerprint(List defs = null) {
    long h = 17L
    def displayMeta = getToolDisplayMeta()
    for (toolDef in applyDescriptionTransform(defs ?: getAllToolDefinitions(), false, false)) {
        h = _fpField(h, toolDef.name as String)
        h = _fpField(h, displayMeta[toolDef.name]?.title)
        h = _fpField(h, toolDef.description)
        h = _fpField(h, toolDef.inputSchema?.properties?.keySet()?.join(','))
    }
    for (Map.Entry entry in getGatewayConfig()) {
        def gwName = entry.key
        def config = entry.value
        h = _fpField(h, gwName as String)
        h = _fpField(h, config.description)
        for (toolName in config.tools) {
            h = _fpField(h, toolName as String)
            h = _fpField(h, config.summaries?."${toolName}")
            h = _fpField(h, config.searchHints?."${toolName}")
        }
    }
    // Include representative field-template and tokenizer output in the cold-build fingerprint.
    // Token-list length checks cannot detect changed token content. Probe both the tokenizer
    // and searchable-field template, whose changes need not alter corpus text or list length.
    h = _fpField(h, bm25Tokenize(_bm25DocText(
        [name: 'hub_x-1', title: 'A_b', description: 'cd', params: 'ef', hints: 'gh',
         gateway: 'ij'])).join(','))
    return Long.toString(h)
}

// The exact text a corpus entry contributes to its tokens. Shared by the tokenize line and
// the fingerprint probe so the two cannot drift -- if this template changes, the fingerprint
// changes with it.
private String _bm25DocText(entry) {
    return "${entry.name} ${entry.title ?: ''} ${entry.description} ${entry.params ?: ''} ${entry.hints ?: ''}"
}

// Cold builds fold fields without allocating a concatenated catalog (~98 KB in the original
// audit); warm searches reuse the memoized fingerprint. Include each field's
// length so delimiter text such as "source|sourceFile|importUrl" cannot erase field boundaries.
private long _fpField(long h, value) {
    String s = (value == null) ? "" : value.toString()
    // String.hashCode(), not a hand-rolled character loop. Nothing here is @CompileStatic,
    // so every charAt/cast/multiply is a sandbox-intercepted dynamic dispatch -- spelling
    // this out by hand over the ~98 KB catalog is order 10^5 dispatches in one request, on
    // the first search after every deploy, in a tool with no budget or continuation escape
    // hatch. The JDK's own hash has the same collision profile for ~2 dispatches per field.
    h = h * 31L + s.length()
    return h * 31L + s.hashCode()
}

// Build a flat list of all tools (core + proxied) with gateway attribution
private buildToolSearchCorpus(List defs = null) {
    def gatewayConfig = getGatewayConfig()
    def proxiedNames = gatewayConfig.values().collectMany { it.tools } as Set
    // Strip [[FLAT_TRIM]] marker tokens before BM25 corpus build -- the markers
    // shouldn't show up as searchable tokens, but the wrapped capability lists
    // SHOULD (so hub_search_tools still matches "switch motion contact").
    def allDefs = applyDescriptionTransform(defs ?: getAllToolDefinitions(), false, false)
    def allDefsMap = allDefs.collectEntries { [(it.name): it] }
    // Friendly names join the searchable text: titles add tokens the bare
    // name/description lack (hub_set_rule gains 'author' from "Author Rule
    // Machine Rule" -- its corpus text otherwise only has 'authoring', and
    // the tokenizer does not stem).
    def displayMeta = getToolDisplayMeta()

    def corpus = []

    // Core tools (not behind a gateway)
    for (toolDef in allDefs) {
        if (!proxiedNames.contains(toolDef.name)) {
            def params = toolDef.inputSchema?.properties?.keySet()?.join(" ") ?: ""
            corpus << [name: toolDef.name, title: displayMeta[toolDef.name]?.title, description: toolDef.description?.replaceAll(/\n+/, ' ')?.trim(), params: params, gateway: null]
        }
    }

    // Gateway sub-tools (with search hints for synonym matching)
    for (Map.Entry entry in gatewayConfig) {
        def gwName = entry.key
        def config = entry.value
        for (toolName in config.tools) {
            def summary = config.summaries[toolName] ?: ""
            def hints = config.searchHints?."${toolName}" ?: ""
            def fullDef = allDefsMap[toolName]
            def params = fullDef?.inputSchema?.properties?.keySet()?.join(" ") ?: ""
            corpus << [name: toolName, title: displayMeta[toolName]?.title, description: "${summary} [${config.description}]", params: params, hints: hints, gateway: gwName]
        }
    }

    return corpus
}

// BM25 tokenizer: lowercase, split on non-alphanumeric, drop tokens < 2 chars
private bm25Tokenize(String text) {
    if (!text) return []
    return text.toLowerCase().split(/[^a-z0-9]+/).findAll { it.length() > 1 }
}

// BM25 Okapi scoring
private String _bm25Key(String token) {
    // Keep document, term, and query keys in the same namespace. This prefix
    // predates Map.get/put and preserves the existing token representation.
    return "t_${token}".toString()
}

private bm25Score(List<List<String>> docTokens, List<String> queryTokens) {
    def k1 = 1.5
    def b = 0.75
    def n = docTokens.size()

    if (n == 0) return []

    // Document lengths and average
    def docLengths = docTokens.collect { it.size() }
    def avgDl = docLengths.sum() / (double) n
    if (avgDl == 0) return new double[n] as List

    // Document frequency: how many docs contain each token. Preserve the token
    // namespace while using Map methods to avoid sandbox property resolution.
    def df = [:]
    for (tokens in docTokens) {
        for (token in tokens.toSet()) {
            def k = _bm25Key(token)
            df.put(k, (df.get(k) ?: 0) + 1)
        }
    }

    // Score each document
    def scores = new double[n]
    int docIdx = -1
    for (tokens in docTokens) {
        docIdx++
        // Term frequency for this doc
        def tf = [:]
        for (t in tokens) { def k = _bm25Key(t); tf.put(k, (tf.get(k) ?: 0) + 1) }

        def dl = docLengths[docIdx]
        double score = 0.0

        for (rawQt in queryTokens) {
            def qt = _bm25Key(rawQt)
            def termFreq = tf.get(qt) ?: 0
            if (termFreq > 0) {
                def docFreq = df.get(qt) ?: 0
                def idf = Math.log((n - docFreq + 0.5) / (docFreq + 0.5) + 1.0)
                def num = termFreq * (k1 + 1)
                def den = termFreq + k1 * (1 - b + b * dl / avgDl)
                score += idf * num / den
            }
        }

        scores[docIdx] = score
    }

    return scores as List
}

def toolGetToolGuide(section, cursor = null, Map apiDocs = null) {
    // apiDocs: {platform_api_search?, platform_api_page?} -- the hub's own API documentation.
    if (apiDocs?.platform_api_search != null || apiDocs?.platform_api_page != null) {
        if (section) throw new IllegalArgumentException("section and platform_api_search / platform_api_page are separate lookups; send one.")
        if (apiDocs.platform_api_search != null && apiDocs.platform_api_page != null) {
            throw new IllegalArgumentException("Send platform_api_search or platform_api_page, not both: search first, then open a pageId it returns.")
        }
        return (apiDocs.platform_api_page != null) ? _platformApiPage(apiDocs.platform_api_page.toString(), cursor)
                                                    : _platformApiSearch(apiDocs.platform_api_search.toString(), cursor)
    }
    def sections = getToolGuideSections()
    def subSections = getToolGuideSubSections()

    if (section) {
        def key = section.toLowerCase().replaceAll(/[^a-z_]/, "_")
        if (sections.containsKey(key)) {
            def result = [success: true, section: key]
            // Sub-keys of an oversized parent (issue #392): advertise them on the parent's own
            // response so the next call can be the narrow one, without a trip to the schema.
            if (subSections.containsKey(key)) result.subSections = subSections[key].keySet().toList()
            return _withGuidePage(result, _guideSectionServed(key, sections[key]), cursor)
        }
        def sub = guideSubSectionLookup(key)
        if (sub) {
            // Siblings, not just the parent: some reference material is shared between shortcuts
            // (the extended condition shapes serve addRequiredExpression, addAction.expression AND
            // addTrigger.condition), so a caller that landed on the wrong sub-key needs the narrow
            // alternatives -- naming only the parent sends it back to the fetch this split avoids.
            def result = [
                success: true,
                section: key,
                parentSection: sub.parent,
                subSections: subSections[sub.parent].keySet().toList(),
                note: "Part of the '${sub.parent}' section. A sibling sub-key may hold what you need; hub_get_tool_guide(section='${sub.parent}') returns all of it.".toString()
            ]
            return _withGuidePage(result, _guideSectionServed(key, sub.content), cursor)
        }
        return [
            success: false,
            error: "Unknown section: ${section}",
            availableSections: sections.keySet().toList(),
            availableSubSections: subSections.collectEntries { k, v -> [(k): v.keySet().toList()] }
        ]
    }

    // Full guide. It does not fit one response and never has (issue #392), so this pages instead
    // of tripping the size guard -- the caller gets real content plus the whole key space to
    // narrow with, and nextCursor when it wants the rest. Keys are served per section only.
    def fullGuide = "Acknowledgment keys are published only when a single section is read.\n\n" +
        sections.collect { k, v -> v }.join("\n\n---\n\n")
    def result = [
        success: true,
        section: "full",
        availableSections: sections.keySet().toList(),
        availableSubSections: subSections.collectEntries { k, v -> [(k): v.keySet().toList()] }
    ]
    return _withGuidePage(result, fullGuide, cursor)
}

private Map _platformApiSearch(String query, cursor) {
    // The hub's own Groovy API reference (firmware 2.5.2+, Settings > For Developers > API
    // documentation), served from /developer-docs. A search downloads and parses the whole index
    // (several MB) on every call and returns only ranked matches, 25 per page; a class page returns
    // its methods 40 per page. `methods` is read with Map.get: the sandbox blocks it as a property.
    def terms = query.toLowerCase().split(/\s+/).findAll { it }
    if (!terms) throw new IllegalArgumentException("platform_api_search needs at least one word, e.g. 'eventsBetween' or 'hub variable'.")
    def index
    try {
        def raw = hubInternalGet("/developer-docs/index.json", null, 60)
        index = raw ? new groovy.json.JsonSlurper().parseText(raw) : null
    } catch (Exception e) {
        mcpLogError("discovery", "API documentation index read failed", e)
        def out = [success: false, error: "Could not read the hub's API documentation index: ${e.message}"]
        if (_hubFirmwareBefore("2.5.2")) out.note = "The on-hub API documentation needs firmware 2.5.2 or later."
        return out
    }
    if (!(index instanceof Map) || !(index.pages instanceof List)) {
        return [success: false, error: "The hub's API documentation index has an unexpected shape."]
    }
    def hits = []
    for (pg in index.pages) {
        if (!(pg instanceof Map)) continue
        // Apps, drivers and shared APIs outrank the many protocol (Z-Wave/Zigbee/Matter) pages.
        int sectionBoost = (pg.section == "protocols") ? 0 : 3
        String pageText = "${pg.id} ${pg.label} ${pg.className} ${pg.topic}".toLowerCase()
        if (terms.every { pageText.contains(it) }) {
            hits << [score: 3 + sectionBoost, pageId: pg.id, className: pg.className, label: pg.label, section: pg.section, kind: "page", usage: pg.usage]
        }
        def pgMethods = pg.get("methods")
        for (m in (pgMethods instanceof List ? pgMethods : [])) {
            if (!(m instanceof Map)) continue
            String name = (m.name ?: "").toString()
            String lname = name.toLowerCase()
            String text = "${name} ${m.signature} ${m.summary} ${pg.className} ${pg.label}".toLowerCase()
            if (!terms.every { text.contains(it) }) continue
            // An exact method-name term ranks first, then a name holding every term.
            int score = sectionBoost
            if (terms.any { it == lname }) score += 4
            else if (terms.every { lname.contains(it) }) score += 2
            hits << [score: score, pageId: pg.id, className: pg.className, label: pg.label, section: pg.section, kind: m.kind ?: "method",
                     name: name, signature: m.signature, summary: m.summary?.toString()?.take(400)]
        }
    }
    for (g in (index.guides instanceof List ? index.guides : [])) {
        if (g instanceof Map && terms.every { "${g.title} ${g.summary}".toLowerCase().contains(it) }) {
            hits << [score: 1, kind: "guide", label: g.title, summary: g.summary, url: g.url]
        }
    }
    hits = hits.sort { -(it.score as int) }.collect { h -> h.findAll { k, v -> k != "score" && v != null } }
    def paged = _paginateList(hits, cursor != null ? cursor : "", 25, "hub_get_tool_guide")
    def out = [success: true, platformApiSearch: query, contentRevision: index.contentRevision, total: hits.size(), matches: paged.page]
    out.note = hits ? "Open a class with hub_get_tool_guide(platform_api_page=<pageId>) for full method descriptions. Methods the sandbox restricts to system apps are not marked; probe before relying on one." :
                      "No match. Search a method or class name, e.g. 'getHubFiles', 'DeviceWrapper', 'hub variable'."
    if (paged.nextCursor != null) out.nextCursor = paged.nextCursor
    return out
}

private Map _platformApiPage(String pageId, cursor) {
    if (!(pageId ==~ /[a-z0-9][a-z0-9-]*/)) throw new IllegalArgumentException("platform_api_page must be a pageId from platform_api_search, e.g. 'api-com-hubitat-app-devicewrapper'.")
    def pg
    try {
        def raw = hubInternalGet("/developer-docs/${pageId}.json", null, 30)
        pg = raw ? new groovy.json.JsonSlurper().parseText(raw) : null
    } catch (Exception e) {
        mcpLogError("discovery", "API documentation page read failed", e)
        return [success: false, error: "Could not read API documentation page '${pageId}': ${e.message}",
                note: "Check the pageId with hub_get_tool_guide(platform_api_search=...)." + (_hubFirmwareBefore("2.5.2") ? " The on-hub API documentation needs firmware 2.5.2 or later." : "")]
    }
    def pgMethods = (pg instanceof Map) ? pg.get("methods") : null
    if (!(pgMethods instanceof List)) return [success: false, error: "API documentation page '${pageId}' has an unexpected shape."]
    // A description past 20,000 characters is cut (descriptionTruncated), so a single-method page stays
    // near the ~60 KB budget.
    def methods = pgMethods.findAll { it instanceof Map }.collect { m ->
        def text = (m.descriptionMarkdown ?: m.summary)?.toString()?.trim()
        def entry = [kind: m.kind, name: m.name, signature: m.signature, description: text?.take(20000)]
        if (text && text.length() > 20000) entry.descriptionTruncated = true
        entry
    }
    // 40 methods a page, fewer when their descriptions would push a page past ~60 KB.
    def pageCursor = (cursor != null) ? cursor : ""
    def paged = _paginateList(methods, pageCursor, 40, "hub_get_tool_guide")
    while (paged.page.size() > 1 && groovy.json.JsonOutput.toJson(paged.page).length() > 60000) {
        paged = _paginateList(methods, pageCursor, paged.page.size() - 1, "hub_get_tool_guide")
    }
    def out = [success: true, pageId: pg.id, className: pg.className, label: pg.label, section: pg.section, topic: pg.topic, usage: pg.usage,
               extendsClass: pg.extendsClass, totalMethods: methods.size(), methods: paged.page]
    if (paged.nextCursor != null) out.nextCursor = paged.nextCursor
    return out
}

// Attach `content` to a guide result, paging it when it cannot fit one response. A payload that
// fits comes back whole and keeps the shape every section call has today -- no nextCursor, no
// offset. Only an actually-split payload gains the pagination fields.
private Map _withGuidePage(Map result, content, cursor) {
    def paged = paginateGuideContent(content, cursor)
    result.content = paged.content
    if (paged.nextCursor != null || paged.offset > 0) {
        result.offset = paged.offset
        result.totalChars = paged.totalChars
    }
    // ABSENT, never present-and-null, on the last page: the repo's cursor contract is "iterate
    // nextCursor until absent", and a client that tests key presence would hand null back, land on
    // page 1 again, and loop forever with no error.
    if (paged.nextCursor != null) result.nextCursor = paged.nextCursor
    return result
}

def _getAllToolDefinitions_partDiscovery() {
    return [
        // Tool Guide
        [
            name: "hub_get_tool_guide",
            description: "Get the deep-reference guide for an MCP tool topic[[FLAT_TRIM]] (exhaustive capability tables, wire formats, worked examples)[[/FLAT_TRIM]]. Read a write tool's section before calling that tool: the section publishes the acknowledgment key the best-practice gate requires, and best_practice_reference maps each write tool to its section. A `<parent>_<part>` key (e.g. set_rule_reference_conditions) returns just that part of its parent section; the bare parent key returns all of it.[[FLAT_TRIM]] A parent's response lists its own sub-keys.[[/FLAT_TRIM]] Prefer a section: omitting it returns the key list plus the first page of the whole guide (paged via nextCursor)[[FLAT_TRIM]], the largest response this tool produces, so on a timeout retry a specific section[[/FLAT_TRIM]].[[FLAT_TRIM]] platform_api_search / platform_api_page read the hub's own Groovy API documentation instead.[[/FLAT_TRIM]]",
            inputSchema: [
                type: "object",
                properties: [
                    section: [type: "string", description: "One section key from the enum. Omit to get the key list plus the first page of the full guide.", enum: ["device_authorization", "best_practice_reference", "tool_access", "hub_admin_write", "hub_admin_write_overview", "hub_admin_write_destructive", "hub_admin_write_radios", "hub_admin_write_devices", "hub_admin_write_code", "hub_admin_write_system", "virtual_devices", "update_device", "rules", "backup", "file_manager", "performance", "performance_overview", "performance_devices", "performance_diagnostics", "builtin_app_tools", "builtin_app_tools_overview", "builtin_app_tools_apps", "builtin_app_tools_rules", "builtin_app_tools_crud", "set_rule_reference", "set_rule_reference_overview", "set_rule_reference_triggers", "set_rule_reference_actions", "set_rule_reference_conditions", "set_rule_reference_walkstep", "set_rule_reference_responses", "set_rule_reference_guards", "set_rule_create_reference", "visual_rule_reference", "variables", "dashboards", "bundles", "rooms", "slow_ops"]],
                    cursor: [type: "string", description: "Continue a paged payload: pass the prior call's nextCursor. Omit otherwise -- a cursor is rejected on a payload that fit one response."],
                    platform_api_search: [type: "string", description: "[[FLAT_TRIM]]Instead of a section: search the hub's Groovy API docs, e.g. 'eventsBetween'.[[/FLAT_TRIM]]"],
                    platform_api_page: [type: "string", description: "[[FLAT_TRIM]]Instead of a section: one API docs class page by pageId.[[/FLAT_TRIM]]"]
                ]
            ]
        ],
        // Tool Search (BM25)
        [
            name: "hub_search_tools",
            description: "Search all MCP tools by natural language query (BM25 ranking). Searches tool names, friendly titles, descriptions, and parameter names. Returns matching tools with their gateway location so you know how to call them. Use when unsure which gateway contains the tool you need.",
            inputSchema: [
                type: "object",
                properties: [
                    query: [type: "string", description: "Natural language search query (e.g. 'zigbee radio', 'delete app', 'memory leak', 'room management')"],
                    maxResults: [type: "integer", description: "Max results to return. Default: 5.", default: 5]
                ],
                required: ["query"]
            ]
        ],
    ]
}

def _readOnlyToolNames_partDiscovery() {
    // Read-only classification membership for this library's tools, contributed to the
    // app's getReadOnlyToolNames() aggregator (issue #209: per-tool metadata lives with
    // the tool). A tool absent from every part list is write+destructive by default.
    return [
        // Meta
        "hub_get_tool_guide", "hub_search_tools"
    ]
}

def _toolDisplayMeta_partDiscovery() {
    // Human-facing title/summary per tool (MCP annotations.title + the Advanced per-tool
    // overrides menu) -- merged into the app's getToolDisplayMeta() aggregator (issue #209).
    return [
        // Reference
        hub_get_tool_guide: [title: "Get Tool Guide", summary: "Deep-reference guide for MCP tool topics, plus search of the hub's own Groovy API documentation."],
        hub_search_tools: [title: "Search Tools", summary: "Search all MCP tools by natural-language query."]
    ]
}

// Native Rule Machine + classic-app tools (issue #209): the RM 5.1 wizard authoring
// surface (hub_set_rule) + native-app CRUD. The shared classic-dynamicPage wizard
// primitives stay in this file (used by other libraries).

def _getAllToolDefinitions_partNativeRM() {
    return [
        // Rule Machine Integration (read + trigger + pause/resume only — platform blocks CRUD)
        [
            name: "hub_list_rules",
            description: "List all Rule Machine rules (RM 4.x + 5.x, deduplicated by id) with each rule's id, label, and live `status` (`active`/`paused`/`stopped`/`disabled`).[[FLAT_TRIM]] Requires the Read master.[[/FLAT_TRIM]][[FLAT_TRIM]] `status` is `unknown` when the hub's app list is momentarily unreadable. CAVEAT: the runtime-STOPPED state is only visible here when the hub's list source decorates the label (many firmwares don't) — the authoritative stopped check is hub_get_rule_health's `stopped` field. For ONE rule's state, call hub_get_rule_health(appId) instead of listing every rule — it returns that rule's paused/disabled/stopped/broken directly. For the enabled/disabled state of NON-RM classic apps (Room Lighting, Notifier, Basic Rules, Button Controllers) use `hub_list_apps` (scope='instances'). Call `hub_get_tool_guide(section='builtin_app_tools_rules')` for the status-detection semantics and platform limitations on RM rule internals.[[/FLAT_TRIM]]",
            inputSchema: [
                type: "object",
                properties: [
                    cursor: [type: "string", description: "Opt-in pagination cursor. Omit for unbounded; pass \"\" for the first page, iterate nextCursor (page size 50)."]
                ]
            ]
        ],
        [
            name: "hub_call_rule",
            description: "Trigger one or more Rule Machine rules. Not destructive (invokes existing user-configured automation).[[FLAT_TRIM]] Requires the Write master.[[/FLAT_TRIM]] Call `hub_get_tool_guide(section='builtin_app_tools_rules')` for action semantics.",
            inputSchema: [
                type: "object",
                properties: [
                    ruleId: [type: ["integer", "array"], items: [type: "integer"], description: "Rule ID from hub_list_rules, or an array of rule IDs to act on in one call"],
                    action: [type: "string", enum: ["rule", "actions", "stop", "start"], description: "Which RM action to invoke. Default: rule."],
                ],
                required: ["ruleId"]
            ]
        ],
        [
            name: "hub_set_rule_paused",
            description: "Pause or resume one or more Rule Machine rules in one call (paused rules don't fire on triggers). paused=true pauses, paused=false resumes (idempotent on the hub). Pass an array of ruleIds to pause/resume a whole set at once — one RMUtils dispatch, e.g. a staged-migration cutover.[[FLAT_TRIM]] Requires the Write master.[[/FLAT_TRIM]]",
            inputSchema: [
                type: "object",
                properties: [
                    ruleId: [type: ["integer", "array"], items: [type: "integer"], description: "Rule ID from hub_list_rules, or an array of rule IDs to pause/resume together"],
                    paused: [type: "boolean", description: "true = pause the rule(s); false = resume."]
                ],
                required: ["ruleId", "paused"]
            ]
        ],
        [
            name: "hub_set_rule_private_boolean",
            description: "Set the private boolean of one or more Rule Machine rules to true or false (strict: accepts Boolean or lowercase string 'true'/'false' only).[[FLAT_TRIM]] Requires the Write master.[[/FLAT_TRIM]]",
            inputSchema: [
                type: "object",
                properties: [
                    ruleId: [type: ["integer", "array"], items: [type: "integer"], description: "Rule ID from hub_list_rules, or an array of rule IDs to set together"],
                    value: [type: "boolean", description: "Target value for the rule's Private Boolean."]
                ],
                required: ["ruleId", "value"]
            ]
        ],
        // Native classic-app CRUD (hub admin-layer, bypasses SmartApp parent-type check).
        // Generic across native automation app types — RM is the first registered type;
        // Room Lighting / Button Controllers / Basic Rules / Notifier / Groups+Scenes work
        // for edit + delete today (any classic-app appId), and join create as their entries
        // get added to _appTypeRegistry().
        [
            name: "hub_set_native_app",
            description: """Create OR edit a classic native app (Room Lighting, Button Controller, Notifier, Group, Scene, Visual Rule, etc.): omit appId to CREATE (appType + name), provide appId to EDIT.[[FLAT_TRIM]] One generic upsert for any classic SmartApp instance via settings/button.[[/FLAT_TRIM]] For Rule Machine RULES use hub_set_rule[[FLAT_TRIM]] (in the hub_manage_rule_machine gateway)[[/FLAT_TRIM]] instead.[[FLAT_TRIM]] Its one-call structured shortcuts are the preferred RM path, NOT this tool's raw settings/walkStep.[[/FLAT_TRIM]]

Requires the Write master + confirm=true + recent hub backup.[[FLAT_TRIM]]

On MCP 2026-07-28, eligible slow writes continue automatically across bounded Streamable HTTP requests and eventually return one final result; no custom token or client extension is needed. Older clients retain the existing status:'in_progress' remainder envelope. See hub_get_tool_guide(section='slow_ops').[[/FLAT_TRIM]]""",
            inputSchema: [
                type: "object",
                properties: [
                    appId: [type: "integer", description: "Installed-app id of an existing classic app (from hub_list_apps with scope='instances'). OMIT to CREATE a new app of `appType` (then `name` is required); PROVIDE to EDIT an existing app's settings/button."],
                    appType: [type: "string", enum: ["rule_machine", "button_controller", "groups_scenes", "notifier", "basic_rule", "room_lighting"], description: "Native app class to CREATE (appId omitted). Default: rule_machine. Visual Rules: use hub_set_visual_rule (not this enum).[[FLAT_TRIM]] Other classic apps are edited by appId and can usually be created through their parent app's own page (e.g. the Room Lighting parent's newScene input creates Room Lights from a group or scene) -- see hub_get_tool_guide(section='builtin_app_tools_crud').[[/FLAT_TRIM]]"],
                    name: [type: "string", description: "Label for the new app. Required on CREATE (when appId is omitted); ignored when appId is provided."],
                    settings: [type: "object", description: "Map {inputName: value} to write to the app's current config page: scalars for bool/enum/text/number inputs; for device inputs (capability.* or driver-specific device.*) a List of device IDs or the {id: label} map hub_get_app_config returns. Discover input names via hub_get_app_config; inputs on a sub-page need pageName or walkStep."],
                    button: [type: "string", description: "Page-transition button name to click (discover via hub_get_app_config)."],
                    pageName: [type: "string", description: "Optional sub-page for schema introspection + settings POST."],
                    stateAttribute: [type: "string", description: "Optional state attribute value for the button click."],
                    buttonRule: [type: "object", description: "Create a Button Rule under an existing Button Controller.", properties: [controllerId: [type: "integer", description: "Button Controller-5.1 appId"], buttonNumber: [type: "integer", description: "button number (>=1)"], event: [type: "string", enum: ["pushed", "held", "doubleTapped", "released"]]]],
                    walkStep: [type: "object", description: "Multi-page classic-app walker — EDIT-only (requires appId; rejected on create). Use it for inputs on a sub-page (hub_list_app_pages lists them), inputs that appear only after an earlier choice, and anything settings/button cannot represent.[[FLAT_TRIM]] For RM rules prefer hub_set_rule's structured shortcuts, which do the same walk in one call. Generic classic-dynamicPage walker for stateful apps: introspect/write/click/navigate/done one step per call, or operation='drive' with steps=[...] to run the whole sequence in one call. Same shape as hub_set_rule's walkStep.[[/FLAT_TRIM]]"],
                    confirm: [type: "boolean", description: "Must be true. Safety gate for Write master operations."]
                ],
                required: ["confirm"]
            ]
        ],
        [
            name: "hub_set_rule",
            description: """Create OR edit a Hubitat Rule Machine rule (RM 5.1) — one upsert tool. Omit appId to CREATE (name required; optionally bundle addTriggers/addActions/addRequiredExpression to populate in the same call). Provide appId to EDIT. In trigger/action/condition specs use `capability` NOT `type`. RM-only — for NON-RM classic apps (Room Lighting, Button Controller, Notifier, Groups+Scenes, Visual Rule) use hub_set_native_app; not the legacy custom engine (hub_*_custom_rule). Requires the Write master + confirm=true + recent backup; each edit ensures a File Manager baseline exists (same-rule baselines are reused for one hour by default; backup.backupKey restores it through hub_manage_backup).

ALWAYS prefer the one-call shortcuts (addTrigger, addAction, addRequiredExpression/replaceRequiredExpression, bulk addTriggers/addActions/replaceActions, remove/modify/move/clear, addLocalVariable/removeLocalVariable, patches); walkStep and raw settings+button are LAST RESORTS.[[FLAT_TRIM]] Each shortcut orchestrates the full RM 5.1 wizard in one call; walkStep (one wizard page per call) covers capabilities no shortcut can represent.

Partial-success (every shortcut): success:true can pair with partial:true — inspect partial/repairHints. A rejected trailing updateRule leaves the change written-but-not-live (subscriptionsNotLive / expressionNotLive / variableNotLive / patchesNotLive); retry hub_set_rule(button='updateRule', confirm=true). If wizardStuck:true, first run the close-editor click restoreHint names (cancelCapab for a condition sub-wizard, actionCancel for the action editor). On CREATE the new appId is returned even if a bundled item only partially bakes (partialTriggers/partialActions).[[/FLAT_TRIM]]

Deep reference + worked examples: guide:true inline, or hub_get_tool_guide(section='set_rule_reference').[[FLAT_TRIM]] Full create + repair protocol: hub_get_tool_guide(section='set_rule_create_reference'). Pass {discover:true} on addTrigger/addAction for the live machine-readable schema.

On MCP 2026-07-28, eligible slow writes continue automatically across bounded Streamable HTTP requests and return one final result. Older clients retain the status:'in_progress' remainder envelope. See hub_get_tool_guide(section='slow_ops').[[/FLAT_TRIM]]""",
            inputSchema: [
                type: "object",
                properties: [
                    appId: [type: "integer", description: "RM rule ID (the rule's installed-app id). OMIT to CREATE a new rule (then `name` is required); PROVIDE to EDIT an existing rule."],
                    name: [type: "string", description: "Label for the new rule (shown in Hubitat's Rule Machine app list). Required on CREATE (when appId is omitted); ignored when appId is provided. To RENAME an existing rule, do not pass name -- write the new label as a setting: settings:{origLabel:'New Name'} (a mainPage settings write auto-commits via updateRule, which copies origLabel to the display label; passing button:'updateRule' too is harmless but redundant)."],
                    settings: [type: "object", description: "Map {inputName: value}: scalars for bool/enum/text/number inputs, list of device IDs for multi-device inputs, capability.* or driver-specific device.* (the multiple=true 3-field contract is emitted and verified automatically — you don't manage it)."],
                    button: [type: "string", description: "Page-transition button name (e.g. updateRule, editCond, pausRule for RM; discover others via hub_get_app_config)."],
                    pageName: [type: "string", description: "Optional sub-page for schema introspection + settings POST."],
                    stateAttribute: [type: "string", description: "Optional state attribute value for the button click (e.g. trigger/action index for RM editCond/editAct)."],
                    addTrigger: [
                        type: "object",
                        description: """Add an RM TRIGGER (structured). DISCRIMINATOR: use `capability` NOT `type` (`{type:'switch'}` is rejected); returns triggerIndex. Capability families (use these display names): Device-state — Switch / Motion / Contact / Lock / Garage / Door / Valve / Window Shade / Presence / Power source; Numeric — Temperature / Humidity / Battery / Illuminance / Power / Energy / CO2 / Dimmer / Thermostat setpoints; Button; Custom Attribute; Certain Time (and optional date) / Sunrise / Sunset (the picker value is the full 'Certain Time (and optional date)' string); Mode; Periodic Schedule. Modifiers: andStays, allOfThese. Optional per spec: conditional (sets the conditional-trigger gate — pair with `condition` to bind it in one call), condition {capability, deviceIds?, state? | comparator?+value?, attribute?, not?, rawSettings?} (a NARROWER set than addRequiredExpression), rawSettings {field:value} with @N = the auto-assigned index (e.g. {'xVar@N':'myVar'}). addTriggers[] = bulk, updateRule once at the end. Per-field specs and the periodic shape: pass {discover: true}, guide:true, or hub_get_tool_guide(section='set_rule_reference_triggers'). Extended condition shapes: section='set_rule_reference_conditions'. Cross-cutting fail-loud steers: section='set_rule_reference_guards'."""
                    ],
                    addTriggers: [
                        type: "array",
                        description: "Bulk-add triggers (each item the same shape as addTrigger); updateRule fires ONCE at the end. The first failed or partial item stops the batch: later items are notAttempted and updateRule is not fired. Pairs with addActions to build a whole rule in one call.",
                        items: [type: "object"]
                    ],
                    addRequiredExpression: [
                        type: "object",
                        description: """Add an RM 5.1 Required Expression (the pre-trigger gate that conditions whether the rule may fire); returns conditionIndices. Spec: {conditions:[{capability, deviceIds?, state?, comparator?, value?, attribute?, not?, rawSettings?}, ...], operator:'AND'|'OR'|'XOR' OR operators:[...] (one per gap; RM walks left to right and stops early, so group mixed AND/OR with subExpression)}. comparator is REQUIRED with attribute (Custom Attribute) and with variable+value (Variable); ASCII !=/<>/== auto-map to RM glyphs, and a free-valued (String) variable/attribute offers `*contains*` (substring match; negate with not:true). STPage capability list and extended shapes (Mode, Between two times, Variable incl. compareToVariable, device-relative compareToDevice, nested subExpression): guide:true or hub_get_tool_guide(section='set_rule_reference_conditions'); cross-cutting fail-loud steers: section='set_rule_reference_guards'."""
                    ],
                    replaceRequiredExpression: [
                        type: "object",
                        description: """Replace the rule's existing Required Expression in place (same appId). Same spec as addRequiredExpression ({conditions:[...], operator|operators}, incl. `*contains*` substring match on a free-valued String variable/attribute -- negate with not:true); use addRequiredExpression to ADD one when the rule has none (this refuses with requiredExpressionMissing). A failed build leaves the original in place (originalPreserved:true); a failure after the switch rolls back to the original (requiredExpressionRestored).[[FLAT_TRIM]] The new expression is built after the existing one in RM's expression editor and the old one is removed only once the new one is complete. The replaced conditions stay listed as unused under Manage Conditions.[[/FLAT_TRIM]]"""
                    ],

                    addActions: [
                        type: "array",
                        description: "Bulk-add actions (each item the same shape as addAction; actions self-bake via doActPage); updateRule fires once at the end. The first failed or partial item stops the batch: later items are notAttempted and updateRule is not fired. Pairs with addTriggers.",
                        items: [type: "object"]
                    ],
                    addLocalVariable: [
                        type: "object",
                        description: "Add a local variable. Spec: {name, type, value} -- ALL THREE are REQUIRED (value is not optional: RM auto-commits the variable only when the value is written, so a missing value is rejected up front). type is one of Number/Decimal/String/Boolean/DateTime (case-insensitive; DateTime wants an ISO timestamp, e.g. 2026-05-06T12:00:00) and value must match the type. This differs from the setLocalVariable ACTION, which takes exactly one of value/sourceVariable/fromDevice/math. Use as %name% in actions/expressions."
                    ],
                    removeLocalVariable: [
                        type: "object",
                        description: "Remove a local variable. Spec: {name}. WARNING: RM does NOT refuse to delete a local an action still references — the delete usually succeeds and leaves the referencing action Broken; that returns success=false (deleted=true) with a repairHint to restore the pre-delete backup (backupKey in the response) or remove the references first. List current locals via hub_list_rule_local_variables (in hub_read_rules)."
                    ],
                    patches: [
                        type: "array",
                        description: "Multi-mutation in one call (not a transaction: ops before a stop stay written): each item is a sub-spec with ONE operation key (settings, button, addTrigger(s), addAction(s), addRequiredExpression, replaceRequiredExpression, addLocalVariable, removeLocalVariable, removeAction, clearActions, replaceActions, moveAction, removeTrigger, modifyTrigger, modifyAction). Operations run sequentially; updateRule fires once at the end; per-op outcome in patches[i]. The first failed or partial op or inner item stops the batch: later ops are notAttempted and updateRule is not fired.",
                        items: [type: "object"]
                    ],
                    removeAction: [
                        type: "object",
                        description: "Delete one action by index: {index:<N>}. RM preserves remaining indices (no renumbering)."
                    ],
                    clearActions: [
                        type: "boolean",
                        description: "Pass true to delete every action (highest index first) — the wipe-and-rebuild pattern. On a rare unconfirmed late commit (asyncCommitLikely:true) verify via hub_get_app_config(appId); do NOT call cancelTrash (it can commit pending deletes)."
                    ],
                    replaceActions: [
                        type: "array",
                        description: "Replace the entire action list (not a transaction): clears all actions, bulk-adds every spec here (same shape as addAction items), then updateRule once. The first failed or partial added item stops the rest (notAttempted, no updateRule); the old list is already cleared. Pass [] to clear all (= clearActions). On asyncCommitLikely:true verify before retrying; do NOT call cancelTrash.",
                        items: [type: "object"]
                    ],
                    moveAction: [
                        type: "object",
                        description: "Move one action up or down a slot: {index:<N>, direction:'up'|'down'}. For arbitrary reorders prefer replaceActions (one call)."
                    ],
                    removeTrigger: [
                        type: "object",
                        description: "Delete one trigger by index: {index:<N>}. RM preserves remaining indices. Use addTrigger to add a replacement."
                    ],
                    modifyTrigger: [
                        type: "object",
                        description: "Change a trigger's state field: {index:<N>, mods:{state:'<new-state>'}}. Only the state field is supported, and only on device-state triggers (Switch, Motion, Contact, Lock, Presence, ...) — Time/Periodic/Mode triggers are rejected with a removeTrigger+addTrigger hint. To change capability or deviceIds, use removeTrigger + addTrigger."
                    ],
                    modifyAction: [
                        type: "object",
                        description: "Retarget a rule-targeting action in one op: {index:<N>, mods:{ruleIds:[...]}} — e.g. point a Run Rule Actions caller at a replacement rule during a staged migration. Supported on runRule/cancelTimers/pauseRule (mods also: action 'pause'|'resume') and privateBoolean (mods also: value bool) actions; other action shapes are rejected toward removeAction + addAction. Implemented as a position-preserving rebuild (remove + re-add + reposition), so the action's settings index changes while its position is kept."
                    ],
                    walkStep: [
                        type: "object",
                        description: """Raw wizard walker — LAST RESORT, one call per wizard step (token-heavy): use ONLY when the structured shortcuts can't represent the change (Periodic sub-pages, conditional-trigger binding, later-firmware features). operation='drive' runs a whole steps=[...] loop in ONE call (introspect → navigate into a sub-page → write each field → done → finalize), carrying the page forward and stopping at the first failed step (stopOnError=false to continue); the single-step primitives drive composes are introspect | write (one field) | click | navigate | done. Spec: {page, operation, write?:{field:value}, click?:{name, stateAttribute?}, navigate?:{targetPage}, hrefContext?:{fromPage, hrefName, hrefParams?}, steps?:[...]}; page is e.g. selectTriggers/selectActions/doActPage/periodic. Always check silentRejection / valueEcho.match / health (the fail-loud signals; health.skipped / health.unreadable mean not-checked, not broken; a standalone mutation with budget-skipped health returns success:false, partial:true, healthUnverified:true -- verify health before continuing, do not replay the committed step). Full walker mechanics + page names: guide:true or hub_get_tool_guide(section='set_rule_reference_walkstep')."""
                    ],
                    addAction: [
                        type: "object",
                        description: """Add an RM ACTION (structured). DISCRIMINATOR: use `capability` NOT `type` (`{type:'log'}` is rejected); returns actionIndex (no trailing updateRule — doActPage self-bakes). Capability names: switch, dimmer, color, colorTemp, button, runCommand, lock, thermostat, hsm, shade, fan, mode, setVariable/setLocalVariable, log, notification, httpGet, httpPost, ping, volume, mute, chime, siren, privateBoolean, runRule, cancelTimers, pauseRule, capture, restore, refresh, poll, disableDevice, fileWrite/fileAppend/fileDelete, zwavePoll; flow control — delay, delayPerMode, cancelDelay, repeat, stopRepeat, repeatWhile, waitExpression, waitEvents, ifThen, elseIf, else, endIf, exitRule, comment. Expression-based ones (ifThen/elseIf/repeatWhile/waitExpression) take expression={conditions:[...], operator|operators}. LIMIT: only ONE waitEvents per rule. Rule-targeting caps (runRule/cancelTimers/pauseRule/privateBoolean) validate each ruleIds entry against the live RM rule list before any write; a rule id that is not an existing rule is rejected -- use hub_list_rules for valid ids. privateBoolean also takes '*', RM's "this rule" target, alone or mixed (e.g. ['*', 1809]). (On a hub whose rule list can't be resolved -- RM not installed or app-tree unreadable -- the check is skipped; a hub with zero rules instead rejects every rule target.) Per-condition shape: {capability, deviceIds:[N], state?, comparator?, value?, attribute?, not?, rawSettings?} (deviceIds MUST be an array — a bare integer silently stores {N:null}); nested subExpression not supported here (use addRequiredExpression). Optional: delay {hours, minutes, seconds, cancelable}; rawSettings {field:value} with @N = the auto action index (e.g. {'flashRate.@N':750}). Per-field specs, the shape guards, and variable-sourced values: pass {discover: true} for the live schema, hub_get_tool_guide(section='set_rule_reference_actions'), or docs/rm_action_subtype_schemas.md. Extended expression shapes (Mode, Between two times, Variable, compareToDevice): section='set_rule_reference_conditions'."""
                    ],
                    guide: [type: "boolean", description: "Set true to return the full hub_set_rule capability reference inline (same content as hub_get_tool_guide(section='set_rule_reference')), without a separate call. Makes NO change to any rule."],
                    buttonRule: [type: "object", description: "Create a Button Rule under an existing Button Controller: {controllerId, buttonNumber, event}. Returns buttonRuleId with the Button trigger auto-seeded — then author actions via addAction on that appId. The controller must already have a button device.", properties: [controllerId: [type: "integer", description: "Button Controller-5.1 appId"], buttonNumber: [type: "integer", description: "button number (>=1)"], event: [type: "string", enum: ["pushed", "held", "doubleTapped", "released"]]]],
                    confirm: [type: "boolean", description: "Must be true."]
                ],
                required: ["confirm"]
            ]
        ],
        [
            name: "hub_get_rule_health",
            description: """Inspect a rule's current state and return a structured health report.[[FLAT_TRIM]] Works for Rule Machine, Visual Rules Builder, and other classic apps (Button Controller, Basic Rule). This standalone read adds live eventSubscriptionCount/scheduledJobCount, runtime stopped, and status/markup fallbacks for paused. paused is true/false/null (unknown); explicit stopped state outranks display markup. Embedded health from write tools carries the structural verdict and compiled paused only, without these extra reads. With auto or ruleBuilderJson, Visual Rule labels preserve the raw own name; forcing configPage uses the rendered label.[[/FLAT_TRIM]] Run after every mutation. ok=false with unreadable=false means at least one issue was found (the issues list explains what); ok=false with unreadable=true means NEITHER source could be read (a transient fetch failure, or the app does not exist) -- a couldn't-check verdict, not evidence of breakage.""",
            inputSchema: [
                type: "object",
                properties: [
                    appId: [type: "integer", description: "Installed-app ID to check (Rule Machine or Visual Rules Builder rule)."],
                    source: [type: "string", enum: ["auto", "ruleBuilderJson", "configPage"], description: "Which source(s) to read; default auto."]
                ],
                required: ["appId"]
            ]
        ],
        [
            name: "hub_list_rule_local_variables",
            description: "List a Rule Machine rule's LOCAL variables (per-rule, distinct from hub globals).[[FLAT_TRIM]] Requires the Read master.[[/FLAT_TRIM]]",
            inputSchema: [
                type: "object",
                properties: [
                    appId: [type: "integer", description: "The Rule Machine rule's installed-app id (the rule whose local variables to list)."]
                ],
                required: ["appId"]
            ]
        ],
        [
            name: "hub_delete_native_app",
            description: """Delete any classic native automation app (RM rule, Room Lighting instance, Button Controller / Button Rule, Basic Rule, Notifier, Group, Scene, etc.). Same endpoint family across all of them.[[FLAT_TRIM]] force=false (default) soft-deletes (hub refuses if the app has child apps/devices); force=true hard-deletes with no child safety checks.[[/FLAT_TRIM]]

BEFORE DELETE: full snapshot saved to File Manager (backup.backupKey).[[FLAT_TRIM]] Call hub_restore_backup (in hub_manage_backup) with that key to recreate the app with all its settings re-applied.[[/FLAT_TRIM]]

Requires Write master + confirm=true + recent hub backup.""",
            inputSchema: [
                type: "object",
                properties: [
                    appId: [type: "integer", description: "Installed-app ID."],
                    force: [type: "boolean", description: "true = bypass child/device safety checks and force-delete. Default false."],
                    confirm: [type: "boolean", description: "Must be true."]
                ],
                required: ["appId", "confirm"]
            ]
        ],
        [
            name: "hub_set_app_disabled",
            description: "Enable or disable any installed app (the admin UI red-X) without deleting it — reversible and preserves the app's config. For Rule Machine rules use hub_set_rule_paused instead. Write master only — no confirm/backup needed[[FLAT_TRIM]]; the disabled flag is read-back verified[[/FLAT_TRIM]].",
            inputSchema: [
                type: "object",
                properties: [
                    appId: [type: "integer", description: "Installed-app ID to enable/disable (from hub_list_apps)."],
                    disabled: [type: "boolean", description: "true = disable the app (stop it running), false = enable it."]
                ],
                required: ["appId", "disabled"]
            ]
        ],
    ]
}

// Enable/disable any installed app via POST /installedapp/disable {id, disable} -- the documented
// Vue admin wire format (red-X). Reversible (re-enable with disabled=false). A POST that doesn't
// throw is NOT proof; the disabled flag is read back from /installedapp/json/<id>.
def toolSetAppDisabled(args) {
    def id = args?.appId
    if (id == null || !id.toString().isInteger() || id.toString().toInteger() <= 0) {
        throw new IllegalArgumentException("appId must be a positive integer (got: '${id}')")
    }
    int appId = id.toString().toInteger()
    _requireUnprotectedAppMutation(appId, "enable or disable")
    if (args?.disabled == null) {
        throw new IllegalArgumentException("disabled is required (true to disable the app, false to enable it)")
    }
    boolean disable = (args.disabled == true || args.disabled?.toString() == "true")
    try {
        hubInternalPostJson("/installedapp/disable", groovy.json.JsonOutput.toJson([id: appId, disable: disable]))
    } catch (Exception e) {
        return [success: false, appId: appId, error: "POST /installedapp/disable failed: ${e.message}", note: "Verify the app id with hub_list_apps and retry."]
    }
    // Read the flag back. Distinguish empty body / GET exception / missing-key so a read-back
    // miss can't masquerade as a clean false-RED, and a missing 'disabled' key can't be read as
    // false (a silent false-GREEN). A bare GET exception means the WRITE may have committed.
    def observed = null
    def readErr = null
    try {
        def txt = hubInternalGet("/installedapp/json/${appId}")
        if (txt) {
            def parsed = new groovy.json.JsonSlurper().parseText(txt)
            if (parsed instanceof Map && parsed.containsKey("disabled")) {
                observed = (parsed.disabled == true)
            } else {
                readErr = "read-back response carried no 'disabled' field"
            }
        } else {
            readErr = "read-back returned an empty body"
        }
    } catch (Exception e) {
        readErr = e.message
        mcpLog("warn", "hub-admin", "hub_set_app_disabled ${appId}: read-back of /installedapp/json/${appId} failed: ${e.message}")
    }
    if (observed == disable) {
        mcpLog("info", "hub-admin", "Set installed app ${appId} disabled=${disable}")
        return [success: true, appId: appId, disabled: disable, message: "App ${appId} disabled flag is now ${disable}."]
    }
    if (observed == null) {
        return [success: false, appId: appId, error: "POST /installedapp/disable was accepted but the disabled state could not be confirmed (${readErr ?: 'unparseable read-back'}).", note: "The change may already be applied -- re-check with hub_list_apps before retrying; do NOT blindly re-POST."]
    }
    return [success: false, appId: appId, disabled: observed, error: "POST accepted but read-back shows disabled=${observed} (wanted ${disable}).", note: "The hub may not have committed the flag; retry, or check the app in the hub UI."]
}

// Enumerate Rule Machine rules via the official hubitat.helper.RMUtils API
// (RM 4.x + RM 5.x, deduplicated by id) and ghost-filter them against the live
// /hub2/appsList tree. Shared by hub_list_rules (which formats the rich list and
// reports ghosts) and _rmValidRuleIds (which needs the existence-safe id set for
// pre-write rule-target validation), so the RMUtils lookup + ghost-filter logic
// lives in exactly one place.
//
// RMUtils is an optional platform class -- absent on hubs that have never
// installed Rule Machine. Absence manifests as NoClassDefFoundError or
// ClassNotFoundException (both Error subclasses, uncaught by catch Exception),
// hence the catch Throwable + null-guarded .message; the caller classifies which
// Throwables are a quiet "RM not installed" vs a real failure to surface.
//
// Returns [combined, ghostIds, v4Error, v5Error, treeReadable]:
//   combined     -- id(String) -> entry map, ghost-filtered when the tree read
//   ghostIds     -- ids RMUtils reported that are absent from /hub2/appsList
//   v4Error/v5Error -- RM 4.x / 5.x lookup error strings (null on success)
//   treeReadable -- false when /hub2/appsList could not be read; combined is
//                   then UNfiltered (may still carry post-delete cache ghosts)
//   liveApps     -- the /hub2/appsList map (id -> [name, disabled]) used for the
//                   ghost filter AND hub_list_rules status enrichment; null when
//                   the tree was unreadable (treeReadable=false)
// Fetch a guide section in full for an inline meta-call on a tool that has no cursor of its own.
// Returns the same envelope hub_get_tool_guide does, with every page concatenated and the
// pagination bookkeeping stripped -- the caller asked for the reference, not a page of it.
private Map _rmWholeGuideSection(String sectionKey) {
    def result = toolGetToolGuide(sectionKey)
    if (!(result instanceof Map) || result.nextCursor == null) return result as Map
    def parts = [result.content as String]
    def cursor = result.nextCursor
    // Bounded: a page is guidePageChars() and the whole guide is well under 20 pages, so the
    // guard can only fire if the pager itself regressed.
    int guard = 0
    while (cursor != null && guard++ < 50) {
        def page = toolGetToolGuide(sectionKey, cursor)
        parts << (page.content as String)
        cursor = page.nextCursor
    }
    def whole = [:] + (result as Map)
    whole.content = parts.join('')
    whole.remove('nextCursor')
    whole.remove('offset')
    whole.remove('totalChars')
    return whole
}


private Map _rmCollectFilteredRmRules() {
    def combined = [:]
    def v4Error = null
    def v5Error = null

    try {
        def rules4 = hubitat.helper.RMUtils.getRuleList() ?: []
        for (r in rules4) { registerRmRule(combined, r, "4.x") }
    } catch (Throwable e) {
        v4Error = e.toString()
    }

    try {
        def rules5 = hubitat.helper.RMUtils.getRuleList("5.0") ?: []
        for (r in rules5) { registerRmRule(combined, r, "5.x") }
    } catch (Throwable e) {
        v5Error = e.toString()
    }

    // Filter RMUtils ghosts. RMUtils.getRuleList() reads a cached child
    // list inside the RM parent app and that cache keeps returning an id
    // for some time (seconds to minutes, non-deterministic) after the
    // rule's InstalledApp row is deleted — verified live on firmware
    // 2.5.0.123 for both /installedapp/delete/<id> and
    // /installedapp/forcedelete/<id>/quiet. Hub UI never shows these
    // because it reads /hub2/appsList, which is authoritative. Cross-
    // check against that tree and drop any rule whose id isn't in it.
    // If /hub2/appsList itself fails, fall through with unfiltered
    // output (treeReadable=false) so hub_list_rules keeps visibility on a
    // transient hub error and _rmValidRuleIds can treat it as cannot-verify.
    def ghostIds = []
    def treeReadable = false
    def liveApps = null
    try {
        liveApps = _collectLiveApps()
        if (liveApps != null) {
            treeReadable = true
            def filtered = [:]
            for (Map.Entry kv in combined) {
                def id = kv.key
                def entry = kv.value
                def idInt
                try { idInt = (id instanceof Number) ? id.intValue() : id.toString().toInteger() }
                catch (Exception ignored) { idInt = null }
                if (idInt != null && liveApps.containsKey(idInt)) {
                    filtered.put(id, entry)
                } else {
                    if (idInt != null) ghostIds << idInt
                }
            }
            combined = filtered
        }
    } catch (Throwable e) {
        mcpLog("warn", "rm-interop", "_rmCollectFilteredRmRules: could not cross-check RMUtils output against /hub2/appsList (${e.message}); returning unfiltered")
    }
    return [combined: combined, ghostIds: ghostIds, v4Error: v4Error, v5Error: v5Error, treeReadable: treeReadable, liveApps: liveApps]
}

// Existence-safe set of Rule Machine rule ids (Integer) for pre-write target
// validation: the RMUtils rule list intersected with the live app tree. Returns
// null when the set cannot be trusted -- any RMUtils lookup error (Rule Machine never
// installed, or a transient one-sided v4/v5 failure) or the app-tree cross-check could
// not run -- so a caller treats "cannot verify" as skip-validation rather than a
// false-empty reject.
private Set _rmValidRuleIds() {
    def collected = _rmCollectFilteredRmRules()
    // Any RMUtils lookup error -- including a one-sided v4 or v5 failure -- makes the
    // enumeration incomplete, so the set cannot be trusted. On a 5.x-only hub the v4
    // getRuleList() legitimately returns [] with no error; if the v5 getRuleList("5.0")
    // then throws transiently, combined is empty but the rules are NOT verified-zero.
    // Requiring BOTH errors (the old && gate) would return that empty set as authoritative
    // and false-reject every existing target on the blip. RM-never-installed still errors
    // on both versions, so this keeps skipping there too.
    if (collected.v4Error || collected.v5Error) return null
    // App tree unreadable: membership is unverifiable (combined is unfiltered).
    if (!collected.treeReadable) return null
    def ids = [] as Set
    for (Map.Entry e in collected.combined) {
        def id = e.key
        def entry = e.value
        def idInt
        try { idInt = (id instanceof Number) ? id.intValue() : id.toString().toInteger() }
        catch (Exception ignored) { idInt = null }
        if (idInt != null) ids << idInt
    }
    return ids
}

// List all Rule Machine rules (RM 4.x + 5.x, deduped by id) via RMUtils, with
// post-delete cache ghosts filtered against /hub2/appsList. The RMUtils lookup and
// ghost filter live in _rmCollectFilteredRmRules (shared with the rule-target
// existence guard); this tool formats, paginates, and classifies the result.
def toolListRmRules(args) {
    def collected = _rmCollectFilteredRmRules()
    def combined = collected.combined
    def v4Error = collected.v4Error
    def v5Error = collected.v5Error
    def ghostIds = collected.ghostIds
    def treeReadable = collected.treeReadable
    def liveApps = collected.liveApps

    // Enrich each rule with its live enabled/paused/stopped/disabled status from the
    // /hub2/appsList tree (issue #359). When the tree was unreadable the rules are
    // returned unfiltered and carry no node data, so status is "unknown".
    for (entry in combined.values()) { _rmAnnotateRuleStatus(entry, treeReadable, liveApps) }

    // combined.values() returns a Collection view in some Groovy versions; materialize
    // as a concrete List via toList() so subList in _paginateList is safe.
    def rules = combined.values().sort { it.label ?: "" }.toList()

    def cursor = args?.cursor
    def paged = _paginateList(rules, cursor, 50, "hub_list_rules")
    def result = [
        rules: paged.page,
        count: paged.page.size()
    ]
    if (cursor != null) {
        result.total = rules.size()
        if (paged.nextCursor != null) result.nextCursor = paged.nextCursor
    }
    if (ghostIds) {
        result.ghostsFiltered = ghostIds.sort()
        result.ghostNote = "RMUtils reported ${ghostIds.size()} rule id(s) that no longer exist in /hub2/appsList — these are post-delete RMUtils-cache ghosts (rule is already gone, the cache just hasn't caught up). Filtered out of the rules list."
    }
    if (!treeReadable && !rules.isEmpty()) {
        result.statusNote = "/hub2/appsList was unreadable, so each rule's status is \"unknown\" (enabled/paused/stopped/disabled could not be determined). Retry; if it persists the hub's internal API may need Hub Security credentials."
    }
    // Classify the failures. A "missing class" error (RM not installed) is quiet whether
    // the other version succeeded OR both versions failed the same way (both-absent path).
    // A non-missing-class error (e.g. timeout, internal platform issue) is always surfaced
    // so operators can investigate rather than get silent empty results.
    // Narrow to class-resolution failures only. Earlier versions treated any
    // MissingMethodException / "No signature of method" / unqualified "Cannot get property"
    // as quiet-missing, but those substrings appear in unrelated Groovy runtime errors
    // (e.g. a shape change in RMUtils' return value would surface as MME against
    // registerRmRule and get swept under the rug). Scope each substring tightly:
    //   - NoClassDefFoundError / ClassNotFoundException / "unable to resolve class":
    //     JVM-level class-resolution errors; unambiguous "RM not installed" signal.
    //   - "Cannot get property 'helper'": the Hubitat sandbox returns null for
    //     unresolved `hubitat.helper.X` namespace lookups; scoping to 'helper'
    //     limits the match to the hubitat.helper.RMUtils path specifically.
    //   - MissingMethodException together with getRuleList: covers the old-firmware
    //     case where RMUtils exists but lacks the getRuleList("5.0") overload —
    //     unrelated MMEs no longer get swallowed.
    def classMissingHint = { String msg ->
        if (!msg) return false
        if (msg.contains("NoClassDefFoundError") ||
            msg.contains("ClassNotFoundException") ||
            msg.contains("unable to resolve class")) return true
        if (msg.contains("Cannot get property") && msg.contains("'helper'")) return true
        if ((msg.contains("MissingMethodException") || msg.contains("No signature of method"))
            && msg.contains("getRuleList")) return true
        return false
    }
    def hardErrors = []
    if (v4Error && !classMissingHint(v4Error)) hardErrors << "v4=${v4Error}"
    if (v5Error && !classMissingHint(v5Error)) hardErrors << "v5=${v5Error}"

    def bothClassMissing = v4Error && v5Error &&
                           classMissingHint(v4Error) && classMissingHint(v5Error)

    if (rules.isEmpty() && bothClassMissing) {
        // Both RMUtils lookups failed with class-resolution errors. That's the
        // expected shape on a hub that has never installed Rule Machine; it's
        // not an error the caller needs to react to. Return an empty list with
        // an informational note and leave success unset so the result still
        // reads as a normal empty response.
        result.note = "Rule Machine not detected on this hub."
    } else if (rules.isEmpty() && v4Error && v5Error) {
        // Both calls failed but at least one with a non-missing-class shape --
        // unusual enough that operators should see the raw error.
        result.success = false
        result.error = "RMUtils calls failed: v4=${v4Error} v5=${v5Error}"
        result.note = "Rule Machine may not be installed on this hub."
    } else if (hardErrors) {
        // One version succeeded but the other had a non-missing-class error — surface it
        // as a warning without blocking the successful results.
        result.warning = "Partial RMUtils failure (results from the other version shown): ${hardErrors.join('; ')}"
    }
    return result
}

// Normalize a single RMUtils rule entry into a consistent map and register under combined[id].
//
// RMUtils.getRuleList() returns list entries in shapes that vary by RM version:
// - RM 5.x: single-entry Map `[<id>: "<label>"]` -- the key is the rule ID, the value is the label.
// The key may arrive as String or Integer depending on how the hub built the Map.
// - RM 4.x: Map with explicit fields `[id: <id>, label: "<label>", name: "...", type: "..."]`.
// - Raw primitive (int or String ID): defensive fallback for shapes not covered above.
private void registerRmRule(Map combined, def r, String version) {
    def id
    def label
    def name
    def type
    if (r instanceof Map) {
        if (r.containsKey("id")) {
            // RM 4.x explicit-fields shape
            id = r.id
            label = r.label ?: r.name
            name = r.name ?: r.label
            type = r.type
        } else if (r.size() == 1) {
            // RM 5.x single-entry shape: [<id>: "<label>"]
            def entry = r.entrySet().iterator().next()
            // entry.key may come back as String or Integer depending on how Hubitat built
            // the Map; coerce to Integer (via string) so downstream consumers get the
            // Integer id advertised in hub_list_rules' response schema.
            def rawKey = entry.key
            try {
                id = (rawKey instanceof Number) ? rawKey.toInteger() : rawKey.toString().toInteger()
            } catch (NumberFormatException coerceErr) {
                // Returning the raw key would silently violate the tool's
                // ruleId: integer schema (callers would see a String id in the
                // response and fail to dispatch hub_call_rule against it). Skip
                // the entry and surface the anomaly via logs instead.
                def keyType = rawKey instanceof Number ? 'Number' : rawKey instanceof String ? 'String' : 'other'
                mcpLog("warn", "rm-interop", "registerRmRule: non-integer ruleId '${rawKey}' (type=${keyType}) in RM ${version} list -- skipping entry")
                return
            }
            label = entry.value?.toString()
            name = label
        }
    } else if (r != null) {
        // Raw ID fallback
        id = r
    }
    if (id == null) return
    def key = id.toString()
    if (!combined.containsKey(key)) {
        combined.put(key, [
            id: id,
            label: label,
            name: name,
            type: type,
            rmVersion: version
        ])
    }
}

// Annotate an RM rule entry (in place) with disabled/paused booleans, a status summary,
// and requiredExpressionFalse. WHY decoration-detection (full algorithm in the
// builtin_app_tools guide): RMUtils exposes no paused or stopped boolean, so both are found
// only by diffing the app's /hub2/appsList name against its RMUtils label. A stopped rule
// reaches this function through EITHER of two channels and both are read here: the
// "(Stopped)" suffix can sit on the RMUtils LABEL while the appsList name stays clean, or it
// can sit in the appsList-name REMAINDER the "(Paused)" diff already computes. The diff is
// what proves a suffix is a runtime decoration rather than the rule's real name — a rule
// literally NAMED "... (Paused)"/"... (Stopped)" carries the suffix in BOTH strings, so
// neither channel fires. The suffix is stripped from the returned label/name in the SAME
// encoding the undecorated path returns (RMUtils entity-escaping preserved), never swapped
// for the HTML-stripped/decoded form the comparison uses. status is a precedence SUMMARY
// (disabled > stopped > paused > active); the booleans stay
// independent — a rule paused first then disabled keeps its decoration, so
// {disabled:true, paused:true, status:"disabled"} is truthful. "unknown" (booleans then
// omitted, never asserted false) covers both a null liveApps (whole tree unreadable) and
// this one rule's node lacking data.disabled / name / RMUtils label.
private void _rmAnnotateRuleStatus(Map entry, boolean treeReadable, Map liveApps) {
    def idInt
    try { idInt = (entry.id instanceof Number) ? entry.id.intValue() : entry.id?.toString()?.toInteger() }
    catch (Exception ignored) { idInt = null }
    def node = (treeReadable && idInt != null && liveApps != null) ? liveApps[idInt] : null
    if (node == null) {
        entry.status = "unknown"
        return
    }
    def disabledRaw = node.disabled
    def cleanApps = stripAppConfigHtml(node.name)
    def cleanRm = stripAppConfigHtml(entry.label)
    if (disabledRaw == null || cleanApps == null || cleanRm == null) {
        def missing = []
        if (disabledRaw == null) missing << "data.disabled"
        if (cleanApps == null) missing << "appsList name"
        if (cleanRm == null) missing << "RMUtils label"
        mcpLog("warn", "rm-interop", "_rmAnnotateRuleStatus: rule ${entry.id} has incomplete node data (missing ${missing.join(', ')}); status unknown")
        entry.status = "unknown"
        return
    }
    def disabled = disabledRaw == true
    def paused = false
    // The literal-name test is "appsList still starts with the WHOLE RMUtils label" -- the
    // same evidence channel B uses to tell decoration from name. Testing only that appsList
    // does not END with " (Stopped)" got case three wrong: a rule literally named
    // "X (Stopped)" that is ALSO paused has appsList "X (Stopped) (Paused)", which ends
    // with "(Paused)", so the suffix in its real name read as a runtime decoration. It was
    // then reported status:"stopped" AND had "(Stopped)" stripped from both label and name,
    // so a name-to-id lookup could no longer find the rule.
    boolean stopped = (cleanRm.endsWith(" (Stopped)") && !cleanApps.startsWith(cleanRm))
    if (cleanApps != cleanRm && cleanApps.startsWith(cleanRm)) {
        def remainder = cleanApps.substring(cleanRm.length())
        if (remainder.contains("(Paused)")) paused = true
        if (remainder.contains("(Stopped)")) stopped = true
        if (remainder.contains("(Required Expression false)")) entry.requiredExpressionFalse = true
    }
    if (stopped) {
        entry.label = _rmStripTrailingDecoration(entry.label, "(Stopped)")
        entry.name = _rmStripTrailingDecoration(entry.name, "(Stopped)")
    }
    entry.disabled = disabled
    entry.paused = paused
    entry.status = disabled ? "disabled" : (stopped ? "stopped" : (paused ? "paused" : "active"))
}

// Drop a trailing runtime decoration from a label WITHOUT re-encoding it: the caller's
// string keeps whatever escaping its source used, so a decorated and an undecorated rule
// come back in the same encoding. Returns the input unchanged when the suffix is absent.
private String _rmStripTrailingDecoration(Object raw, String suffix) {
    def s = raw?.toString()
    if (s == null) return null
    // RMUtils labels can carry trailing spaces, so match past them.
    def trimmed = s.replaceAll(/\s+$/, "")
    if (!trimmed.endsWith(suffix)) return s
    return trimmed.substring(0, trimmed.length() - suffix.length()).replaceAll(/\s+$/, "")
}

// Normalize a ruleId argument that may be a single id or a list of ids into a
// deduped List<Integer>. RMUtils.sendAction natively takes a LIST of rule ids,
// so the RMUtils-backed tools accept either shape and dispatch once.
//
// Multi-id batches also existence-check every id against the live RM rule list
// BEFORE any dispatch: the array form is sold as the staged-migration cutover,
// where one typo'd id silently left un-actioned (RMUtils is fire-and-forget and
// reports nothing per-rule) is the exact failure the batch exists to prevent.
// Single-id calls keep their long-standing no-validation behavior. The check
// skips when the rule list is unverifiable (_rmValidRuleIds returns null).
private Map _rmRuleIdListArg(Object raw) {
    if (raw == null) throw new IllegalArgumentException("ruleId is required")
    def rawList = (raw instanceof List) ? raw : [raw]
    if (rawList.isEmpty()) throw new IllegalArgumentException("ruleId array must not be empty")
    List<Integer> ids = []
    for (id in rawList) {
        // _rmCoerceRuleId, not normalizeRuleId: a JSON-number 400.7 would silently
        // TRUNCATE to rule 400 via toInteger() -- and then PASS the existence
        // check below, pausing the wrong rule with full confidence.
        def n = _rmCoerceRuleId(id)
        if (n == null) {
            throw new IllegalArgumentException("ruleId '${id}' is not an integer-valued rule id. Use hub_list_rules to find valid ids.")
        }
        if (!ids.contains(n)) ids << n
    }
    Boolean verified = null
    if (ids.size() > 1) {
        def valid = _rmValidRuleIds()
        if (valid != null) {
            verified = true
            def unknown = ids.findAll { !valid.contains(it) }
            if (unknown) {
                throw new IllegalArgumentException("ruleId array contains id(s) that are not existing RM rules: ${unknown.join(', ')}. Nothing was dispatched. Verify ids via hub_list_rules and re-issue the batch.")
            }
        } else {
            // Cannot verify (RMUtils error / app tree unreadable): the batch still
            // dispatches, but the caller is TOLD -- the tool description promises
            // an up-front existence check, and a silent skip would let a typo'd id
            // report success on a fire-and-forget dispatch.
            verified = false
            mcpLog("warn", "rm-interop", "_rmRuleIdListArg: multi-id existence check SKIPPED (rule list unverifiable) for ids ${ids.join(', ')}")
        }
    }
    return [ids: ids, idsVerified: verified]
}

// Trigger a Rule Machine rule via RMUtils.sendAction() (rule) or the RM page
// buttons for actions/stop/start. actions clicks runAction, the UI's "Run Actions"
// button; stop/start toggle stopRule (RMUtils has no startRule verb — the RM 5.1 UI
// uses the stopRule button as a toggle on state.stopped, and clicking it while
// stopped restarts the rule and resets the private boolean). The button route is
// the one the hub UI itself takes, so unlike RMUtils.sendAction it is not refused by
// the platform's per-app load limiter.
//
// Not destructive — invokes existing user-configured automation.
def toolRunRmRule(args) {
    if (args?.ruleId == null) throw new IllegalArgumentException("ruleId is required")
    def idArg = _rmRuleIdListArg(args.ruleId)
    List<Integer> ruleIds = idArg.ids
    for (it in ruleIds) { _requireUnprotectedAppMutation(it, "change rule runtime") }
    def action = args?.action ?: "rule"

    // start/stop route through the stopRule button click (a toggle on
    // state.stopped) rather than RMUtils.sendAction — verified live on
    // firmware 2.5.0.123 that clicking stopRule when state.stopped=false
    // sets it true (unsubscribe + cancel delays/repeats/waits) and when
    // state.stopped=true clears it + re-runs initialize() + resets the
    // private boolean. To keep the verb idempotent, we read state before
    // clicking and no-op if the rule is already in the target state.
    if (action == "stop" || action == "start" || action == "actions") {
        boolean runActions = (action == "actions")
        def perRule = { Integer id -> runActions ? _rmRunActionsButton(id) : _rmToggleStopped(id, action) }
        String verb = runActions ? "runAction button" : "stopRule toggle"
        if (ruleIds.size() == 1) {
            def single = perRule(ruleIds[0])
            // Every call echoes ruleIds -- scalar and array alike -- matching the
            // sendRmAction paths, so callers can read one key on every shape.
            if (single instanceof Map) single.ruleIds = ruleIds
            return single
        }
        // Per-rule toggle loop with a relay-budget checkpoint: each toggle is a
        // statusJson read + (maybe) a button click, so a long list can outlive the
        // response budget. _rmToggleStopped no-ops rules already in the target
        // state, so re-issuing with the remainder is safe.
        def results = []
        List remaining = []
        boolean budgetPaused = false
        for (int i = 0; i < ruleIds.size(); i++) {
            if (i > 0 && _timeBudgetExceeded(args?.__reqT0 as Long)) {
                budgetPaused = true
                remaining = ruleIds.subList(i, ruleIds.size()).collect { it }
                break
            }
            results << perRule(ruleIds[i])
        }
        List failed = []
        results.eachWithIndex { r, i -> if (r?.success != true) failed << ruleIds[i] }
        def out = [
            success: failed.isEmpty() && !budgetPaused,
            partial: budgetPaused || (!failed.isEmpty() && failed.size() < results.size()),
            ruleIds: ruleIds,
            rmAction: "${verb} x${results.size()}".toString(),
            results: results
        ]
        if (idArg.idsVerified != null) out.idsVerified = idArg.idsVerified
        if (failed) {
            out.failedRuleIds = failed
            def actionedCount = results.size() - failed.size()
            out.error = (actionedCount == 0)
                ? "${verb} failed for EVERY rule in the batch (${failed.join(', ')}); per-rule detail in results[].".toString()
                : "${verb} failed for rule(s) ${failed.join(', ')} -- the other ${actionedCount} rule(s) in the batch WERE actioned; per-rule detail in results[].".toString()
            out.note = runActions
                ? "Re-issue for the failed ids only: a repeat of a succeeded id runs that rule's actions again."
                : "Re-issue for the failed ids only. A repeat of a succeeded id is safe: the toggle no-ops rules already in the target state."
        }
        if (budgetPaused) {
            out.remainingRuleIds = remaining
            if (!out.error) out.error = "Response-budget checkpoint: rule(s) ${remaining.join(', ')} were not yet actioned."
            // Failed ids and un-reached ids are DIFFERENT sets -- the re-issue
            // guidance must carry both or a caller following it strands the failures.
            def reissueIds = (failed + remaining).unique()
            out.note = "Budget checkpoint -- re-issue with ruleId=[${reissueIds.join(', ')}] to finish${failed ? " (includes the ${failed.size()} failed id(s), not just the un-reached ones)" : ""}; already-actioned rules no-op safely."
        }
        return out
    }

    if (action != "rule") throw new IllegalArgumentException("Invalid action '${action}'. Must be 'rule', 'actions', 'stop', or 'start'.")
    def result = sendRmAction(ruleIds, "runRule", "hub_call_rule action=${action}")
    if (result instanceof Map && idArg.idsVerified != null) result.idsVerified = idArg.idsVerified
    return result
}

// Click the rule's Run Actions button (runAction on the main page): runs the action list
// directly, skipping condition evaluation, exactly as the hub UI does.
private Map _rmRunActionsButton(Integer ruleId) {
    try {
        _rmClickAppButton(ruleId, "runAction")
    } catch (Exception e) {
        return [success: false, ruleId: ruleId, error: "hub_call_rule action=actions: runAction button click failed (${e.message})"]
    }
    return [success: true, ruleId: ruleId, rmAction: "runAction button"]
}

// Drive the RM 5.1 stopRule button — the same toggle the hub UI exposes
// for Stop/Start. `action` is one of "stop" or "start". Idempotent:
// clicking stopRule when state.stopped is already the target value would
// toggle it the wrong way (running -> stopped, stopped -> running), so
// we read state.stopped first and no-op if we're already there.
private Map _rmToggleStopped(Integer ruleId, String action) {
    def status
    try {
        status = _rmFetchStatusJson(ruleId)
    } catch (Exception e) {
        return [success: false, ruleId: ruleId, error: "hub_call_rule action=${action}: cannot read rule state before toggle (${e.message})"]
    }
    def stoppedNow = _readAppStateBoolean(status, "stopped", false)
    def targetStopped = (action == "stop")
    if (stoppedNow == targetStopped) {
        return [
            success: true,
            ruleId: ruleId,
            rmAction: "noop",
            note: "Rule was already ${action == 'stop' ? 'stopped' : 'running (not stopped)'} -- stopRule button not clicked."
        ]
    }
    try {
        _rmClickAppButton(ruleId, "stopRule")
    } catch (Exception e) {
        return [success: false, ruleId: ruleId, error: "hub_call_rule action=${action}: stopRule button click failed (${e.message})"]
    }
    return [
        success: true,
        ruleId: ruleId,
        rmAction: (action == "stop") ? "stopRule button -> state.stopped=true" : "stopRule button -> state.stopped=false (initialize + private boolean reset)"
    ]
}

// Pull a named Boolean out of statusJson.appState[]. Hubitat serializes
// Booleans in appState entries as the real `true`/`false` value, but
// occasionally as the string "true"/"false" -- treat both equivalently.
private Boolean _readAppStateBoolean(Map status, String name, Boolean fallback) {
    def entry = (status?.appState ?: []).find { it?.name == name }
    if (entry == null) return fallback
    def v = entry.value
    if (v instanceof Boolean) return v
    if (v == "true") return true
    if (v == "false") return false
    return fallback
}

// Fetch statusJson for {@code appId} and return the raw value of
// {@code state.editAct}, or {@code null} if the entry is absent.
//
// <p>RM 5.1 sets {@code state.editAct} to the action index whenever an
// action edit is in flight. While set, {@code delAct} and move-arrow
// clicks are silently no-oped by RM's {@code appButtonHandler}. This
// helper is used as a pre-flight guard in {@code _rmDeleteAction} and
// {@code _rmMoveAction} so callers get a descriptive error immediately
// rather than retrying for 10s before hitting the generic timeout.
//
// <p>RM is BELIEVED to clear a genuinely in-flight {@code state.editAct}
// after ~60s, but this is UNVERIFIED for a stale marker: one artificially set
// via a raw stateAttribute click was observed live (fw 2.5.1.135) NOT to clear
// after 5+ minutes. Treat the timeout as best-effort, not guaranteed. The value
// is typically an Integer (the action index) but may be serialized as a
// String by some firmware versions -- returned as-is without coercion.
private Object _rmGetStateEditAct(Integer appId) {
    def status = _rmFetchStatusJson(appId)
    def entry = (status?.appState ?: []).find { it?.name?.toString() == "editAct" }
    return entry?.value
}

// Pause or resume a Rule Machine rule via RMUtils.sendAction(pauseRule|resumeRule).
// paused=true pauses, paused=false resumes. Idempotent on the hub side. Backs the
// hub_set_rule_paused tool (verb-pair merge of the former pause/resume tools).
def toolSetRulePaused(args) {
    if (args?.ruleId == null) throw new IllegalArgumentException("ruleId is required")
    if (args?.paused == null) throw new IllegalArgumentException("paused (boolean) is required: true=pause, false=resume")
    Boolean paused
    if (args.paused instanceof Boolean) paused = args.paused
    else if (args.paused == "true") paused = true
    else if (args.paused == "false") paused = false
    else throw new IllegalArgumentException("paused must be boolean true/false (got: ${args.paused})")
    def idArg = _rmRuleIdListArg(args.ruleId)
    List<Integer> ruleIds = idArg.ids
    for (it in ruleIds) { _requireUnprotectedAppMutation(it, "change rule runtime") }
    def result = paused ? sendRmAction(ruleIds, "pauseRule", "hub_set_rule_paused")
                        : sendRmAction(ruleIds, "resumeRule", "hub_set_rule_paused")
    // idsVerified: true = every id existence-checked before dispatch; false = the
    // check was SKIPPED (rule list unverifiable) and this fire-and-forget batch
    // may include ids that do not exist. Absent on single-id calls.
    if (result instanceof Map && idArg.idsVerified != null) result.idsVerified = idArg.idsVerified
    // Echo the applied pause state so callers can confirm the outcome without a
    // follow-up read. RMUtils pause/resume is fire-and-forget, so this is the
    // requested/applied value, not a hub read-back.
    if (result instanceof Map) result.paused = paused
    return result
}

// Set a Rule Machine rule's private boolean (used by its conditions) via
// RMUtils.sendAction(setRuleBooleanTrue|setRuleBooleanFalse).
//
// Strict-coercion policy: accepts ONLY Boolean true/false or the canonical
// lowercase strings "true"/"false". Other truthy-looking values — 1, 0,
// "True", "TRUE", "yes", "no", "on", "off" — are rejected with
// IllegalArgumentException. Reason: silently coercing "yes" to true (or 1
// to true) risks the AI sending the wrong boolean when a rule's behaviour
// depends on the boolean (e.g. arming a security path). The ambiguity is
// worse than the friction of requiring explicit true/false.
def toolSetRmRuleBoolean(args) {
    if (args?.ruleId == null) throw new IllegalArgumentException("ruleId is required")
    if (args?.value == null) throw new IllegalArgumentException("value (boolean) is required")
    // Accept Boolean or the canonical lowercase strings 'true'/'false' only. Reject other
    // truthy-looking values (1, 'yes', 'True') to avoid silently setting the wrong boolean.
    Boolean resolved = null
    if (args.value instanceof Boolean) {
        resolved = args.value
    } else if (args.value == "true") {
        resolved = true
    } else if (args.value == "false") {
        resolved = false
    } else {
        throw new IllegalArgumentException("value must be boolean true/false (or the string 'true'/'false'), got: ${args.value}")
    }
    def rmAction = resolved ? "setRuleBooleanTrue" : "setRuleBooleanFalse"
    def idArg = _rmRuleIdListArg(args.ruleId)
    for (it in idArg.ids) { _requireUnprotectedAppMutation(it, "set rule private boolean") }
    def result = sendRmAction(idArg.ids as List, rmAction, "hub_set_rule_private_boolean value=${resolved}")
    if (result instanceof Map && idArg.idsVerified != null) result.idsVerified = idArg.idsVerified
    return result
}

// Shared sendAction wrapper. Returns a consistent success/error result map.
//
// Invariant: the 4-arg form `sendAction([ids], action, appLabel, "5.0")` dispatches
// to the RM 5.x handler and is the canonical call for both RM 4.x and RM 5.x rules.
// The 3-arg form `sendAction([ids], action, appLabel)` reaches only RM 4.x and is
// used as a fallback for very old firmware that predates the version-discriminator
// overload (see sendRmActionFallback). Background on the RM API shape:
// https://community.hubitat.com/t/rule-machine-api/7104
private Map sendRmAction(List<Integer> ruleIds, String rmAction, String logContext) {
    def appLabel = app?.label ?: "MCP Rule Server"
    try {
        hubitat.helper.RMUtils.sendAction(ruleIds, rmAction, appLabel, "5.0")
        mcpLog("info", "rm-interop", "${logContext}: sent ${rmAction} to rule(s) ${ruleIds.join(', ')}")
        def result = [success: true, ruleIds: ruleIds, rmAction: rmAction]
        if (ruleIds.size() == 1) result.ruleId = ruleIds[0]
        return result
    } catch (MissingMethodException e) {
        return sendRmActionFallback(ruleIds, rmAction, appLabel, logContext, e)
    } catch (NoSuchMethodError e) {
        return sendRmActionFallback(ruleIds, rmAction, appLabel, logContext, e)
    } catch (Throwable e) {
        // Everything else — NoClassDefFoundError (RM not installed), timeouts, NPEs
        // inside RM internals, invalid ruleId — propagates through a single error
        // response without a second attempt. Retrying a transient failure would
        // double-fire the action if the first call partially succeeded.
        def m = e.message ?: e.toString()
        mcpLog("error", "rm-interop", "${logContext} failed for rule(s) ${ruleIds.join(', ')}: ${m}")
        return [success: false, error: "RMUtils.sendAction failed: ${m}", note: _rmSendActionErrorNote(rmAction, ruleIds, m)]
    }
}

// Single source of truth for the RMUtils load-limiter marker substring (matched
// case-insensitively). RMUtils surfaces this text when the hub's per-app load limiter
// has tripped; centralized so a wording change is one edit, not a scatter of literals.
private String _rmExcessiveLoadMarker() { "excessive hub load" }

// Build the actionable note for a failed RMUtils.sendAction. When RMUtils reports the hub's
// per-app load limiter, steer recovery correctly: that limiter is STICKY -- it does NOT lift when
// hub load drains, so an immediate retry of the same call just fails again. An app disable/enable
// only clears the block on the app INSTANCE and the platform's load counters survive it, so the
// retry after a bounce can re-trip immediately (observed live); only a hub REBOOT resets those
// counters. On a pause/resume call the direct page-button escape
// bypasses RMUtils and is load-immune, so it IS the real recovery. Pause and resume share a
// SINGLE toggle button, pausRule, whose title flips between "Pause" and "Resume" with the rule's
// current run state (the same one-button toggle pattern as stopRule); clicking pausRule on a
// paused rule resumes it, so both the pause and resume cases steer to the same pausRule button.
// Substring is scoped tightly to RMUtils' load-message text so unrelated failures keep the plain note.
private String _rmSendActionErrorNote(String rmAction, List<Integer> ruleIds, String message) {
    def base = "Verify the ruleId is valid (use hub_list_rules) and Rule Machine is installed."
    if (ruleIds.size() > 1) {
        // A LIST dispatch that threw may have actioned part of the set before
        // failing -- a reflex retry double-fires runRule/runRuleAct actions.
        base = "${base} NOTE: this was a LIST dispatch (${ruleIds.join(', ')}) -- part of the set may already have been actioned; verify per-rule state via hub_list_rules before retrying (a blind retry re-fires already-actioned rules)."
    }
    if (message && message.toLowerCase().contains(_rmExcessiveLoadMarker())) {
        if (rmAction == "pauseRule" || rmAction == "resumeRule") {
            def verb = (rmAction == "resumeRule") ? "resume" : "pause"
            def perRule = (ruleIds.size() == 1) ? "hub_set_rule(appId=${ruleIds[0]}, button:'pausRule', confirm:true)"
                                                : "hub_set_rule(appId=<id>, button:'pausRule', confirm:true) per rule (${ruleIds.join(', ')}) -- CHECK EACH RULE'S CURRENT STATE FIRST via hub_list_rules: the batch went out in one RMUtils dispatch and part of it may already have been actioned, and pausRule is a toggle, so clicking it on a rule the batch already ${verb}d UNDOES that rule"
            return "RMUtils hit the hub's per-app load limiter (sticky -- retrying does not clear it; an app disable/enable clears only the block on the app instance and the platform's load counters can re-trip it at once, so only a hub reboot fully resets it). To ${verb} the rule now, drive the page button directly with ${perRule}, which bypasses RMUtils and is load-immune (pausRule is a single toggle -- clicking it on a paused rule resumes it). ${base}"
        }
        return "RMUtils hit the hub's per-app load limiter. It is sticky -- it does NOT lift when load drains and an immediate retry fails the same way. An app disable/enable clears the block on the app instance but not the platform's load counters, so it can re-trip immediately; a hub reboot is what resets them. Clear it, then reissue. ${base}"
    }
    return base
}

// 3-arg fallback invoked only when the 4-arg sendAction raised a signature-mismatch
// shape (MissingMethodException / NoSuchMethodError) — very old firmware that
// predates the version-discriminator overload. Any other Throwable from the 4-arg
// call propagates directly in sendRmAction above.
private Map sendRmActionFallback(List<Integer> ruleIds, String rmAction, String appLabel, String logContext, Throwable original) {
    try {
        hubitat.helper.RMUtils.sendAction(ruleIds, rmAction, appLabel)
        mcpLog("info", "rm-interop", "${logContext}: sent ${rmAction} to rule(s) ${ruleIds.join(', ')} (3-arg fallback)")
        def result = [success: true, ruleIds: ruleIds, rmAction: rmAction, fallback: "3-arg"]
        if (ruleIds.size() == 1) result.ruleId = ruleIds[0]
        return result
    } catch (Throwable e2) {
        def m1 = original.message ?: original.toString()
        def m2 = e2.message ?: e2.toString()
        mcpLog("error", "rm-interop", "${logContext} failed for rule(s) ${ruleIds.join(', ')}: 4-arg=${m1}, 3-arg=${m2}")
        return [success: false, error: "RMUtils.sendAction failed: ${m2}", note: "4-arg attempt also failed: ${m1}. ${_rmSendActionErrorNote(rmAction, ruleIds, m2)}"]
    }
}

// Resolve the page-transition button to click after a main-page settings
// write commits, for the app type whose live config reports `configAppName`
// (config.app.appType.name -- the child appName the registry keys on).
// Returns "updateRule" (the RM framework default) for unrecognized or
// RM-family types, and the registry's explicit `commitButton` (which may be
// null) for types that override it. A null return means "no commit click" --
// the app's inputs are submitOnChange and clicking updateRule would poison
// the render (e.g. Basic Rule's "For input string: updateRule").
// Repair hint for a session-end mainPage Done that did not commit. A Done the page itself refused
// (uiBlocked) posted nothing: the fix is the named fields, not a commit click.
private String _rmMainPageDoneRepairHint(Integer appId, Map done) {
    if (done?.uiBlocked == true) {
        return "The closing mainPage Done was refused, as Hubitat's app page would refuse it (${done.reason}). Settings are already written; set the listed fields with hub_set_native_app(appId=${appId}, settings={...}), which re-runs the Done.".toString()
    }
    return "The session-end mainPage Done click did not commit (${done?.reason}). Settings are already written, but the app's update lifecycle did not run -- verify via hub_get_app_config(appId=${appId}) and re-commit via hub_set_native_app(appId=${appId}, button='updateRule') for RM-family apps.".toString()
}

// True when configAppName is a registry type (matching as _resolveCommitButton does) or the Room
// Lighting parent, i.e. its commit button is known rather than defaulted.
private boolean _appTypeRegistryKnows(String configAppName) {
    if (!configAppName) return false
    if (configAppName == "Room Lighting") return true
    def versioned = (configAppName =~ /^(.+) [0-9]+(?:\.[0-9]+)*$/)
    def bare = versioned.matches() ? (versioned[0] as List)[1].toString() : null
    return _appTypeRegistry().any { typeKey, reg -> reg.appName == configAppName || (bare != null && reg.appName == bare) }
}

private String _resolveCommitButton(String configAppName) {
    if (!configAppName) return "updateRule"
    // The Room Lighting parent has no updateRule button and no create entry of its own. A settings write on
    // the Room Lighting parent (e.g. newScene) already does its work; clicking updateRule there
    // throws MissingMethodException in its appButtonHandler (verified live, fw 2.5.1.181).
    if (configAppName == "Room Lighting") return null
    // The hub reports Visual Rule children versioned ("Visual Rule Builder 2.0"); the registry holds
    // the bare family name. Exact match first, then the version-stripped name.
    def versioned = (configAppName.toString() =~ /^(.+) [0-9]+(?:\.[0-9]+)*$/)
    def bare = versioned.matches() ? (versioned[0] as List)[1].toString() : null
    def match = _appTypeRegistry().find { typeKey, reg -> reg.appName == configAppName } ?:
                (bare != null ? _appTypeRegistry().find { typeKey, reg -> reg.appName == bare } : null)
    if (match != null && match.value.containsKey("commitButton")) return match.value.commitButton
    return "updateRule"
}

// Detect whether the given configPage still carries an open RM-style
// wizard editor scaffold (any input whose name matches the well-known
// trigger/condition/action edit-scaffold patterns). Used by
// hub_set_rule to decide whether a wizard-Done button (`hasAll`,
// `actionDone`, ...) actually closed the editor or whether it needs a
// second click to commit. Verified live on firmware 2.5.0.123: the
// first wizard-Done click frequently leaves the scaffold in place and
// a second click of the same button finalizes the commit.
//
// Patterns recognized:
// isCondTrig.<N>   trigger-N "is conditional?" toggle (always present
// while a trigger row is open for editing)
// tCapab<N>        trigger-N capability picker
// tDev<N>          trigger-N device picker
// tstate<N>        trigger-N state value
// AlltDev<N>       trigger-N "all of these?" toggle
// stays<N>         trigger-N "and stays?" toggle
// editAct<N>       action-N edit scaffold
// editCond<N>      condition-N edit scaffold
private boolean _rmHasWizardScaffold(Map configPage) {
    if (!(configPage?.sections instanceof List)) return false
    def scaffoldPattern = ~/^(isCondTrig\.\d+|tCapab\d+|tDev\d+|tstate\d+|AlltDev\d+|stays\d+|editAct\d+|editCond\d+)$/
    for (sec in configPage.sections) {
        for (inp in (sec?.input ?: [])) {
            def n = inp?.name?.toString()
            if (n && scaffoldPattern.matcher(n).matches()) return true
        }
    }
    return false
}

// After a wizard-Done button click, the trigger summary row appears
// but the page sometimes leaves a single `isCondTrig.<N>` input on its
// own — RM 5.1's "Conditional Trigger?" follow-up prompt. Returns that
// input name (e.g. "isCondTrig.3") if it's the ONLY trigger-edit input
// remaining on the page, or null otherwise. Callers use this to auto-
// finalize by writing `<name>=false` (the canonical "no, not
// conditional" answer that closes the prompt without consuming an extra
// trigger index, unlike a second hasAll click).
//
// Returns null if either:
// - No isCondTrig.<N> input is present (nothing to finalize)
// - Other editor-scaffold inputs are also present (caller hasn't
// finished filling the trigger; finalizing now would commit an
// incomplete trigger). The caller's higher-level scaffold check
// handles that case separately.
private String _rmFindResidualCondTrig(Map configPage) {
    if (!(configPage?.sections instanceof List)) return null
    def condTrigPattern = ~/^isCondTrig\.\d+$/
    def otherScaffoldPattern = ~/^(tCapab\d+|tDev\d+|tstate\d+|AlltDev\d+|stays\d+|editAct\d+|editCond\d+)$/
    String foundCondTrig = null
    for (sec in configPage.sections) {
        for (inp in (sec?.input ?: [])) {
            def n = inp?.name?.toString()
            if (!n) continue
            if (condTrigPattern.matcher(n).matches()) {
                if (foundCondTrig != null) return null  // Multiple condTrigs — not a clean finalize case
                foundCondTrig = n
            } else if (otherScaffoldPattern.matcher(n).matches()) {
                return null  // Wider scaffold present — let the WARN path handle
            }
        }
    }
    return foundCondTrig
}

// Decide whether a just-clicked updateRule left an RM rule with pending
// subscription work. Returns null if the rule has no trigger-bearing
// settings at all (no lag to detect), otherwise returns a small map with
// `unsettled` (Boolean) + `triggerCount` (Integer) + `subCount` (Integer) +
// `suppressedBy` (why RM is withholding subscriptions, or null) so the caller
// can decide whether to auto-retry / warn. Also null when statusJson is unreadable.
//
// Unsettled = rule has at least one tDev<N> multi-device capability
// setting (trigger is device-backed) but eventSubscriptions is empty.
// HTTP-only, time-only, and triggerless rules legitimately have empty
// eventSubscriptions, so we scope the "unsettled" flag to the specific
// trigger shape that MUST produce subscriptions when initialized.
//
// Verified live on firmware 2.5.0.123: after a fresh trigger-wizard
// hasAll commit followed by updateRule, eventSubscriptions can stay
// at 0 for up to ~minute before populating — a second updateRule click
// typically settles them immediately. This function detects the case
// so hub_set_rule can auto-retry once + surface a clean warning
// if the retry still doesn't help.
private Map _rmCheckSubscriptionSettle(Integer appId) {
    def status
    try {
        status = _rmFetchStatusJson(appId)
    } catch (Exception e) {
        return null
    }
    def settings = status?.appSettings ?: []
    def triggerDevs = settings.findAll { s ->
        def n = s?.name?.toString()
        n?.matches(/^tDev\d+$/) && (s?.deviceIdsForDeviceList instanceof List) && s.deviceIdsForDeviceList
    }
    if (!triggerDevs) return null
    def subs = status?.eventSubscriptions ?: []
    return [
        unsettled: subs.isEmpty(),
        triggerCount: triggerDevs.size(),
        subCount: subs.size(),
        suppressedBy: _rmTriggerSubscriptionGate(status)
    ]
}

private String _rmSuppressedSettleText(Object gate) {
    def why = [requiredExpressionFalse: "its Required Expression is false (RM removes trigger subscriptions until it is true)",
               paused: "the rule is paused", stopped: "the rule is stopped"][gate?.toString()] ?: "RM reports the rule as inactive (${gate})"
    return "SUPPRESSED: eventSubscriptions=0 because ${why}. This is expected and says nothing about whether the trigger is complete; check the trigger again with updateRule once the rule is active.".toString()
}

// Why RM would hold no trigger subscriptions on purpose, or null. RM removes them while
// the Required Expression is false, and a paused or stopped rule has none either.
private String _rmTriggerSubscriptionGate(Map status) {
    def appState = status?.appState
    if (appState instanceof List) {
        if (_readAppStateBoolean(status, "stopped", false)) return "stopped"
        if (_readAppStateBoolean(status, "paused", false)) return "paused"
    }
    // RM's own decoration is a styled span; a rule merely named "... (Paused)" is plain text.
    def label = status?.installedApp?.label?.toString() ?: ""
    if (label.contains(">(Required Expression false)</span>")) return "requiredExpressionFalse"
    if (label.contains(">(Paused)</span>")) return "paused"
    if (label.contains(">(Stopped)</span>")) return "stopped"
    return null
}

// Collect the hub's authoritative /hub2/appsList tree keyed by app id, for hub_list_rules'
// ghost filter (an id absent here but still in RMUtils' lagging cache is a post-delete
// ghost — hub UI lists read this tree, so we do too) and its status enrichment. Per-node
// name and disabled are stored RAW (either may be null) so _rmAnnotateRuleStatus can tell
// "field present" from "field missing"; a null RETURN means the endpoint was unreadable —
// callers surface RMUtils output unfiltered rather than dropping every rule.
private Map _collectLiveApps() {
    def responseText
    try {
        responseText = hubInternalGet("/hub2/appsList")
    } catch (Exception e) {
        mcpLog("warn", "rm-interop", "_collectLiveApps: /hub2/appsList fetch failed (${e.message})")
        return null
    }
    if (!responseText) return null
    def parsed
    try {
        parsed = new groovy.json.JsonSlurper().parseText(responseText)
    } catch (Exception e) {
        mcpLog("warn", "rm-interop", "_collectLiveApps: /hub2/appsList parse failed (${e.message})")
        return null
    }
    if (!(parsed instanceof Map) || !(parsed.apps instanceof List)) {
        mcpLog("warn", "rm-interop", "_collectLiveApps: /hub2/appsList is missing its apps list")
        return null
    }
    def apps = [:]
    boolean complete = true
    def walk
    walk = { node ->
        // A leaf may carry "children": null; only a present non-List value is malformed.
        if (!(node instanceof Map) || (node.data != null && !(node.data instanceof Map))
                || (node.children != null && !(node.children instanceof List))) {
            complete = false
            return
        }
        def idVal = node.data?.id != null ? node.data.id : node.id
        if (idVal != null) {
            try {
                // Store the RAW disabled value (may be null when the key is absent) —
                // coercing to == true here would erase the "field missing" signal that
                // _rmAnnotateRuleStatus needs to classify the rule as per-entry unknown.
                if (!(idVal.toString() ==~ /[1-9][0-9]*/)) throw new IllegalArgumentException("Invalid app ID")
                apps.put(idVal as Integer, [name: node.data?.name, disabled: node.data?.disabled])
            } catch (Exception ignored) { complete = false }
        } else if (node.data) {
            // An idless structural container is safe only when all its children can be read;
            // absent children are an empty container, not a malformed one.
            complete = false
        }
        (node?.children ?: []).each { walk(it) }
    }
    for (it in parsed.apps) { walk(it) }
    if (!complete) mcpLog("warn", "rm-interop", "_collectLiveApps: /hub2/appsList contains malformed app nodes; absence cannot be established")
    return complete ? apps : null
}

// Normalize an atTime string to the form RM 5.1 expects:
// {@code YYYY-MM-DDTHH:mm:ss.SSS+HHMM} (millis + numeric zone offset,
// no colon in the offset, e.g. {@code 2026-04-28T03:00:00.000-0500}).
//
// <p>RM 5.1's {@code selectTriggers} page render throws
// {@code java.text.ParseException: Unparseable date: ...} and enters a
// broken state if the stored {@code atTime<N>} value lacks the millis
// fraction or the timezone offset. Any subsequent trigger-add then also
// fails because the page can't render. Normalizing here prevents the
// cascade.
//
// <p><b>Format choice has SEMANTIC consequences for trigger recurrence:</b>
// <ul>
// <li>HH:mm form -- trigger fires DAILY at that wall-clock time (every day).</li>
// <li>Any ISO datetime form -- trigger fires ONCE on the specific date.</li>
// </ul>
//
// <p>Accepted input forms:
// <ol>
// <li>{@code 17:00} or {@code 5:00} -- HH:mm form; passes through unchanged.
// RM 5.1 stores this verbatim and renders the trigger as
// "When time is HH:MM AM/PM" with daily recurrence. Verified live on
// firmware 2.4.4.156: rule with {@code atTime1="22:00"} fires every day
// at 10 PM (existing rule id 825 used as reference).</li>
// <li>{@code 2026-04-28T03:00:00.000-0500} -- explicit numeric offset; normalized
// to UTC equivalent (same instant: {@code 2026-04-28T08:00:00.000+0000}). One-shot dated.</li>
// <li>{@code 2026-04-28T03:00:00} -- no millis, no tz; hub local tz applied. One-shot dated.</li>
// <li>{@code 2026-04-28T03:00:00.000} -- millis present, no tz; hub local tz applied. One-shot dated.</li>
// <li>{@code 2026-04-28T03:00:00-0500} -- no millis, explicit offset; normalized to UTC. One-shot dated.</li>
// <li>{@code 2026-04-28T03:00:00Z} -- Zulu shorthand; normalized to +0000. One-shot dated.</li>
// <li>{@code 2026-04-28T03:00:00.000Z} -- Zulu with millis; normalized to +0000. One-shot dated.</li>
// </ol>
//
// <p>Throws {@code IllegalArgumentException} for input that does not
// match any of the above forms (ASCII-only message, echoes the bad value).
// Internal _rm helper -- not part of the tool surface.
String _rmNormalizeAtTime(String raw) {
    if (!raw) throw new IllegalArgumentException("addTrigger.atTime is required when time='A specific time'")

    // HH:mm form (no date, no seconds) -- RM 5.1 accepts this directly and treats
    // it as a DAILY-RECURRING trigger that fires every day at this wall-clock time.
    // Pass through unchanged so callers can opt into daily-recurring behavior.
    // Without this branch the daily-recurring path is unreachable: the parser
    // chain below requires a YYYY-MM-DD prefix, which forces all callers into
    // ONE-SHOT dated-trigger mode. Verified live on firmware 2.4.4.156: existing
    // rule id 825 stores atTime3="22:00" and fires daily at 10 PM.
    if (raw.matches(/\d{1,2}:\d{2}/)) {
        return raw
    }

    // Canonical RM form: yyyy-MM-dd'T'HH:mm:ss.SSSZ (Z = numeric offset like -0500)
    def canonicalFormat = "yyyy-MM-dd'T'HH:mm:ss.SSSZ"

    // Attempt each known input form. The output format is always canonical.
    // Order: most-specific first so the correct parser wins without ambiguity.
    def UTC = TimeZone.getTimeZone("UTC")
    def hubTz = location.timeZone
    if (!hubTz) {
        throw new IllegalStateException("_rmNormalizeAtTime: location.timeZone is null -- hub timezone is not configured. Set the hub timezone in Settings > Location and Modes before using time-based triggers.")
    }
    def parsers = [
        // Millis + explicit numeric offset (e.g. -0500 / +0000) -- normalize to UTC
        [fmt: "yyyy-MM-dd'T'HH:mm:ss.SSSZ",    tz: UTC],
        // Millis + Z suffix
        [fmt: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",   tz: UTC],
        // No millis + explicit numeric offset -- normalize to UTC
        [fmt: "yyyy-MM-dd'T'HH:mm:ssZ",          tz: UTC],
        // No millis + Z suffix
        [fmt: "yyyy-MM-dd'T'HH:mm:ss'Z'",        tz: UTC],
        // Millis, no timezone -- use hub local tz
        [fmt: "yyyy-MM-dd'T'HH:mm:ss.SSS",       tz: hubTz],
        // No millis, no timezone -- use hub local tz
        [fmt: "yyyy-MM-dd'T'HH:mm:ss",           tz: hubTz],
    ]

    for (parser in parsers) {
        try {
            def sdf = new java.text.SimpleDateFormat(parser.fmt)
            sdf.setLenient(false)
            sdf.timeZone = parser.tz
            def parsed = sdf.parse(raw)
            // Reformat to canonical form in the same timezone used for parsing.
            // Explicit-offset inputs are normalized to UTC (same instant, +0000
            // representation). Hub-local inputs preserve the wall-clock time
            // with the hub's configured offset.
            def outSdf = new java.text.SimpleDateFormat(canonicalFormat)
            outSdf.timeZone = parser.tz
            return outSdf.format(parsed)
        } catch (java.text.ParseException ignored) {
            // try next parser
        }
    }

    throw new IllegalArgumentException(
        "addTrigger.atTime '${raw}' is not a recognized format. " +
        "Accepted forms: 'HH:mm' (e.g. '17:00' -- creates a DAILY-recurring trigger), " +
        "'YYYY-MM-DDTHH:mm:ss' (hub tz assumed -- creates a ONE-SHOT dated trigger), " +
        "'YYYY-MM-DDTHH:mm:ss.SSS' (hub tz assumed), " +
        "'YYYY-MM-DDTHH:mm:ssZ', 'YYYY-MM-DDTHH:mm:ss.SSSZ' (Zulu), " +
        "'YYYY-MM-DDTHH:mm:ss+HHMM' or 'YYYY-MM-DDTHH:mm:ss.SSS+HHMM' (explicit offset).")
}

// Single source of truth for the PRODUCTION-CODE set of
// `settingsSkipped[].reason` codes that are INFORMATIONAL (do NOT signal a
// genuine field-write failure). Consumed by both `_rmAddRequiredExpression`
// and `_rmAddAction` partial gates -- the shared `_rmWalkConditionReveal`
// walker emits the same sentinels on STPage and doActPage, so both callsites
// need an identical exemption list. Centralising it here means a future
// addition (a second informational reason code) lands in one place inside
// production code rather than requiring lockstep edits in two helpers.
//
// SCOPE CAVEAT: this list is the source of truth for production behavior
// ONLY. Doc surfaces that name reason codes literally (inline schema
// descriptions in this file's tool registrations, the inline hub_get_tool_guide
// content block, TOOL_GUIDE.md, etc.) still require manual sync when a new
// reason code is added -- there is no lint rule today that mirrors the
// discrete-event-caps-doc-parity check for reason codes. Adding such a lint
// would be the mechanical class-fix (PIPELINE.md Rule 13) that closes the
// remaining gap.
//
// Genuinely-partial reason codes (`silent_rejection`, `offset_field_not_revealed`,
// `verification_fetch_failed`, `not_in_schema`, `api_unavailable`, etc.) are NOT
// in this list and continue to flip `partial`.
// Reason-code is the disambiguator -- doc contract at the inline hub_get_tool_guide
// content block calls this list out by name.
private List _rmInformationalSkippedReasons() {
    // useST_idempotent_noop: the Step-1 useST=true mainPage toggle is idempotent
    // (safe to re-write when an expression already exists). When the toggle is
    // already set the write does not advance the schema and _rmWriteSettingOnPage
    // tags it silent_rejection; that is cosmetic, not a lost-value degradation, so
    // it is re-tagged to this informational code and must NOT flip partial.
    //
    // state_change_comparator_ignored_explicit_value: a no-RHS state-change comparator
    // ('*changed*'/'*became*') was requested on an enum attribute ALONGSIDE an explicit
    // state/value. The value lands and the rule works as an equals-check, so the dropped
    // change-comparator intent is reported informationally, NOT as a partial degradation.
    //
    // device_list_committed_schema_unchanged: a device-picker field (its committed value is
    // a List of device IDs stored in the hub's deviceIdsForDeviceList side-structure, not in
    // settings[<key>]) is the LAST write of an action and reveals no further schema, so none
    // of _rmWriteSettingOnPage's four landing detectors fire and it tags silent_rejection --
    // even though the IDs committed. The re-tag is value-echo-gated (see
    // _rmReclassifyDeviceListSkips): it only applies when the requested IDs are actually
    // present in the committed echo, so a genuine device-write FAILURE (IDs absent) keeps the
    // silent_rejection reason and still flips partial.
    return ["reveal_fallback_to_existing_field", "useST_idempotent_noop",
            "state_change_comparator_ignored_explicit_value",
            "device_list_committed_schema_unchanged"]
}

// Authoritative predicate for the "device-list field" class: a classic-app setting whose
// committed value is a List of device IDs the hub stores in a deviceIdsForDeviceList (or
// deviceList id->label) side-structure, leaving settings[<key>] null. This is the echo
// STRUCTURE, not a field-name allow-list -- it recognises every device picker (switch, lock,
// shade, thermostat, fan, ...) without enumerating each field name, and it is the single
// source of truth _rmReclassifyDeviceListSkips uses to reclassify a cosmetic device-write
// silent_rejection. Takes a status appSettings entry (the {name, value, deviceIdsForDeviceList,
// deviceList} shape from statusJson), not a config input descriptor.
private boolean _rmStatusEntryIsDeviceList(Object entry) {
    if (!(entry instanceof Map)) return false
    def e = entry as Map
    return (e.deviceIdsForDeviceList instanceof List) || (e.deviceList instanceof Map)
}

// The committed device IDs for a device-list status entry, as a Set of Strings. Reads
// a non-empty deviceIdsForDeviceList (the authoritative id list); when that is empty or absent
// it falls back to the deviceList map's keys (id->label) -- the two shapes are treated
// interchangeably, matching _rmStatusEntryIsDeviceList. Empty Set when no IDs are committed --
// which, for a requested non-empty write, means the write did NOT land (keeps the skip partial).
private Set _rmStatusEntryDeviceIds(Object entry) {
    if (!(entry instanceof Map)) return [] as Set
    def e = entry as Map
    def direct = (e.deviceIdsForDeviceList instanceof List) ? (((e.deviceIdsForDeviceList as List).collect { it?.toString() }.findAll { it }) as Set) : ([] as Set)
    if (direct) return direct
    if (e.deviceList instanceof Map) {
        return ((e.deviceList as Map).keySet().collect { it?.toString() }.findAll { it }) as Set
    }
    return direct
}

// Reclassify cosmetic device-list-write silent_rejections in `skipped` to the informational
// device_list_committed_schema_unchanged reason so they do not flip partial -- but ONLY when
// the requested IDs actually committed (value-echo-gated against statusJson). A device-picker
// field is often an action's LAST write and reveals no further schema, so _rmWriteSettingOnPage
// cannot see it land and tags silent_rejection even on success. This mutates the entries of
// `skipped` in place. A skip is left untouched (stays partial) when: it is not a
// silent_rejection, its value is not a device-id List, its status entry is absent or is not a
// device-list entry, or the requested IDs are not all present in the committed echo (a genuine
// partial/failed device write). One statusJson fetch, made only when a candidate skip exists;
// a fetch failure leaves every skip untouched (conservative -- unverifiable stays partial).
// Only a device-list picker that is an action's LAST write (revealing no further schema) earns
// the cosmetic silent_rejection this re-tags; a condition/trigger device picker advances the
// schema (a later field reveals after the pick), so it never gets the cosmetic skip.
private void _rmReclassifyDeviceListSkips(Integer appId, List skipped) {
    if (!skipped) return
    def candidates = skipped.findAll {
        it instanceof Map && it.reason == "silent_rejection" && it.value instanceof List
    }
    if (candidates.isEmpty()) return
    def status
    try {
        status = _rmFetchStatusJson(appId)
    } catch (Exception statusExc) {
        // Null-guard the identity: an exception with no message renders "(null)" from a bare
        // ${e.message}; ?: falls back to toString(), which carries the class name.
        mcpLog("warn", "rm-native", "_rmReclassifyDeviceListSkips: statusJson fetch for app ${appId} failed (${statusExc.message ?: statusExc}) -- device-list silent_rejections left as-is (stay partial)")
        return
    }
    // Defensive: a malformed appSettings shape (a scalar where a List/Map is expected, etc.)
    // must never bubble an exception up through _rmAddAction's partial computation. On any
    // post-fetch anomaly, log and leave every skip as-is (stays partial -- the conservative side).
    try {
        def byName = (status?.appSettings ?: []).findAll { it instanceof Map && it.name != null }
            .collectEntries { [(it.name.toString()): it] }
        for (sk in candidates) {
            def entry = byName[(sk.key?.toString())]
            if (!_rmStatusEntryIsDeviceList(entry)) continue
            def requested = ((sk.value as List).collect { it?.toString() }.findAll { it }) as Set
            if (requested.isEmpty()) continue
            def committed = _rmStatusEntryDeviceIds(entry)
            if (committed.containsAll(requested)) {
                sk.reason = "device_list_committed_schema_unchanged"
                sk.committedDeviceIds = committed.toList().sort()
            }
        }
    } catch (Exception reclassExc) {
        mcpLog("warn", "rm-native", "_rmReclassifyDeviceListSkips: post-fetch reclassification for app ${appId} failed (${reclassExc.message ?: reclassExc}) -- device-list silent_rejections left as-is (stay partial)")
    }
}

// Validate that every device ID in `ids` resolves on the hub. RM 5.1
// silently stores `{<bogusId>: null}` for unknown IDs in any device
// setting (rDev_<N>, tDev_<N>, switch.<N>, etc.) -- the write returns
// 200 but the rule renders with placeholder text and never fires.
// Catch this before writing so callers see a clear error instead of a
// phantom in-flight rule. Throws IllegalArgumentException on the
// first missing id with a message keyed by `label` (e.g.
// "addTrigger.deviceIds[2]"). Idempotent for List<null>/empty.
private void _rmValidateDeviceIdsExist(String label, Object ids) {
    if (!(ids instanceof List)) return
    for (id in ids) {
        def idStr = id?.toString()
        if (!idStr) continue
        def exists
        try {
            def resp = hubInternalGet("/device/fullJson/${idStr}")
            exists = (resp != null && resp.toString().length() > 0)
        } catch (Exception fetchExc) {
            // Distinguish "device truly missing" (404 / empty body) from
            // "validator unavailable" (network blip, auth-cookie expiry,
            // transient hub error). For non-404 failures, log and SKIP
            // validation rather than synthesizing a misleading
            // "device does not exist" error that steers the user toward
            // the wrong root cause.
            def msg = fetchExc.message?.toString() ?: ""
            if (msg.contains("404") || msg.toLowerCase().contains("not found")) {
                exists = false
            } else {
                mcpLog("warn", "rm-native", "_rmValidateDeviceIdsExist: ${label} validation fetch for id=${idStr} failed transiently (${msg}) -- skipping validation; the underlying hub call may have errored independent of whether the device exists")
                exists = true  // assume valid on transient failure; the actual write will fail loudly if the ID is genuinely bogus
            }
        }
        if (!exists) {
            // The not-touched sentinel is correct only where this validator runs before the
            // operation's first hub write; it is called pre-write on every current path, so the
            // refusal keeps the edit-path restoreHint accurate. (Batch callers catch per item and
            // never consult the sentinel for restoreHint.)
            throw new IllegalArgumentException("${label} contains device ID '${idStr}' which does not exist on the hub. Verify the device ID via hub_list_devices. RM is not touched.")
        }
    }
}

// Action capabilities whose primary target is another RM rule -- their ruleIds
// must resolve to an existing Rule Machine rule. Single source of truth for the
// pre-write existence guard's capability gate and the bulk-path "does this batch
// target a rule?" scan; keep it aligned with the capability branches in
// _rmAddAction that write a rule field (ruleAct / stopAct / pauseRule / privateT).
private List _rmRuleTargetCaps() { ["privateBoolean", "runRule", "cancelTimers", "pauseRule"] }

// True when an action spec's capability targets another RM rule (see _rmRuleTargetCaps).
private boolean _rmSpecTargetsRule(Object spec) {
    if (!(spec instanceof Map)) return false
    return ((spec.capability?.toString()?.trim()) in _rmRuleTargetCaps())
}

// True when any spec in a bulk action list targets another RM rule. Lets a bulk
// entry point resolve the valid-rule-id set once (and only when it is actually
// needed) and thread it to every _rmAddAction in the batch.
private boolean _rmSpecListTargetsRule(List specs) {
    return (specs ?: []).any { _rmSpecTargetsRule(it) }
}

// Normalize the rule id(s) written into a rule-targeting action field to the
// integer-canonical form; with allowThisRule, RM's "this rule" target "*" passes through as-is. A decimal-form Number (22624.0) would otherwise bake
// literally into the rule field and RM then mishandles it -- the same reason the
// trigger paths canonicalize a device id to "72" rather than "72.0". Accepts a
// scalar or a list; returns a list (RM's rule pickers are multi-select).
//
// Uses the shared _rmCoerceRuleId so a decimal-form id ("555.0") the guard accepted
// normalizes here too. A non-integer-valued id (fractional 555.9, or non-numeric "abc")
// is rejected fail-loud rather than passed on: only the cannot-verify skip path (RM not
// installed or app-tree unreadable) reaches here without the guard having validated the
// id, and there normalizeRuleId would truncate a fractional Number to a DIFFERENT existing
// rule via toInteger() -- the exact silent corruption _rmCoerceRuleId exists to prevent.
// Throwing keeps the guard and the write on the same integer-valued contract on every path.
private List _rmNormalizeRuleIdsForWrite(Object ids, boolean allowThisRule = false) {
    def idList = (ids instanceof List) ? ids : (ids != null ? [ids] : [])
    return idList.collect { id ->
        if (_rmIsThisRuleTarget(id)) {
            if (allowThisRule) return "*"
            throw new IllegalArgumentException(_rmThisRuleUnsupportedMessage("rule"))
        }
        def c = _rmCoerceRuleId(id)
        if (c == null) {
            throw new IllegalArgumentException("rule target id '${id}' is not an integer-valued rule id. Use hub_list_rules to find valid rule ids. RM is not touched.")
        }
        return c
    }
}

// RM stores a rule-targeting action aimed at its own rule as "*", alone or mixed with
// real ids (privateT.<N> = ["*","1809"]). Seen live only on Set Private Boolean.
private boolean _rmIsThisRuleTarget(Object id) {
    return id?.toString()?.trim() == "*"
}

private boolean _rmTargetAllowsThisRule(Object capability) {
    return capability?.toString() == "privateBoolean"
}

private String _rmThisRuleUnsupportedMessage(Object label) {
    return "${label} target '*' is Rule Machine's \"this rule\" target. It is supported only for privateBoolean actions; for this action use the rule's own numeric id (hub_list_rules) or edit it in the RM wizard. RM is not touched.".toString()
}

// Coerce a rule-target id to an integer-valued Integer, or null when it is not
// integer-valued. Accepts 555, 555.0, "555", "555.0" (a decimal-form string can arrive
// from JSON coercion) and rejects a fractional id (555.9 / "555.9") rather than silently
// truncating it to a different existing rule, plus non-numeric input ("abc"). The Number
// branch compares doubleValue against longValue (avoids BigDecimal-from-double rounding on
// an already-numeric id); the String branch parses via BigDecimal (integer-valued when
// stripTrailingZeros leaves scale <= 0), since toInteger() throws on any decimal point.
private Integer _rmCoerceRuleId(Object id) {
    try {
        if (id instanceof Number) {
            return (id.doubleValue() == id.longValue()) ? id.intValue() : null
        }
        def s = id?.toString()?.trim()
        if (!s) return null
        def bd = new BigDecimal(s)   // throws on non-numeric -> caught -> null
        return (bd.stripTrailingZeros().scale() <= 0) ? bd.intValue() : null
    } catch (Exception ignored) { return null }
}

// Fail loud, pre-write, when a rule-targeting action names a rule id that does not
// resolve to an existing Rule Machine rule. RM 5.1 stores an unknown id verbatim
// into the action's rule field and bakes a dangling reference that never fires and
// renders broken, with no error at write time. Resolving each id against the
// existence-safe rule-id set (the RMUtils rule list confirmed against /hub2/appsList)
// up front keeps the refusal pre-write, matching the fail-loud style of the other
// pre-write guards.
//
// validRuleIds lets a bulk caller resolve the set once and thread it to every item
// (avoids one fetch per action); a single-action caller passes null and the set is
// resolved lazily here. When the set cannot be determined -- RMUtils absent or the
// app-tree cross-check failed, both surfaced as null -- treat it as "cannot verify"
// and let the write proceed (a genuinely bogus id still bakes broken) rather than
// synthesize a misleading "rule does not exist" on a hub blip; mirrors the transient-
// skip stance of _rmValidateDeviceIdsExist. An EMPTY (non-null) set is NOT a blip --
// the rule list was read successfully and has zero valid rules -- so every rule target
// is genuinely invalid and is rejected fail-loud (only null, cannot-verify, skips).
//
// This guard wraps a bare scalar into a list (a caller may pass ruleIds as a single
// integer), BECAUSE ruleIds is not contractually required to be an array here -- the
// sibling _rmValidateDeviceIdsExist instead SKIPS a non-List input, because a bare
// integer deviceId is the very bug it exists to catch (RM stores {N:null} for it), so
// silently ignoring the scalar is the safe stance there. For a rule target the scalar
// is a legitimate single-rule reference, so it is validated rather than skipped.
private void _rmValidateRuleTargetExists(String label, Object ids, Set validRuleIds = null) {
    def idList = (ids instanceof List) ? ids : (ids != null ? [ids] : [])
    if (!idList) return
    // Shape checks need no rule list, so they run before the cannot-verify skip below.
    for (id in idList) {
        if (_rmIsThisRuleTarget(id)) {
            if (!_rmTargetAllowsThisRule(label)) throw new IllegalArgumentException(_rmThisRuleUnsupportedMessage(label))
        } else if (_rmCoerceRuleId(id) == null) {
            throw new IllegalArgumentException("${label} target rule id '${id}' is not a valid numeric rule id. Use hub_list_rules to find valid rule ids. RM is not touched.")
        }
    }
    if (idList.every { _rmIsThisRuleTarget(it) }) return
    def liveIds = (validRuleIds != null) ? validRuleIds : _rmValidRuleIds()
    if (liveIds == null) {
        // Cannot verify (RMUtils absent / tree unreadable) -> skip; an empty set (verified
        // zero rules) falls through and rejects every target. Log the skip like the sibling
        // device guard so a target that later bakes broken has a diagnostic trail.
        mcpLog("warn", "rm-native", "_rmValidateRuleTargetExists: ${label} rule-target existence check skipped -- the RM rule list was unverifiable (RMUtils lookup or /hub2/appsList read failed); a bogus rule id could bake a broken reference")
        return
    }
    for (id in idList) {
        if (_rmIsThisRuleTarget(id)) continue
        def idInt = _rmCoerceRuleId(id)
        if (!liveIds.contains(idInt)) {
            throw new IllegalArgumentException("${label} target rule id '${id}' does not exist on the hub. Use hub_list_rules to find valid rule ids. RM is not touched.")
        }
    }
}

// Map common ASCII comparator aliases to the Unicode glyphs RM 5.1's
// comparator enum accepts. Verified live 2026-05-17 on firmware
// 2.5.0.135: writing "!=" silently rejects because the enum option set
// is the Unicode "≠". Pass-through for unrecognized values so callers
// who already pass the Unicode glyphs continue to work.
// Internal _rm helper -- not part of the tool surface.
String _rmNormalizeComparator(Object raw) {
    if (raw == null) return null
    def s = raw.toString()
    if (s == "!=" || s == "<>") return "≠"
    if (s == "==") return "="
    // Bare 'contains' is never a valid RM comparator; the wizard enum offers the
    // asterisk-wrapped '*contains*' (substring match). Accept the intuitive bare
    // form (case-insensitive) so a caller who guesses it does not silently build a
    // broken rule -- an already-wrapped '*contains*' falls through unchanged.
    if (s.equalsIgnoreCase("contains")) return "*contains*"
    return s
}

// Single source of truth for the Hubitat Safety Monitor action command set (actType
// lockActs, actSubType getSetHSM, field alarm.<N>). Bare tokens exactly as RM's alarm
// enum offers them -- NOT the vue hsmArm* tokens. The handler, the validation error, and
// the discover schema must all agree on this list. No 'armAll': use 'armRules'.
private List _rmHsmCommands() {
    ["armAway", "armHome", "armNight", "disarm", "rearm", "disarmAll", "armRules", "cancelAlerts"]
}

// Internal _rm helper -- not part of the tool surface.
// Single source of truth for the RM no-RHS state-change comparator family. Each entry
// is a substring marker that identifies a comparator selecting a change EVENT rather
// than a value test, so it has no right-hand value to place in a value picker. The
// predicate below is a FAMILY gate ("is this a no-RHS comparator at all"); routing an
// option to a specific request must additionally match the exact token (see
// _rmComparatorTokensMatch). If RM adds a new no-RHS token, extend THIS list in
// lockstep -- the enum branches across the four wizard surfaces consult the predicate,
// not a private copy of the markers. Method-constant, not `static final` (script-scope
// rejects the field in the Hubitat sandbox -- see hubResponseCapBytes).
private List<String> _rmRhsOptionalComparatorMarkers() { ["changed", "became"] }

// Internal _rm helper -- not part of the tool surface.
// FAMILY gate for the no-RHS state-change comparator family. Used both to relax the
// RHS-required guards (a missing value is legitimate here) and to detect when such a
// comparator is being routed to an enum-valued attribute whose value picker cannot
// represent it. It answers "no-RHS comparator?" only. Choosing WHICH picker option to
// route a request to is the job of _rmComparatorTokensMatch (exact-token equality), never
// this gate. Matching is token-anchored, NOT a bare substring: strip the '*...*' wrapping,
// then accept only an exact marker ('changed') or a marker followed by a word ('became
// true'/'became false'). A bare-substring test misfires on unrelated comparators that
// merely CONTAIN a marker -- 'unchanged' and 'last changed date' both contain 'changed'
// but are not no-RHS state-change comparators.
boolean _rmComparatorIsRhsOptional(Object rawComparator) {
    def token = _rmComparatorToken(rawComparator)
    if (token == null) return false
    return _rmRhsOptionalComparatorMarkers().any { m -> token == m || token.startsWith(m + " ") }
}

// Internal _rm helper -- not part of the tool surface.
// Strip a comparator token to its comparable core: the '*...*' wizard wrapping and
// surrounding whitespace removed, case-folded. RM renders state-change tokens wrapped
// (e.g. '*became true*') in the picker option list but the request may arrive wrapped
// or bare; normalizing both sides lets an EXACT equality decide a route.
private String _rmComparatorToken(Object raw) {
    def s = raw?.toString()?.trim()?.toLowerCase()
    if (!s) return null
    while (s.startsWith("*")) s = s.substring(1)
    while (s.endsWith("*")) s = s.substring(0, s.length() - 1)
    s = s.trim()
    // Re-null an emptied result: an all-asterisk token ('*' / '**') strips to "",
    // which must NOT equality-match another emptied token (empty-vs-empty false match).
    return s ?: null
}

// Internal _rm helper -- not part of the tool surface.
// Exact-token equality between a requested comparator and a candidate picker option,
// after stripping the '*...*' wrapping and case-folding both sides. This is the ROUTE
// gate: a picker offering both 'became true' and 'became false' must route a
// '*became false*' request to the EXACT option, never the first RHS-optional option;
// and a picker option like 'unchanged' must NOT match a '*changed*' request. Use this
// (not the fuzzy family gate) whenever choosing which option to write.
private boolean _rmComparatorTokensMatch(Object requested, Object candidate) {
    return _rmComparatorTokenMatchesOption(_rmComparatorToken(requested), candidate)
}

// Internal _rm helper -- not part of the tool surface.
// Equality of an ALREADY-NORMALIZED requested token against a candidate picker option.
// Route sites normalize the requested comparator ONCE (hoisted out of the per-candidate
// .find) and call this; _rmComparatorTokensMatch is the un-hoisted convenience form.
private boolean _rmComparatorTokenMatchesOption(String requestedToken, Object candidate) {
    if (requestedToken == null) return false
    def b = _rmComparatorToken(candidate)
    return b != null && requestedToken == b
}

// Internal _rm helper -- not part of the tool surface.
// Normalize an enum input's `options` to a list of value strings. The hub returns
// enum-picker options in shapes that need flattening before use:
//   - bare strings: ["on", "off"]
//   - a LIST of value-key Maps: [[value:"on", text:"On"], ...] -- one option per Map
//   - a MAP container keyed by value: ["on":"On", "off":"Off"] -- value is the KEY
// A naive toString() on a value-key Map option yields "[value:on, text:On]"; iterating
// a Map CONTAINER with .collect would yield "on=On" Map.Entry strings; a bare-String
// `options` would .collect into per-CHARACTER options. Any of those corrupts the route
// probe AND the shared state_<N> domain validator that consumes this helper. The
// canonical reader for the enum route-or-skip probe and the state_<N> domain validator.
List _rmReadPickerOptionStrings(Object pickerInput) {
    def opts = pickerInput?.options
    if (opts == null) return []
    if (opts instanceof Map) {
        // Map CONTAINER: the option VALUE is the key (RM's enum value), the entry value
        // is the display label. Read the keys.
        return opts.keySet().collect { it?.toString() }.findAll { it }
    }
    if (opts instanceof CharSequence) {
        // Scalar options (a lone String): treat as a single option, never char-iterate.
        def s = opts.toString()
        return s ? [s] : []
    }
    return (opts.collect { o ->
        (o instanceof Map ? o.value?.toString() : o?.toString())
    }).findAll { it }
}

// Internal _rm helper -- not part of the tool surface.
// Canonical repair-hint for a no-RHS state-change comparator requested on an enum-valued
// Custom Attribute (the comparator_not_representable_for_enum_attribute skip). Single
// source of truth so the trigger / condition / Required-Expression emit sites cannot
// drift. ASCII-only.
private String _rmNotRepresentableEnumComparatorHint(Object attribute, Object comparator) {
    def attrName = attribute?.toString()
    def cmp = comparator?.toString()
    return "Comparator '${cmp}' cannot be represented for the enum-valued Custom Attribute '${attrName}': Rule Machine offers only a value picker (e.g. on/off) for an attribute it recognizes as an enum, with no comparator slot, so a state-change comparator has nowhere to land. Use a non-built-in attribute name, or trigger on the device's native capability instead (e.g. capability:'Switch')."
}

// The set of top-level keys an addTrigger spec is allowed to carry. Single source of
// truth for "did the caller pass a key we understand": the fail-loud shape validators
// report the leftover (unrecognized) keys, so a plausible-but-wrong shape (e.g. a bare
// `minutes` where a `periodic` map belongs) names the offending key instead of silently
// committing a broken trigger. Keep in lockstep with the triggerSpec fields read below.
private List<String> _rmRecognizedTriggerKeys() {
    ["discover", "capability", "deviceIds", "condition", "conditional",
     "periodic", "rawSettings", "variable", "comparator", "attribute", "buttonNumber",
     "modeIds", "state", "value", "time", "atTime", "offset", "allOfThese", "andStays"]
}

// Internal _rm helper -- not part of the tool surface.
// The state-change comparator family expressed as substring stems: the RHS-optional
// 'changed'/'became' forms plus the value-delta 'increased'/'decreased' forms. Built on
// _rmRhsOptionalComparatorMarkers so the changed/became stems have one owner and cannot
// drift. Used to detect a state-change token that was mistakenly supplied as `state`.
private List<String> _rmStateChangeTokenStems() { _rmRhsOptionalComparatorMarkers() + ["increased", "decreased"] }

// Internal _rm helper -- not part of the tool surface.
// True when a value looks like a state-change comparator token (wrapped '*changed*' or bare
// 'changed', 'became true', 'increased', ...). Case-folded substring test so wrapped and bare
// forms both match. Meaningful only for the capability families the guard applies to (see
// _rmStateChangeGuardApplies): device-attribute enum and numeric triggers, where the change
// semantics belong in comparator:'*changed*' and state/value holds an enum value or number
// that never contains a change stem (on/open/active/locked/42). The families the guard exempts
// (Mode, Variable, Custom Attribute, Button, time) legitimately carry a value that CAN contain
// such a stem, so the guard is scoped away from them rather than relying on this token test alone.
private boolean _rmLooksLikeStateChangeToken(Object raw) {
    def s = raw?.toString()?.toLowerCase()
    if (!s) return false
    // Fold BOTH sides: the stems come from _rmRhsOptionalComparatorMarkers(), so a
    // future marker added in mixed case must not silently defeat the case-folded match.
    // Lower-case the stems once, not per element of the any-scan.
    def stems = _rmStateChangeTokenStems().collect { it.toLowerCase() }
    return stems.any { s.contains(it) }
}

// Internal _rm helper -- not part of the tool surface.
// Resolve a trigger capability name to its FAMILY as classified in the addTrigger discover
// schema (the single source of truth). Case-insensitive, alias-aware (e.g. "Door" resolves to
// the Garage entry's device-state family). Returns null for an unrecognized capability, which
// callers treat as "unknown -- fail safe". Reuses the discover schema so the family taxonomy
// has one owner and cannot drift from the documented capability list.
private String _rmTriggerCapabilityFamily(String cap) {
    if (!cap) return null
    def wanted = cap.trim()
    def match = (_rmTriggerSchemaForDiscover()?.capabilities ?: []).find { c ->
        (c?.name?.toString()?.equalsIgnoreCase(wanted)) ||
        (c?.aliases instanceof List && (c.aliases as List).any { it?.toString()?.equalsIgnoreCase(wanted) })
    }
    return match?.family?.toString()
}

// Internal _rm helper -- not part of the tool surface.
// Best-effort "did you mean" for an unrecognized capability name. When a live options list is
// supplied (the picker/enum the caller was actually shown) it is the AUTHORITATIVE candidate
// set -- the suggestion is drawn only from it, so the "did you mean" can never name a value the
// shown list would reject (a self-contradiction). The curated discover-schema names/aliases are
// a fallback used ONLY when no live list is supplied. Exact case-fold first, then containment
// either direction (so "Contact Sensor" -> "Contact"). Both containment directions require the
// SUBSTRING to be at least 4 chars, so a short name/token ('co'/'on'/'fan') never matches as a
// spurious substring of an unrelated request. Advisory only -- it enriches an already-throwing
// message and never gates a valid capability.
private String _rmSuggestTriggerCapability(String cap, Collection liveOptions = null) {
    def want = cap?.trim()?.toLowerCase()
    if (!want) return null
    def live = (liveOptions ?: []).collect { it?.toString() }.findAll { it }
    def schemaNames = (_rmTriggerSchemaForDiscover()?.capabilities ?: []).collectMany { c ->
        def out = []
        if (c?.name != null) out << c.name.toString()
        if (c?.aliases instanceof List) (c.aliases as List).each { if (it != null) out << it.toString() }
        out
    }
    def candidates = (live ? live : schemaNames).findAll { it }.unique()
    def exact = candidates.find { it.toLowerCase() == want }
    if (exact) return exact
    return candidates.find { def n = it.toLowerCase(); (want.length() >= 4 && n.contains(want)) || (n.length() >= 4 && want.contains(n)) }
}

// Internal _rm helper -- not part of the tool surface.
// FAMILY gate for the state-change-token guard. Guard EVERY trigger capability EXCEPT the families
// whose value has no comparator channel or may legitimately be a change stem: Mode (hub-state) and
// Variable carry names/arbitrary strings; Custom Attribute's enum value may legitimately BE a change
// stem (e.g. a trend attribute's "increased"/"decreased"); the time family (Periodic Schedule /
// Certain Time / Sunrise / Sunset) exposes no tstate at all, so a state-change steer is meaningless
// there; the Button family's value is an event type (pushed / held / doubleTapped / released), not a
// comparator-backed state that offers *changed*. A DENY-LIST, not a positive device-state/numeric
// scope: an unrecognized capability (family null) is GUARDED, because the live tCapab picker accepts
// device-state/numeric caps the curated discover schema omits (Water, Smoke, Voltage, Acceleration,
// ...) and a change token on those is always the mis-supplied-comparator mistake this guard catches.
// The deny-list and a positive device-state/numeric list agree on every capability the schema
// enumerates; they differ ONLY for unlisted caps, which the deny-list correctly guards. Single owner
// shared by the add and modify paths.
private boolean _rmStateChangeGuardApplies(String cap) {
    !(_rmTriggerCapabilityFamily(cap) in ["hub-state", "variable", "custom-attribute", "time", "button"])
}

// Internal _rm helper -- not part of the tool surface.
// Return a human-readable "what is missing" message when a periodic spec is under-specified for
// its frequency (only whichPeriod would be written -> the row renders "?"/"null"), else null.
// The required-field sets are derived from the periodic WRITE block's per-frequency dispatch:
// each frequency must carry at least the field(s) that select its mode, and Monthly/Yearly need
// their full nth-weekday or by-day combo. A non-empty rawSettings map is the caller's escape
// hatch (they drive the sub-page fields directly), so the recognized-field requirement is
// skipped when it is present. Messages are ASCII-only and name the concrete fields.
private String _rmPeriodicShapeError(String freq, Map per) {
    if (per?.rawSettings instanceof Map && !(per.rawSettings as Map).isEmpty()) return null
    switch (freq) {
        case "Seconds":
            if (per.everyN == null) return "Periodic Seconds requires everyN (the count enum)."
            break
        case "Minutes":
            if (per.everyN == null && per.selectedMinutes == null) return "Periodic Minutes requires everyN ('every N minutes') or selectedMinutes ('at these minutes')."
            break
        case "Hourly":
            if (per.everyN == null && per.selectedHours == null) return "Periodic Hourly requires everyN ('every N hours') or selectedHours ('at these hours')."
            break
        case "Daily":
            if (per.everyN == null && per.weekdaysOnly != true && per.selectedDaysOfMonth == null) return "Periodic Daily requires everyN ('every N days'), weekdaysOnly:true, or selectedDaysOfMonth."
            break
        case "Weekly":
            if (per.daysOfWeek == null) return "Periodic Weekly requires daysOfWeek (list of weekday names, e.g. ['Monday','Friday'])."
            break
        case "Monthly":
            // Mutual-exclusion of dayOfMonth+weekOfMonth is rejected earlier, so here each mode's
            // full field set is required: nth-weekday needs dayOfWeek + everyNMonths; by-day needs
            // everyNMonths; neither present means no mode was selected at all.
            if (per.weekOfMonth != null) {
                def missing = []
                if (per.dayOfWeek == null) missing << "dayOfWeek"
                if (per.everyNMonths == null) missing << "everyNMonths"
                if (missing) return "Periodic Monthly nth-weekday (weekOfMonth set) also requires ${missing.join(' and ')}."
            } else if (per.dayOfMonth != null) {
                if (per.everyNMonths == null) return "Periodic Monthly by-day (dayOfMonth set) also requires everyNMonths."
            } else {
                return "Periodic Monthly requires either dayOfMonth+everyNMonths (by-day) or weekOfMonth+dayOfWeek+everyNMonths (nth-weekday)."
            }
            break
        case "Yearly":
            def missing = []
            if (per.weekOfMonth == null) missing << "weekOfMonth"
            if (per.dayOfWeek == null) missing << "dayOfWeek"
            if (per.months == null) missing << "months"
            if (missing) return "Periodic Yearly (always nth-weekday) requires ${missing.join(', ')} (e.g. weekOfMonth:'Second', dayOfWeek:'Monday', months:'December')."
            break
        case "Cron String":
            if (per.cronString == null) return "Periodic Cron String requires cronString (the cron expression, e.g. '0 0 12 * * ?')."
            break
        default:
            // Unrecognized frequency -- the periodic write block's frequency check handles it.
            return null
    }
    return null
}

// Argument-only refusal seam used before MRTR allocates requestState. Keep this
// allowlist narrower than the full leaf validation: every check here is decided
// solely from the supplied trigger map and must not read or mutate hub state.
private void _rmValidateRoundZeroTriggerSpec(Map triggerSpec) {
    if (!(triggerSpec instanceof Map) || triggerSpec.discover == true) return
    def cap = triggerSpec.capability?.toString()?.trim()
    if (!cap) return

    def effState = triggerSpec.state != null ? triggerSpec.state : triggerSpec.value
    def offendingField = triggerSpec.state != null ? "state" : "value"
    if (triggerSpec.comparator == null && _rmLooksLikeStateChangeToken(effState) &&
            _rmStateChangeGuardApplies(cap)) {
        throw new IllegalArgumentException("${offendingField}:'${effState}' is not a valid state value -- for a state-change trigger use comparator:'*changed*' (or '*became*'/'*increased*'/'*decreased*'), not ${offendingField}. Pass {discover:true} for this capability's field schema. RM is not touched.")
    }

    // time is the trigger's mode picker; the UI offers only these options, the clock rides in atTime.
    if (cap.equalsIgnoreCase("Certain Time (and optional date)") && triggerSpec.time != null &&
            !(triggerSpec.time?.toString() in ["A specific time", "Sunrise", "Sunset"])) {
        throw new IllegalArgumentException("addTrigger.time must be one of ['A specific time', 'Sunrise', 'Sunset']; got '${triggerSpec.time}'. Put the clock time in atTime (e.g. time:'A specific time', atTime:'17:30'). Pass {discover: true} for the full trigger schema. RM is not touched.")
    }

    if (cap.equalsIgnoreCase("Periodic Schedule") && !(triggerSpec.periodic instanceof Map)) {
        def strayKeys = triggerSpec.keySet().findAll {
            !(it?.toString() in _rmRecognizedTriggerKeys())
        }
        def detail
        if (triggerSpec.containsKey("periodic")) {
            detail = " periodic was supplied but is not a Map of schedule fields."
        } else if (strayKeys) {
            detail = " Received unrecognized key${strayKeys.size() == 1 ? '' : 's'}: ${strayKeys}."
        } else {
            detail = ""
        }
        throw new IllegalArgumentException("Periodic Schedule trigger requires periodic:{frequency:'Seconds'|'Minutes'|'Hourly'|'Daily'|'Weekly'|'Monthly'|'Yearly'|'Cron String', everyN:<n>, ...}.${detail} Pass {discover:true} for the full periodic field schema. RM is not touched.")
    }
}

// Pure periodic fields that historically run after device-ID prevalidation.
// Round zero invokes these only when no earlier dynamic validator can apply.
private void _rmValidateRoundZeroPeriodicSpec(Map triggerSpec) {
    def cap = triggerSpec?.capability?.toString()?.trim()
    if (!cap) return
    if (cap.equalsIgnoreCase("Periodic Schedule") && triggerSpec.periodic instanceof Map) {
        def periodic = triggerSpec.periodic as Map
        def frequency = periodic.frequency?.toString()
        if (!frequency) {
            throw new IllegalArgumentException("Periodic Schedule trigger requires periodic.frequency (one of: Seconds, Minutes, Hourly, Daily, Weekly, Monthly, Yearly, 'Cron String'). Pass {discover:true} for the full periodic field schema. RM is not touched.")
        }
        // A key the walker never reads would be dropped with no trace (e.g. time for startingTime).
        def periodicKeys = ["frequency", "everyN", "startingTime", "weekdaysOnly", "selectedHours", "selectedMinutes",
                            "selectedDaysOfMonth", "daysOfWeek", "dayOfWeek", "dayOfMonth", "everyNMonths", "months",
                            "weekOfMonth", "minutesOffset", "cronString", "rawSettings"]
        def unknownKeys = periodic.keySet().collect { it?.toString() }.findAll { !(it in periodicKeys) }
        if (unknownKeys) {
            throw new IllegalArgumentException("Periodic Schedule: unknown periodic key(s) ${unknownKeys}; accepted keys are ${periodicKeys}. Pass {discover:true} for the full periodic field schema. RM is not touched.")
        }
        if ((frequency == "Seconds" || frequency == "Minutes") && periodic.everyN != null) {
            def allowedCounts = [1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30]
            def requestedCount = null
            try { requestedCount = periodic.everyN as Integer }
            catch (Exception ignored) { requestedCount = null }
            if (requestedCount == null || !(requestedCount in allowedCounts)) {
                throw new IllegalArgumentException("Periodic ${frequency} everyN must be one of ${allowedCounts} (RM restricts the count to this enum); got '${periodic.everyN}'. RM is not touched.")
            }
        }
        if (frequency == "Monthly" && periodic.dayOfMonth != null &&
                periodic.weekOfMonth != null) {
            throw new IllegalArgumentException("Periodic Monthly: dayOfMonth and weekOfMonth are mutually exclusive -- dayOfMonth selects a calendar day (e.g. the 15th), weekOfMonth selects the Nth weekday (e.g. the Second Monday). Pass one mode's fields, not both. RM is not touched.")
        }
        def shapeErr = _rmPeriodicShapeError(frequency, periodic)
        if (shapeErr) {
            throw new IllegalArgumentException("${shapeErr} Pass {discover:true} for the full periodic field schema. RM is not touched.")
        }
    }
}

// Pure action checks in their established order. Structural checks and
// picker/existence checks need live rule state and remain inside the worker.
private void _rmValidateRoundZeroActionSpec(Map actionSpec) {
    if (!(actionSpec instanceof Map) || actionSpec.discover == true) return
    def cap = actionSpec.capability?.toString()?.trim()
    if (!cap) return
    _rmRejectUnwalkableExpressionConditions(actionSpec)

    def capLc = cap.toLowerCase()
    def expressionBearingCaps = ["ifthen", "elseif", "repeatwhile", "waitexpression"]
    if (capLc in expressionBearingCaps && actionSpec.conditions != null &&
            !(actionSpec.expression instanceof Map)) {
        throw new IllegalArgumentException("${cap} action takes expression:{conditions:[...], operator|operators}, not a top-level conditions array. Wrap them: expression:{conditions:[...], operator:'AND'}. Pass {discover:true} for the expression shape. RM is not touched.")
    }

    def action = actionSpec.action?.toString()?.trim()
    if (action == null && actionSpec.state != null &&
            _rmActionCapUsesActionVerb(cap)) {
        throw new IllegalArgumentException("${cap} action uses action: (not state:) to select the operation -- e.g. addAction(capability:'${cap}', action:'${actionSpec.state}', ...). Pass {discover:true} for this capability's action list. RM is not touched.")
    }
}

private Map _rmAddTrigger(Integer appId, Map triggerSpec) {
    // The body runs as a closure so its call sites live in the closure's own class: the app class is
    // near the JVM 65,535 constant-pool limit. Behaviour is unchanged.
    def _impl = {
    if (!(triggerSpec instanceof Map)) throw new IllegalArgumentException("addTrigger requires a Map spec. RM is not touched.")
    // Discover mode -- return static schema without touching the hub.
    // No capability field required; no Write master gate; no backup.
    if (triggerSpec.discover == true) {
        return _rmTriggerSchemaForDiscover()
    }
    _rmValidateRoundZeroTriggerSpec(triggerSpec)
    def cap = triggerSpec.capability?.toString()?.trim()
    if (!cap) throw new IllegalArgumentException("addTrigger.capability is required. Common values: Switch, Motion, Contact, Time, Periodic Schedule, Mode, Custom Attribute. Pass {discover: true} to get the full structured schema. RM is not touched.")

    // Pre-validate device IDs exist — RM 5.1 silently stores
    // {<bogusId>: null} in tDev_<N> if the ID doesn't resolve, and the
    // trigger renders as "Broken Trigger" with no event subscriptions.
    _rmValidateDeviceIdsExist("addTrigger.deviceIds", triggerSpec.deviceIds)
    if (triggerSpec.condition instanceof Map) {
        // Normalize singular deviceId -> deviceIds on the trigger.condition Map BEFORE
        // pre-validation runs **because** _rmBuildCondition's internal normalization runs
        // too late to protect _rmValidateDeviceIdsExist: validator sees the raw .deviceIds
        // list, an absent value early-returns, and the bogus singular ID surfaces only
        // as a "Broken Trigger" render later.
        def cm = triggerSpec.condition as Map
        if (cm.deviceIds == null && cm.deviceId != null) {
            cm.deviceIds = [cm.deviceId]
        }
        _rmValidateDeviceIdsExist("addTrigger.condition.deviceIds", cm.deviceIds)
    }

    _rmValidateRoundZeroPeriodicSpec(triggerSpec)
    // Preserve the legacy valid-path normalization without making the pure
    // round-zero validator mutate caller arguments.
    if (cap.equalsIgnoreCase("Periodic Schedule") && triggerSpec.periodic instanceof Map) {
        def periodic = triggerSpec.periodic as Map
        def frequency = periodic.frequency?.toString()
        if ((frequency == "Seconds" || frequency == "Minutes") && periodic.everyN != null) {
            periodic.everyN = periodic.everyN as Integer
        }
    }

    // Snapshot committed trigger indices (settings) BEFORE clicking moreCond.
    // The actual in-flight trigger idx is discovered from the schema after
    // the click — see "schema-aware index discovery" block below. We do not
    // trust existing+1 because state.moreCond can drift (e.g. if a prior
    // STPage walk or aborted wizard left the counter advanced).
    def existing = _rmCollectTriggerIndices(appId)

    // Open the trigger editor (state.moreCond=true).
    _rmClickAppButton(appId, "true", "moreCond", "selectTriggers")

    // CONDITIONAL TRIGGER PATH. When `condition` is provided, the trigger is
    // bound to a freshly-created condition. RM 5.1's wizard for conditional
    // triggers is two-stage: first stage builds a condition (consumes one
    // trigger index for the condition's setup state), second stage builds
    // the actual trigger that REFERENCES the saved condition by ID.
    // Verified live by walking the UI in Chrome with network capture
    // (firmware 2.5.0.123): clicking "Done with this Condition" advances
    // state.moreCond to the next trigger index, and the trigger that
    // follows is at idx+1, with condTrig.<idx+1>=<conditionId> binding it.
    def conditionSpec = (triggerSpec.condition instanceof Map) ? (triggerSpec.condition as Map) : null
    def conditionId = null
    def applied = []
    def skipped = []
    def idx = null
    if (conditionSpec) {
        // Conditional path: pre-compute idx via existing+1 because
        // _rmBuildCondition needs an explicit slot to write its setup
        // state into. We tolerate drift only in the non-conditional path.
        idx = (existing ? existing.max() + 1 : 1)
        conditionId = _rmBuildCondition(appId, idx, conditionSpec, applied, skipped)
        // The condition wizard advanced the trigger index by one, so the
        // actual conditional trigger now lives at idx+1. The isCondTrig
        // and condTrig writes are deferred to the post-tCapab finalize
        // block below — verified live that schema doesn't
        // expose isCondTrig.<idx+1>/condTrig.<idx+1> until tCapab<idx+1>
        // is set + tDev<idx+1>/tstate<idx+1> populated. Writing them
        // early gets silently dropped (settingsSkipped reveals
        // available=[cancelCapab, isCondTrig.<old>, tCapab<new>]).
        idx = idx + 1
    }

    // Normalize capability to the canonical case Hubitat's enum expects.
    // The tCapab<N> input is an enum and its `options` list contains
    // properly-cased labels like "Switch", "Motion", "Contact". Writing
    // a value that isn't in the list is silently rejected by Hubitat:
    // the field stays unset, the schema doesn't progress, and tDev<N>
    // never appears — leaving us to commit a phantom "**Broken
    // Trigger**" via hasAll. Match case-insensitively against the live
    // options and write back the canonical value. Verified live in
    // Chrome 2026-04-25: tCapab2='switch' rejected, tCapab2='Switch'
    // exposes tDev2 of type capability.switch.
    def capPageConfig = _rmFetchConfigJson(appId, "selectTriggers")
    def allCapInputs = (capPageConfig?.configPage?.sections ?: []).collectMany { it?.input ?: [] }
    if (idx == null) {
        // SCHEMA-AWARE INDEX DISCOVERY (non-conditional path). Find the
        // in-flight tCapab<N> for an uncommitted wizard — any N not in the
        // already-committed `existing` set. state.moreCond can be at any
        // value if a prior STPage walk or aborted wizard left the counter
        // advanced; trust the schema, not existing+1. Pick the largest
        // unmatched N (the most-recent moreCond click). Verified live
        // 2026-04-26: STPage walks left state.moreCond at 3+ on rule 1319,
        // and addTrigger using existing+1=1 errored with "tCapab1 not
        // present" until the schema-aware fix landed.
        def candidateIdxs = []
        for (inp in allCapInputs) {
            def n = inp?.name?.toString()
            if (n) {
                def m = (n =~ /^tCapab(\d+)$/)
                if (m.matches()) {
                    def cn = (m[0][1] as Integer)
                    if (!existing.contains(cn)) candidateIdxs << cn
                }
            }
        }
        if (!candidateIdxs) {
            throw new IllegalStateException("addTrigger: no in-flight tCapab<N> in selectTriggers schema after moreCond click. Existing committed: ${existing}; schema names: ${allCapInputs.collect { it?.name }.findAll { it }.join(', ')}")
        }
        idx = candidateIdxs.max()
    }
    def capInput = allCapInputs.find { it?.name == "tCapab${idx}".toString() }
    if (!capInput) throw new IllegalStateException("addTrigger: tCapab${idx} not present in selectTriggers schema -- wizard didn't open. Was the moreCond click consumed?")
    def capOptions = (capInput.options ?: []) as List
    def capCanonical = capOptions.find { it.toString().equalsIgnoreCase(cap) }
    if (!capCanonical) {
        def suggestion = _rmSuggestTriggerCapability(cap, capOptions)
        def didYouMean = suggestion ? " Did you mean '${suggestion}'?" : ""
        throw new IllegalArgumentException("addTrigger.capability '${cap}' not in Hubitat's trigger capability list.${didYouMean} Valid options: ${capOptions.collect { it.toString() }.sort().join(', ')}. Pass {discover: true} to get the per-capability field schema for each of these.")
    }
    _rmWriteSettingOnPage(appId, "selectTriggers", "tCapab${idx}", capCanonical, applied, null, skipped)

    // Helper closures (sandbox-friendly: no closure recursion on private methods)
    def writeIfPresent = { String name, Object value, String typeHint = null ->
        if (value != null) _rmWriteSettingOnPage(appId, "selectTriggers", name, value, applied, typeHint, skipped)
    }

    // Device-based capabilities use tDev<N>. Time and other non-device
    // capabilities skip this block.
    if (triggerSpec.deviceIds != null) {
        // Defense-in-depth: if the caller passed deviceIds, tDev<N> MUST
        // be in the schema after the tCapab<N> write. If it isn't, the
        // capability normalization above missed something — abort
        // before clicking hasAll on a broken half-baked trigger.
        def afterCap = _rmFetchConfigJson(appId, "selectTriggers")
        def afterInputs = (afterCap?.configPage?.sections ?: []).collectMany { it?.input ?: [] }
        if (!afterInputs.find { it?.name == "tDev${idx}".toString() }) {
            throw new IllegalStateException("addTrigger: tDev${idx} did not appear after writing tCapab${idx}=${capCanonical}; refusing to commit a broken trigger. Schema names: ${afterInputs.collect { it?.name }.findAll{it}.join(', ')}")
        }
        writeIfPresent("tDev${idx}", triggerSpec.deviceIds)
    }

    // Hub Variable trigger: tCapab<N>=Variable exposes xVar<N> (variable
    // picker, no device IDs). Comparator is the standard ReltDev<N> below.
    // Verified live 2026-05-17: xVar<N> options are populated from the
    // hub variables list; writing it advances the schema to expose
    // ReltDev<N>.
    if (capCanonical == "Variable") {
        if (triggerSpec.rawSettings != null && !(triggerSpec.rawSettings instanceof Map)) {
            throw new IllegalArgumentException("triggers[].rawSettings must be a Map, got ${triggerSpec.rawSettings.class?.name}.")
        }
        def hasRawXVar = triggerSpec.rawSettings instanceof Map &&
            ((triggerSpec.rawSettings as Map).any { k, _v -> k.toString().replace("@N", idx.toString()) == "xVar${idx}".toString() })
        if (triggerSpec.variable == null && !hasRawXVar) {
            throw new IllegalArgumentException("triggers[].variable is required when capability='Variable' (hub variable name). Use hub_list_variables to discover available names.")
        }
        if (triggerSpec.variable != null) {
            writeIfPresent("xVar${idx}", triggerSpec.variable)
        }
    }

    // Numeric / text comparator path (Temperature, Humidity, Battery,
    // Custom Attribute, Variable, etc.) Some comparators on the live
    // wizard are Unicode (e.g. '≠' for not-equal). Normalize common
    // ASCII aliases so callers can pass "!=" / "==" / "<>".
    if (triggerSpec.comparator != null) {
        // Trigger-row site of the enum-recognized Custom Attribute comparator
        // invariant (see _rmForceWriteEnumField docstring for the authoritative
        // rule). Fields here: comparator=ReltDev<N>, value picker=tstate<N>. The
        // schema-gated writeIfPresent path means a neither-rendered comparator
        // records not_in_schema (not silent dead-storage); a throwing re-fetch
        // force-writes the comparator best-effort and flags partial.
        if (triggerSpec.attribute != null) {
            writeIfPresent("tCustomAttr${idx}", triggerSpec.attribute)
            def afterAttr = null
            try {
                // The writeIfPresent helper does not return the post-write schema, so
                // this GET is the only way to see which fields the rCustomAttr re-render
                // exposed (comparator vs value picker). Necessary, not redundant.
                afterAttr = _rmFetchConfigJson(appId, "selectTriggers")
            } catch (Exception fetchEx) {
                mcpLog("warn", "rm-native", "addTrigger Custom Attribute: re-fetch after tCustomAttr${idx}='${triggerSpec.attribute}' failed for app ${appId} (${fetchEx.message ?: fetchEx}); force-writing comparator ReltDev${idx} as fallback (partial)")
            }
            if (afterAttr == null) {
                _rmForceWriteEnumField(appId, "selectTriggers", "ReltDev${idx}".toString(), _rmNormalizeComparator(triggerSpec.comparator), applied, skipped)
            } else {
                def afterAttrInputs = (afterAttr?.configPage?.sections ?: []).collectMany { it?.input ?: [] }
                def comparatorExposed = afterAttrInputs.any { it?.name == "ReltDev${idx}".toString() }
                def valuePickerExposed = afterAttrInputs.any { it?.name == "tstate${idx}".toString() }
                // Comparator-first: write whenever exposed; suppress only the true enum
                // case; neither-exposed still attempts (schema-gated -> not_in_schema).
                if (comparatorExposed) {
                    writeIfPresent("ReltDev${idx}", _rmNormalizeComparator(triggerSpec.comparator))
                } else if (!valuePickerExposed) {
                    writeIfPresent("ReltDev${idx}", _rmNormalizeComparator(triggerSpec.comparator))
                } else {
                    // ENUM-recognized attribute: only the value picker tstate<N> is exposed,
                    // the comparator ReltDev<N> is hidden. A value comparator's value lands in
                    // tstate<N> below -- correct, nothing to do here. The no-RHS family is
                    // gated by _rmComparatorIsRhsOptional (single-source-of-truth markers in
                    // _rmRhsOptionalComparatorMarkers -- extend BOTH in lockstep if RM adds a
                    // new no-RHS token, or this branch silently falls through). A state-change
                    // comparator ('*changed*' / '*became*') has NO right-hand value, so it
                    // cannot ride the value picker; the routing here applies ONLY when no
                    // explicit value was supplied. If the picker offers an option matching the
                    // REQUESTED change token exactly, the generic tstate<N> write below will
                    // place it; otherwise the comparator is genuinely unrepresentable through
                    // this path and must NOT be silently dropped as clean success (the bug). When
                    // an explicit value WAS supplied it wins and lands in tstate<N> below -- the
                    // change-comparator intent is moot, not routed here.
                    if (_rmComparatorIsRhsOptional(triggerSpec.comparator)) {
                        def stateVal = triggerSpec.state != null ? triggerSpec.state : triggerSpec.value
                        if (stateVal != null) {
                            // Contradictory request: a state-change comparator AND an explicit
                            // value. The value lands in tstate<N> below and the rule works as an
                            // equals-check, so the change-comparator intent is dropped -- but
                            // honestly, via an INFORMATIONAL skip that does NOT flip partial.
                            skipped << [key: "ReltDev${idx}".toString(), reason: "state_change_comparator_ignored_explicit_value",
                                        value: _rmNormalizeComparator(triggerSpec.comparator), attribute: triggerSpec.attribute?.toString()]
                        } else {
                            def pickerInput = afterAttrInputs.find { it?.name == "tstate${idx}".toString() }
                            // Family gate passed; now require an EXACT token match between the
                            // requested comparator and a picker option (not just any RHS-optional
                            // option), so 'became false' never routes to a 'became true' slot and
                            // 'unchanged' never satisfies a '*changed*' request. Normalize the
                            // requested token ONCE, not per-candidate.
                            def reqToken = _rmComparatorToken(triggerSpec.comparator)
                            def changeOption = _rmReadPickerOptionStrings(pickerInput).find { _rmComparatorTokenMatchesOption(reqToken, it) }
                            if (changeOption != null) {
                                // The picker offers the exact requested change option -- route it
                                // through the generic tstate<N> write so the trigger actually fires.
                                triggerSpec.state = changeOption
                            } else {
                                // The accumulator is the local `skipped` list -- always present on
                                // this path; recording the skip is the whole point here, never a no-op.
                                skipped << [key: "ReltDev${idx}".toString(), reason: "comparator_not_representable_for_enum_attribute",
                                            value: _rmNormalizeComparator(triggerSpec.comparator), attribute: triggerSpec.attribute?.toString()]
                            }
                        }
                    }
                }
            }
        } else if (_rmComparatorIsRhsOptional(triggerSpec.comparator)) {
            // An RHS-optional (state-change) comparator on a non-Custom-Attribute capability.
            // Route the change token by what the LIVE wizard renders for this trigger index,
            // NOT the curated family taxonomy: the taxonomy lists only seven device-state caps,
            // so gating on it misroutes every OTHER live device-state cap (Water/Smoke/CO/...)
            // to ReltDev<N>, which lands not_in_schema and renders the trigger
            // "turns null" (fires on any event). The presence of the ReltDev<N> comparator field
            // IS the authoritative "this cap takes a comparator" signal (numeric/text caps expose
            // it -- '*changed*' is a real option there; a device-state enum cap does NOT -- its
            // change option rides the tstate<N> value picker). Deciding on the rendered field
            // means this route covers EVERY capability the F9 state-change guard steers, and
            // cannot disagree with that guard's deny-list -- neither now relies on the family list.
            def explicitVal = triggerSpec.state != null ? triggerSpec.state : triggerSpec.value
            def dsCfg = null
            try {
                dsCfg = _rmFetchConfigJson(appId, "selectTriggers")
            } catch (Exception dsEx) {
                // Never abort on a transient re-fetch (the F9 contract) -- degrade below.
                mcpLog("warn", "rm-native", "addTrigger: re-fetch of selectTriggers after device write failed for app ${appId} (${dsEx.message ?: dsEx}); state-change comparator ${_rmNormalizeComparator(triggerSpec.comparator)} routed unverified (partial)")
            }
            def dsInputs = dsCfg == null ? null : (dsCfg?.configPage?.sections ?: []).collectMany { it?.input ?: [] }
            def hasComparatorField = dsInputs != null && dsInputs.any { it?.name == "ReltDev${idx}".toString() }
            def dsPicker = dsInputs == null ? null : dsInputs.find { it?.name == "tstate${idx}".toString() }
            if (hasComparatorField) {
                // Numeric/text comparator cap: '*changed*' is a real ReltDev<N> option -- write it.
                writeIfPresent("ReltDev${idx}", _rmNormalizeComparator(triggerSpec.comparator))
            } else if (dsPicker != null) {
                // Device-state enum cap: the tstate<N> value picker carries the change option.
                if (explicitVal != null) {
                    // Contradictory request: an explicit state AND a change comparator. The value
                    // lands in tstate<N> below and wins, so the change intent is dropped -- report
                    // it via an INFORMATIONAL skip that does NOT flip partial (matches the enum
                    // Custom Attribute sibling). Key on a SYNTHETIC comparator@tstate<N> so the
                    // real tstate<N> field is never listed in BOTH settingsApplied and
                    // settingsSkipped (the applied/skipped-disjoint invariant).
                    skipped << [key: "comparator@tstate${idx}".toString(), reason: "state_change_comparator_ignored_explicit_value",
                                value: _rmNormalizeComparator(triggerSpec.comparator), capability: capCanonical?.toString()]
                } else {
                    // Match the requested token against the picker's actual options rather than
                    // hardcoding a literal (RM may store it wrapped, e.g. '*changed*'). Read the
                    // option strings ONCE. Route the EXACT match into tstate<N> via the generic
                    // write below.
                    def reqToken = _rmComparatorToken(triggerSpec.comparator)
                    def pickerOptions = _rmReadPickerOptionStrings(dsPicker)
                    def changeOption = pickerOptions.find { _rmComparatorTokenMatchesOption(reqToken, it) }
                    if (changeOption != null) {
                        triggerSpec.state = changeOption
                    } else {
                        // The value picker offers no matching change option -- surface a GENUINE
                        // skip (-> partial) keyed on the real tstate<N> field (which received no
                        // value, so no applied/skipped collision) rather than silently landing
                        // ReltDev<N> not_in_schema. The skip carries its own precise walkStep hint.
                        skipped << [key: "tstate${idx}".toString(), reason: "change_comparator_not_representable_for_device_state",
                                    value: _rmNormalizeComparator(triggerSpec.comparator), capability: capCanonical?.toString(),
                                    pickerOptions: pickerOptions,
                                    hint: "The '${capCanonical}' value picker (tstate${idx}) offers no option matching the change comparator '${_rmNormalizeComparator(triggerSpec.comparator)}' (options: ${pickerOptions}). Write tstate${idx} directly via a walkStep call if the picker uses a change token that this route does not match."]
                    }
                }
            } else {
                // Neither the comparator field (ReltDev<N>, numeric caps) nor the value picker
                // (tstate<N>, device-state enum caps) rendered for this row. Route by curated
                // family and fetch outcome.
                def capFamily = _rmTriggerCapabilityFamily(capCanonical?.toString())
                if (dsInputs == null) {
                    // Transient re-fetch failure: the rendered field is unknown. A numeric
                    // (comparator-bearing) capability takes '*changed*' as a real ReltDev<N>
                    // option, so force-write it to preserve the pre-redesign infallibility
                    // (mirrors the Custom Attribute fetch-failure force-write). Device-state and
                    // unknown families ride a value picker whose exact option string is only
                    // knowable from the fetch that just failed, so a false write is worse than a
                    // flagged partial -- degrade with a verify-and-repair hint (never abort, the
                    // F9 contract).
                    if (capFamily == "numeric") {
                        _rmForceWriteEnumField(appId, "selectTriggers", "ReltDev${idx}".toString(), _rmNormalizeComparator(triggerSpec.comparator), applied, skipped)
                    } else if (capFamily == "hub-state") {
                        // Mode (hub-state) carries its change semantics through modesX<N>, written
                        // by the Mode path below -- so a stray change comparator here has no route
                        // to place regardless of the failed re-fetch. Recording the unverified-route
                        // skip would flip partial before that clean commit; leave it for the Mode
                        // path (mirrors the fetch-success neither-field hub-state no-op below).
                    } else {
                        // Unlike the other genuine skips, this one keys on a SYNTHETIC
                        // comparator@tstate<N> rather than the real field name (the fetch failed,
                        // so the real field -- tstate<N> vs ReltDev<N> -- is unknown). The repair
                        // target therefore lives in the hint, not the key; TOOL_GUIDE / the served
                        // guide say the same.
                        skipped << [key: "comparator@tstate${idx}".toString(), reason: "state_change_route_unverified_fetch_failed",
                                    value: _rmNormalizeComparator(triggerSpec.comparator), capability: capCanonical?.toString(),
                                    hint: "The selectTriggers schema could not be re-fetched to place the state-change comparator '${_rmNormalizeComparator(triggerSpec.comparator)}'. Verify via hub_get_app_config(appId); if the change did not land, write tstate${idx} (device-state enum caps) or ReltDev${idx} (numeric caps) directly via a walkStep call."]
                    }
                } else if (capFamily == "hub-state") {
                    // Mode (hub-state) carries its change semantics through modesX<N>, written by
                    // the Mode path below -- a phantom ReltDev<N> here would record not_in_schema
                    // (partial) before that clean commit. Leave it for the Mode path.
                } else {
                    // Schema rendered but neither field present (an unexpected wizard state for a
                    // device-state capability). The change token cannot be placed, and any
                    // explicit value cannot ride the absent tstate<N> -- so do NOT claim it
                    // committed. Surface the specific device-state reason (keyed on the synthetic
                    // comparator@tstate<N> so a downstream tstate<N> value write, when an explicit
                    // value was supplied, is never double-listed) rather than a bare ReltDev<N>
                    // not_in_schema whose generic "introspect and re-write" advice would misdirect.
                    skipped << [key: "comparator@tstate${idx}".toString(), reason: "change_comparator_not_representable_for_device_state",
                                value: _rmNormalizeComparator(triggerSpec.comparator), capability: capCanonical?.toString(),
                                hint: "The '${capCanonical}' trigger rendered neither a comparator field (ReltDev${idx}) nor a value picker (tstate${idx}) for the state-change comparator '${_rmNormalizeComparator(triggerSpec.comparator)}'. Re-fetch via hub_get_app_config(appId) and author the change directly via a walkStep call."]
                }
            }
        } else {
            // Non-RHS-optional numeric/text comparator (>, <, =, ...) on a standard capability --
            // the comparator field is already in the schema; write it directly.
            writeIfPresent("ReltDev${idx}", _rmNormalizeComparator(triggerSpec.comparator))
        }
    }

    // Button capability has its own button-number field.
    if (triggerSpec.buttonNumber != null) {
        writeIfPresent("ButtontDev${idx}", triggerSpec.buttonNumber)
    }

    // MODE CAPABILITY -- special-case BEFORE the generic tstate path.
    //
    // RM 5.1 Mode triggers do NOT use tstate<N>. The correct field is
    // modesX<N>, which takes a List of mode IDs (String representations of
    // Long IDs from location.modes). Writing tstate<N> for a Mode trigger
    // causes: tCapab<N>=Mode lands, tstate<N> is silently ignored, and the
    // trigger renders as "**Broken Trigger**" because modesX<N> is absent.
    //
    // Two input shapes are accepted:
    //   state  -- String or List<String> of mode NAMES (e.g. "Night" or
    //             ["Away", "Night"]). Names are resolved to IDs via
    //             location.modes. Case-insensitive. All names must resolve;
    //             unresolved names throw IllegalArgumentException with the
    //             full valid-modes list so the caller can correct the input.
    //   modeIds -- List<Integer or String> of mode IDs. Written directly as
    //              String values inside a List (e.g. ["3"] or ["3", "5"]).
    //
    // Verified live (zero-context validation 2026-05-02): two agents
    // hit this pattern (rules 1319, 1320), each spending 30+ extra tool calls
    // deleting and rebuilding the rule because tstate<N> silently no-ops.
    if (capCanonical == "Mode") {
        def rawModeIds = []
        if (triggerSpec.modeIds instanceof List) {
            // Caller supplied IDs directly -- convert each to String.
            rawModeIds = (triggerSpec.modeIds as List).collect { it?.toString() }.findAll { it }
        } else {
            // Resolve mode name(s) from location.modes. Support single
            // String or List<String>.
            def nameInput = triggerSpec.state
            def modeNames = (nameInput instanceof List) ? (nameInput as List) : (nameInput != null ? [nameInput] : [])
            if (modeNames.isEmpty()) {
                throw new IllegalArgumentException("addTrigger Mode requires state (mode name or list of mode names) or modeIds (list of mode IDs)")
            }
            def allModes = location.modes ?: []
            def validModeNames = allModes.collect { it?.name?.toString() }.findAll { it }
            for (mn in modeNames) {
                def matched = allModes.find { it?.name?.toString()?.equalsIgnoreCase(mn?.toString()) }
                if (!matched) {
                    def commaHint = _rmCommaJoinedModeHint(mn, validModeNames, "addTrigger Mode")
                    if (commaHint) throw new IllegalArgumentException(commaHint)
                    throw new IllegalArgumentException("addTrigger Mode: mode name '${mn}' not found. Valid modes: ${validModeNames.sort().join(', ')}")
                }
                rawModeIds << matched.id.toString()
            }
        }
        if (rawModeIds.isEmpty()) {
            throw new IllegalArgumentException("addTrigger Mode: no mode IDs resolved -- pass state with valid mode name(s) or modeIds with mode ID(s)")
        }
        // A directly-passed integer ID skips the name-resolution check above, so
        // reject any ID no hub mode carries before it commits a mode-less row.
        def modeCheck = _rmBadModeIds(rawModeIds, null)
        if (modeCheck.bad) {
            throw new IllegalArgumentException("addTrigger Mode: mode ID(s) ${modeCheck.bad.join(', ')} not offered by ${modeCheck.source}. Valid IDs: ${modeCheck.valid.sort().join(', ')}")
        }
        writeIfPresent("modesX${idx}", rawModeIds)
    } else {
        // tstate<N> covers both enum-state ("on"/"active") and numeric value
        // (Temperature reading) paths. value field is the numeric form.
        // NOT used for Mode (see special-case above) -- Mode uses modesX<N>.
        def stateValue = triggerSpec.state != null ? triggerSpec.state : triggerSpec.value
        if (stateValue != null) {
            writeIfPresent("tstate${idx}", stateValue)
        }
    }

    // Time-based capability uses time1, atTime1, atSunriseOffset1 etc.
    // The wizard uses index 1 for the time fields regardless of trigger
    // index because RM models time triggers as singletons within the
    // trigger row -- the index is on the wrapper trigger, not the inner
    // time picker. (Verified live on firmware 2.5.0.123.)
    //
    // BUG A FIX: when caller provides atTime but omits time, infer
    // time='A specific time' automatically. atTime is only meaningful
    // for the wall-clock path; Sunrise/Sunset use offset instead.
    // Without this inference the entire time block was silently skipped
    // (the if-guard required time != null), leaving atTime unwritten and
    // the trigger rendering as "Certain Time **Broken Trigger**".
    def effectiveTime = triggerSpec.time
    if (effectiveTime == null && triggerSpec.atTime != null) {
        effectiveTime = "A specific time"
    }
    if (effectiveTime != null) {
        writeIfPresent("time${idx}", effectiveTime)
        if (triggerSpec.atTime != null) {
            // RM 5.1's selectTriggers page parser requires the full
            // 'YYYY-MM-DDTHH:mm:ss.SSS+HHMM' form. Short ISO forms
            // (no millis, no tz, or Zulu 'Z' suffix) cause
            // ParseException on every page render, blocking all
            // subsequent trigger additions with no recovery path short
            // of deleting the rule. Normalize before writing.
            writeIfPresent("atTime${idx}", _rmNormalizeAtTime(triggerSpec.atTime.toString()))
        }
        if (triggerSpec.offset != null) {
            def t = effectiveTime?.toString()
            if (t == "Sunrise") writeIfPresent("atSunriseOffset${idx}", triggerSpec.offset)
            else if (t == "Sunset") writeIfPresent("atSunsetOffset${idx}", triggerSpec.offset)
        }
    }

    // Optional modifier fields.
    if (triggerSpec.allOfThese == true) writeIfPresent("AlltDev${idx}", true)
    if (triggerSpec.andStays instanceof Map) {
        writeIfPresent("stays${idx}", true)
        def s = triggerSpec.andStays as Map
        // RM's allHandler computes total wait time as SHours*3600 + SMins*60
        // + SSecs and crashes with NullPointerException on .multiply() if
        // any of the three are null when the trigger fires. Always write
        // all three (default 0) so the math survives even when caller only
        // specified one component (e.g. minutes: 2). Verified live: rule
        // with stays=true and only SMins=2 NPEs on the next contact event;
        // adding SHours=0 + SSecs=0 fixes it.
        writeIfPresent("SHours${idx}", s.hours != null ? s.hours : 0)
        writeIfPresent("SMins${idx}", s.minutes != null ? s.minutes : 0)
        writeIfPresent("SSecs${idx}", s.seconds != null ? s.seconds : 0)
    }

    // Caller escape hatch. Supports the '@N' token in field names —
    // replaced with the auto-assigned trigger index. Matches addAction's
    // rawSettings expansion (verified live 2026-05-17): users pass
    // `xVar@N` and the helper writes `xVar1` (or whatever idx landed on).
    if (triggerSpec.rawSettings instanceof Map) {
        for (Map.Entry entry in triggerSpec.rawSettings) {
            def k = entry.key
            def v = entry.value
            def fieldName = k.toString().replace("@N", idx.toString())
            writeIfPresent(fieldName, v)
        }
    }

    // Periodic Schedule: navigate the dedicated periodic sub-page, write
    // the frequency-specific fields, and submit Done so the trigger row's
    // description bakes ("Every 1 hour starting at 1:00 PM" etc.).
    // Without this dance, hasAll commits a phantom row with description="?"
    // because the parent's renderer can't reach the sub-page state.
    //
    // Field BASE names are IRREGULAR across frequencies (everyNHC vs everyNDC
    // vs everyNSecs -- no shared stem to extract), so freqFieldMap below carries
    // the exact RM 5.1 base name for each role of each frequency, captured live
    // against fw 5.1.8. The per-trigger SUFFIX, by contrast, is uniform: every
    // field ends in the resolved sub-page index pn (interpolated below).
    if (capCanonical == "Periodic Schedule" && triggerSpec.periodic instanceof Map) {
        def per = triggerSpec.periodic as Map
        def freq = per.frequency?.toString()
        if (!freq) {
            throw new IllegalArgumentException("Periodic Schedule trigger requires periodic.frequency (one of: Seconds, Minutes, Hourly, Daily, Weekly, Monthly, Yearly, 'Cron String')")
        }
        // Monthly mode detection: weekOfMonth present selects nth-weekday mode,
        // which hides the by-day fields. (A by-day+weekOfMonth mix was already
        // rejected up front, so here weekOfMonth presence unambiguously means
        // nth-weekday.)
        def monthlyNthWeekday = (freq == "Monthly" && per.weekOfMonth != null)
        // Resolve the periodic sub-page navigation from the LIVE selectTriggers
        // schema rather than hardcoding it. RM renders the periodic href once
        // the in-flight trigger's capability is Periodic Schedule; the href
        // carries params={n: <trigger index>} keyed to THIS trigger, and the
        // sub-page's field names are suffixed by that same n (whichPeriod<n>,
        // everyNDoMC<n>, ...). For a single periodic trigger n=1 -- byte-identical
        // to suffix-1. For a 2nd periodic trigger RM renders a periodic<n> sub-page
        // with whichPeriod<n>/everyN*C<n>/etc.; routing to the right n AND writing
        // the n-suffixed field names is what keeps the two triggers from colliding.
        // Mirrors the walkStep navigate href-discovery.
        def periodicHrefName = "periodic1"
        def periodicHrefParams = [n: 1]
        def periodicHrefFound = false
        def periodicHrefDiscoveryError = null
        try {
            def stCfg = _rmFetchConfigJson(appId, "selectTriggers")
            def periodicHref = (stCfg?.configPage?.sections ?: []).collectMany { sect ->
                (sect?.body ?: []).findAll { b -> b instanceof Map && b.element == "href" && b.page?.toString() == "periodic" }
            }.find { it != null }
            if (periodicHref != null) {
                periodicHrefFound = true
                if (periodicHref.name != null) periodicHrefName = periodicHref.name.toString()
                if (periodicHref.params instanceof Map) periodicHrefParams = periodicHref.params as Map
            }
        } catch (Exception hrefExc) {
            periodicHrefDiscoveryError = "${hrefExc.class.simpleName}: ${hrefExc.message}".toString()
            mcpLog("warn", "rm-native", "_rmAddTrigger: periodic href discovery on selectTriggers failed for app ${appId} (in-flight trigger idx ${idx}) (${periodicHrefDiscoveryError}) -- falling back to periodic1/n=1; a non-first periodic trigger may collide with the first")
        }
        // Href absent (not an exception, but still a discovery failure): warn the
        // same way, because suffix-1 fallback is only safe for the FIRST periodic
        // trigger. RM keys the periodic sub-page by trigger index, so without the
        // discovered href a later periodic trigger would write suffix-1 fields and
        // clobber the first trigger's schedule.
        if (!periodicHrefFound) {
            mcpLog("warn", "rm-native", "_rmAddTrigger: no periodic href found in selectTriggers schema for app ${appId} (in-flight trigger idx ${idx}) -- falling back to periodic1/n=1")
        }
        // The marker form-index suffix uses params.n (matches walkStep navigate).
        // Guard the cast: a malformed params.n (non-integer) would otherwise escape
        // to the outer catch as a raw context-less JVM message; fall back to 1 and
        // flag it so the fallback decision below treats a discovered-but-malformed
        // href the same as an absent one (both leave us unable to target the right
        // sub-page index, which is unsafe for a non-first trigger).
        def periodicHrefIndex = 1
        def periodicNMalformed = false
        if (periodicHrefParams?.n != null) {
            try {
                periodicHrefIndex = periodicHrefParams.n as Integer
            } catch (Exception nCastExc) {
                periodicNMalformed = true
                mcpLog("warn", "rm-native", "_rmAddTrigger: periodic href params.n='${periodicHrefParams.n}' is not an integer for app ${appId} (in-flight trigger idx ${idx}) (${nCastExc.class.simpleName}: ${nCastExc.message}) -- falling back to n=1")
                periodicHrefIndex = 1
            }
        }
        // Normalize params.n to the resolved integer index. Downstream re-casts
        // (_rmSubmitSubPageDone re-reads hrefParams.n as Integer) must operate on a
        // clean Integer so a malformed value the cast guard above already absorbed
        // can't re-throw past this point. Build a fresh map -- never mutate the
        // discovered params.
        def hrefParams = (periodicHrefParams instanceof Map ? (periodicHrefParams as Map) : [:]) + [n: periodicHrefIndex]
        // If we cannot reliably target this trigger's own sub-page index -- the href
        // was NOT discovered OR its params.n was malformed -- AND this is not the
        // first trigger slot, suffix-1 fallback would silently overwrite an earlier
        // periodic trigger. Refuse to write a guaranteed clobber: record a skip so
        // the row surfaces partial=true with an actionable repair hint, and leave
        // the periodic sub-page writes unattempted for this trigger. (idx is provably
        // Integer here -- assigned from the resolved trigger index -- so its cast is
        // unguarded, unlike the hub-supplied params.n above.)
        def periodicUnsafeFallback = ((!periodicHrefFound || periodicNMalformed) && (idx as Integer) > 1)
        if (periodicUnsafeFallback) {
            def unsafeReason = periodicHrefDiscoveryError != null ? "periodic href discovery failed (${periodicHrefDiscoveryError})"
                             : !periodicHrefFound ? "periodic href absent from selectTriggers schema"
                             : "periodic href params.n malformed"
            skipped << [key: "periodic", reason: "periodic_href_unresolved_nonfirst_trigger", value: freq,
                        note: "Cannot resolve the periodic sub-page index for trigger idx ${idx} (${unsafeReason}); writing suffix-1 fields would overwrite an earlier periodic trigger. Periodic sub-page not written."]
            mcpLog("warn", "rm-native", "_rmAddTrigger: skipping periodic sub-page writes for app ${appId} trigger idx ${idx} -- ${unsafeReason} and idx>1, suffix-1 fallback would clobber the first periodic trigger")
        } else if (periodicNMalformed || periodicHrefDiscoveryError != null) {
            // Safe path (idx==1, suffix-1 is correct) but a discovery anomaly still
            // occurred. Surface a breadcrumb in the response so a hub systematically
            // emitting bad periodic hrefs shows up as more than scattered hub logs.
            def anomaly = periodicNMalformed ? "periodic href params.n malformed (resolved to 1)" : "periodic href discovery threw (${periodicHrefDiscoveryError})"
            skipped << [key: "periodic", reason: "periodic_href_anomaly_firsttrigger", value: freq,
                        note: "${anomaly}; suffix-1 was used and is correct for the first periodic trigger, but verify the schedule rendered via hub_get_app_config."]
        }
        // Periodic field names are suffixed by the per-trigger sub-page index
        // (pn). For pn=1 the field names end in ...C1; for a later periodic
        // trigger pn follows the discovered sub-page index, so the names become
        // ...C<pn> and target that trigger's own sub-page slots.
        def pn = periodicHrefIndex

        // Field-name maps. Keys are role aliases; values are the RM 5.1 setting
        // names with the per-trigger suffix interpolated.
        //
        // Role keys (not all frequencies have all roles):
        //   everyNToggle  -- bool, "every n <unit>?"; must land BEFORE everyNCount
        //   everyNCount   -- the count; for Hourly/Daily a free integer, for
        //                    Minutes a restricted enum (validated up front). Seconds
        //                    is equally restricted, via secondsCount below.
        //   secondsCount  -- Seconds has NO toggle; the count enum IS the mode
        //                    (restricted enum, same allowed set as Minutes)
        //   selectMulti   -- multi-enum picker (hours / days-of-month / days-of-week / minutes)
        //   weekdayToggle -- Daily-only "weekdays only"
        //   dayOfMonth    -- Monthly by-day "on day number"
        //   everyNMonths  -- Monthly by-day "of every n months"
        //   weekOfMonth   -- Monthly/Yearly nth-weekday "in the week of month" (First..Last)
        //   dayOfWeek     -- Monthly/Yearly nth-weekday SINGLE day-of-week (Sunday..Saturday)
        //   everyNMonthsNth -- Monthly nth-weekday cadence (everyNMCX<n>, the X-suffixed field)
        //   monthEnum     -- Yearly nth-weekday single month (yearlyMonthCX<n>, the X-suffixed field)
        //   time          -- "starting at" time field
        //   offset        -- Hourly-only minute offset
        //   cron          -- Cron String text field
        //
        // Monthly and Yearly are MODE-PROGRESSIVE: writing the week-of-month
        // field swaps the visible field set (mutually exclusive with the by-day
        // fields). The dispatch below routes by whether weekOfMonth is present.
        def freqFieldMap = [
            "Seconds": [secondsCount: "everyNSecs${pn}"],
            "Minutes": [everyNToggle: "everyNMinutesC${pn}", everyNCount: "everyNC${pn}", selectMulti: "selectMinutesC${pn}"],
            "Hourly":  [everyNToggle: "everyNHoursC${pn}", everyNCount: "everyNHC${pn}", time: "startingHC${pn}", selectMulti: "selectHoursC${pn}", offset: "startingHCX${pn}"],
            "Daily":   [everyNToggle: "everyNDoMC${pn}",   everyNCount: "everyNDC${pn}", time: "startingDC${pn}", weekdayToggle: "everyWeekDay${pn}", selectMulti: "selectDoMC${pn}"],
            "Weekly":  [selectMulti: "selectDoWC${pn}", time: "startingWC${pn}"],
            // Monthly carries BOTH mode field sets; dispatch picks one by weekOfMonth presence.
            // (Specific-months "on day N of selected months" is a THIRD, order-sensitive
            // sub-mode that the flat routing can't satisfy -- not supported here.)
            "Monthly": [dayOfMonth: "dayMC${pn}", everyNMonths: "everyNMC${pn}",
                        weekOfMonth: "weeklyMC${pn}", dayOfWeek: "dailyMC${pn}", everyNMonthsNth: "everyNMCX${pn}",
                        time: "startingMC${pn}"],
            // Yearly is ALWAYS nth-weekday; yearlyMonthC<n> alone never completes,
            // so the month lives in yearlyMonthCX<n> (the X-suffixed reveal field).
            "Yearly":  [weekOfMonth: "weeklyYC${pn}", dayOfWeek: "dailyYC${pn}", monthEnum: "yearlyMonthCX${pn}", time: "startingYC${pn}"],
            "Cron String": [cron: "cronStr${pn}"]
        ]
        def fields = freqFieldMap.get(freq) ?: [:]
        // (Periodic arg validation -- Seconds/Minutes restricted-enum count and
        // the Monthly dayOfMonth/weekOfMonth mutual-exclusivity -- already ran
        // up front, before the trigger editor opened.)
        // Skip the entire periodic sub-page dance when the suffix-1 fallback
        // would clobber an earlier periodic trigger (see periodicUnsafeFallback).
        if (!periodicUnsafeFallback) {
        // Forward-nav into the periodic sub-page. Its return is intentionally NOT
        // folded into skipped: _rmNavigateToPage returns null on BOTH a POST failure
        // AND a non-JSON response (the latter is benign -- the caller plain-fetches),
        // so null is ambiguous here. A genuine nav failure surfaces deterministically
        // anyway via the writePeriodic persistence checks below (every field skips).
        //
        // BUG-9 (verified live 2026-06-03, app 1606): RM 5.1's OWN `periodic` page
        // method (ruleApp51, ~line 1576) logs a benign NullPointerException
        // ("Cannot get property 'n' on null object ... method periodic") against the
        // RULE app -- not ours (app 194) -- 2-3x while RM renders the periodic
        // sub-page during these interactions. It is RM-internal (RM doesn't null-
        // guard its own params.n on a render path) and NON-FATAL: the trigger bakes
        // cleanly (settingsApplied populated, health.ok). Our POSTs already carry n
        // via hrefParams; the noise is on RM's render, which we do not control. Do
        // NOT chase it into this fragile sub-page flow to silence RM's own log line.
        _rmNavigateToPage(appId, "selectTriggers", "periodic", periodicHrefIndex, periodicHrefName, hrefParams, null, null, false, true)
        // Closure that wraps _rmWriteSubPageField with applied/skipped routing
        // based on the helper's persistence verification (Map return). Use this
        // for every periodic-sub-page field write so silent rejections are
        // caught and surfaced rather than optimistically claimed as applied.
        def writePeriodic = { String fieldKey, Object fieldValue ->
            def wr = _rmWriteSubPageField(appId, "periodic", "selectTriggers", periodicHrefName, periodicHrefIndex, hrefParams, fieldKey, fieldValue)
            if (wr?.persisted) {
                applied << fieldKey
            } else if (wr?.verifyFetchFailed) {
                skipped << [key: fieldKey, reason: "verification_fetch_failed", value: fieldValue, verifyError: wr?.verifyError]
            } else {
                skipped << [key: fieldKey, reason: "silent_rejection", value: fieldValue, schemaUnchanged: true, available: wr?.afterKeys]
            }
        }
        // Write frequency first -- schema-progressive, so subsequent fields
        // only appear after this lands. whichPeriod<pn> is the per-trigger
        // mode selector (whichPeriod1 for the 1st periodic trigger).
        writePeriodic("whichPeriod${pn}".toString(), freq)
        if (freq == "Cron String") {
            // Cron String mode: just one text field.
            if (per.cronString != null && fields.cron) {
                writePeriodic(fields.cron, per.cronString.toString())
            }
        } else {
            // Seconds: single count enum, no toggle.
            if (per.everyN != null && fields.secondsCount) {
                writePeriodic(fields.secondsCount, per.everyN)
            }
            // everyN toggle + count (Minutes / Hourly / Daily). Order matters:
            // the toggle must land first because the count field only appears
            // (and only accepts a value) after the toggle is true. Writing the
            // count into the toggle field is the original "rendered null" bug.
            if (per.everyN != null && fields.everyNToggle) {
                writePeriodic(fields.everyNToggle, true)
                if (fields.everyNCount) {
                    writePeriodic(fields.everyNCount, per.everyN)
                }
            }
            // Daily-only: weekdaysOnly toggle.
            if (per.weekdaysOnly == true && fields.weekdayToggle) {
                writePeriodic(fields.weekdayToggle, true)
            }
            // nth-weekday mode (Monthly with weekOfMonth, OR Yearly which is
            // always nth-weekday). Writing the week-of-month field HIDES the
            // by-day fields and reveals the day-of-week + X-suffixed cadence/
            // month fields, so the by-day branch below must NOT also run.
            def nthWeekday = (freq == "Yearly") || monthlyNthWeekday
            if (nthWeekday) {
                if (per.weekOfMonth != null && fields.weekOfMonth) {
                    writePeriodic(fields.weekOfMonth, per.weekOfMonth)
                }
                // Single day-of-week enum (dailyMC<n> / dailyYC<n>). The dayOfWeek
                // alias is SINGULAR -- distinct from Weekly's daysOfWeek multi.
                if (per.dayOfWeek != null && fields.dayOfWeek) {
                    writePeriodic(fields.dayOfWeek, per.dayOfWeek)
                }
                // Monthly nth-weekday cadence is a FREE number in everyNMCX<n>
                // (NOT the by-day everyNMC<n>, and NOT the restricted enum).
                if (per.everyNMonths != null && fields.everyNMonthsNth) {
                    writePeriodic(fields.everyNMonthsNth, per.everyNMonths)
                }
                // Yearly nth-weekday month is a single enum in yearlyMonthCX<n>.
                if (per.months != null && fields.monthEnum) {
                    writePeriodic(fields.monthEnum, per.months)
                }
            } else {
                // by-day mode (Monthly without weekOfMonth). dayMC<n> + everyNMC<n>;
                // an incomplete combo (e.g. dayOfMonth without everyNMonths)
                // renders "null" -- documented in the arg shape.
                if (per.dayOfMonth != null && fields.dayOfMonth) {
                    writePeriodic(fields.dayOfMonth, per.dayOfMonth)
                }
                if (per.everyNMonths != null && fields.everyNMonths) {
                    writePeriodic(fields.everyNMonths, per.everyNMonths)
                }
            }
            // Multi-enum selection. Each frequency exposes ONE selectMulti
            // field but under a different alias; route the matching one.
            //   Hourly  selectedHours        -> selectHoursC<n>
            //   Daily   selectedDaysOfMonth  -> selectDoMC<n>
            //   Weekly  daysOfWeek           -> selectDoWC<n>
            //   Minutes selectedMinutes      -> selectMinutesC<n> (alt to everyN)
            // CONTRACT for the Elvis chain below: it relies on (a) each frequency
            // exposing AT MOST ONE selectMulti alias, so no two of these are set at
            // once, and (b) empty-list falsiness -- an empty [] for one alias falls
            // through to the next. If a future frequency exposes two multi-pickers,
            // this collapses them to one and must be reworked into per-frequency routing.
            def selectVals = per.selectedHours ?: per.selectedDaysOfMonth ?: per.daysOfWeek ?:
                             per.selectedMinutes
            if (selectVals != null && fields.selectMulti) {
                writePeriodic(fields.selectMulti, selectVals)
            }
            // Time field (startingHC<n> / startingDC<n> / startingWC<n> / ...).
            if (per.startingTime != null && fields.time) {
                writePeriodic(fields.time, per.startingTime.toString())
            }
            // Hourly-only: minute offset (when not using everyN).
            if (per.minutesOffset != null && fields.offset) {
                writePeriodic(fields.offset, per.minutesOffset)
            }
        }
        // Caller escape hatch for periodic-page fields not yet mapped above.
        if (per.rawSettings instanceof Map) {
            for (Map.Entry entry in (per.rawSettings as Map)) {
                def rk = entry.key
                def rv = entry.value
                writePeriodic(rk.toString(), rv)
            }
        }
        // Submit Done -- bakes the description into the trigger row. _rmSubmitSubPageDone
        // lets a Done-POST failure throw (so its other callers surface it as success:false);
        // here we catch it locally and fold it into skipped, because the periodic sub-page is
        // write-after-commit (the trigger row already exists) so a Done failure is a repairable
        // partial -- not the full success:false the abort-style callers want.
        try {
            _rmSubmitSubPageDone(appId, "periodic", "selectTriggers", periodicHrefName, hrefParams)
        } catch (Exception periodicDoneExc) {
            def doneErr = "${periodicDoneExc.class.simpleName}: ${periodicDoneExc.message}".toString()
            mcpLog("warn", "rm-native", "_rmAddTrigger: periodic sub-page Done submit failed for app ${appId} (in-flight trigger idx ${idx}) (${doneErr})")
            skipped << [key: "periodic", reason: "subpage_done_failed", value: freq,
                        note: "Periodic sub-page Done submit failed (${doneErr}); the trigger row description may not have baked. Verify via hub_get_app_config and re-add if the row shows '?'."]
        }
        } // end if (!periodicUnsafeFallback)
    }

    // Conditional-trigger binding MUST be written BEFORE hasAll while the
    // trigger-edit form is still open. Verified live: after hasAll,
    // selectTriggers' schema is empty (the wizard
    // returned to the trigger-list view, no edit fields exposed), so
    // condTrig.<idx> writes silently fail with available=[] (a hub-render
    // error pattern). The earlier comment claiming condTrig.<idx> only
    // appears AFTER hasAll was wrong.
    //
    // For conditional triggers, the live UI flow inside the trigger edit
    // form is:
    //   1. Toggle isCondTrig.<idx>=true → reveals condTrig.<idx> dropdown
    //   2. Set condTrig.<idx>=<conditionId> → picks which condition the
    //      trigger references (by condition's allocation id)
    //   3. Click hasAll to commit the trigger
    if (conditionSpec != null || triggerSpec.conditional == true) {
        // Pre-hasAll: bind the trigger to its condition while the edit
        // form is open. _rmWriteSettingOnPage no-ops if isCondTrig.<idx>
        // isn't yet in the schema, but in practice it's exposed as soon
        // as tCapab/tDev/tstate are written.
        _rmWriteSettingOnPage(appId, "selectTriggers", "isCondTrig.${idx}", true, applied, null, skipped)
        if (conditionId != null) {
            _rmWriteSettingOnPage(appId, "selectTriggers", "condTrig.${idx}", conditionId.toString(), applied, null, skipped)
        }
    }

    // Click hasAll (with form context) to commit.
    _rmClickAppButton(appId, "hasAll", null, "selectTriggers")

    // Post-hasAll finalize: for non-conditional triggers we need to write
    // isCondTrig.<idx>=false to close the residual "Conditional Trigger?"
    // prompt that RM exposes briefly after hasAll. Skip this for
    // conditional triggers — they already had isCondTrig.<idx>=true set
    // pre-hasAll, and writing false here would un-bind the condition.
    if (conditionSpec == null && triggerSpec.conditional != true) {
        try {
            _rmWriteSettingOnPage(appId, "selectTriggers", "isCondTrig.${idx}", false, applied, null, skipped)
        } catch (Exception finalizeExc) {
            mcpLog("debug", "rm-native", "_rmAddTrigger: post-hasAll isCondTrig.${idx}=false finalize failed for app ${appId} (${finalizeExc.message}) -- residual 'Conditional Trigger?' prompt may linger, can leave a phantom Broken Trigger N+1")
            // Best-effort: if the prompt isn't there (clean exit), the
            // schema check inside _rmWriteSettingOnPage skips it.
        }
    }

    // Navigate back to mainPage to commit the in-flight trigger.
    // Mirrors the action-wizard pattern (_rmAddAction navigates
    // doActPage→selectActions for the bake) — the live UI's "Done with
    // Triggers" button submits a form with `_action_href_name|mainPage|0`
    // that signals the page transition. This ensures trigger state is
    // fully baked before the next addTrigger call (or final updateRule).
    _rmNavigateToPage(appId, "selectTriggers", "mainPage", 0, "name", null, null, null, false, true)

    // Final config-error check.
    def finalConfig
    def verificationFetchFailed = false
    try { finalConfig = _rmFetchConfigJson(appId, "selectTriggers") }
    catch (Exception verifyExc) {
        finalConfig = null
        verificationFetchFailed = true
        mcpLog("warn", "rm-native", "_rmAddTrigger: post-commit selectTriggers fetch failed for app ${appId} (${verifyExc.message}) -- caller cannot verify the trigger baked, will mark response as verificationFetchFailed=true")
    }
    def err = finalConfig?.configPage?.error

    def health = _rmCheckRuleHealth(appId)

    // Post-commit silent-failure detection. RM 5.1's selectTriggers
    // silently accepts many invalid inputs at the field-write level —
    // bad state values, capability/state mismatches, unknown deviceIds —
    // without erroring. The trigger row may not bake at all, leaving
    // mainPage's "Define Triggers" placeholder. Without detection,
    // addTrigger would return success=true on a rule whose trigger
    // didn't actually commit. The hub isn't doing anything wrong —
    // it's permissive by design — but the LLM needs the signal so it
    // can self-correct. Verified: this check catches the
    // "expression silently didn't bake" class of failures that
    // configPageError + brokenMarkers don't catch.
    def triggerNotBaked = false
    try {
        def mainCfg = _rmFetchConfigJson(appId, "mainPage")
        // Read BOTH paragraph formats the hub emits. body-element format is used
        // by the live Hubitat UI renderer; paragraphs-array format appears in some
        // direct /configure/json responses. _rmCheckRuleHealth does the same dual-read
        // for its broken-marker scan, so detection works across both hub paths.
        def mainParagraphs = (mainCfg?.configPage?.sections ?: []).collectMany { sect ->
            def fromBody = (sect?.body ?: [])
                .findAll { b -> b instanceof Map && (b.element == "paragraph" || b.element == "href") }
                .collect { it.description?.toString() ?: "" }
            def fromParagraphs = (sect?.paragraphs ?: []).collect { it?.toString() ?: "" }
            fromBody + fromParagraphs
        }
        def joinedParagraphs = mainParagraphs.join("\n")
        // Placeholder-only state: paragraph says "Define Triggers" but no
        // trigger row exists. If a trigger row IS present, the placeholder
        // is replaced by the rendered trigger text.
        triggerNotBaked = joinedParagraphs.contains("Define Triggers")
    } catch (Exception verifyExc) {
        verificationFetchFailed = true
        mcpLog("warn", "rm-native", "_rmAddTrigger: post-commit mainPage paragraph fetch failed for app ${appId} (${verifyExc.message}) -- trigger-baked check skipped")
    }

    // Partial-success signal — see _rmAddAction for rationale. The trigger
    // is committed but a caller-requested field didn't land; LLM should
    // retry via hub_set_rule(walkStep) or rebuild the trigger row.
    // health.brokenMarkers non-empty means a PRIOR trigger is already broken;
    // the new trigger committed but the rule is in a known-bad state the
    // caller should address — surface as partial so the LLM sees it immediately.
    // Filter informational/cosmetic skips out of the skip-driven partial computation,
    // mirroring the exemption that _rmAddAction and _rmAddRequiredExpression apply via
    // _rmInformationalSkippedReasons(). Only the shared walker sentinels (e.g.
    // reveal_fallback_to_existing_field) are exempt by reason code -- a field the walker
    // matched after it was already visible is not a degraded write.
    // not_in_schema is NOT exempt as a reason code. Like silent_rejection it is GENUINE
    // degradation: a field the helper tried to write was absent from the live page schema, so
    // the value did not land. A state-change comparator such as '*changed*' is itself written
    // into the comparator field (ReltDev_<N>) as a value -- it is not an absent RHS -- so a
    // clean '*changed*' trigger does NOT skip its comparator. The only way the comparator (or
    // attribute, device, state) skips with not_in_schema is a real schema-timing failure where
    // the value never wrote, which must surface as partial rather than be masked. This matches
    // how the walker pages (STPage/doActPage) and _rmAddAction treat not_in_schema, and how
    // _rmModifyTrigger hard-throws on it.
    // The single narrow exception is the (isCondTrig.<N>, not_in_schema, value=false) tuple:
    // after the trigger commits, the helper writes isCondTrig.<N>=false best-effort to dismiss
    // the residual "Conditional Trigger?" prompt that RM only sometimes exposes post-hasAll. On
    // firmware/timing where the prompt already closed, that field is legitimately gone and the
    // write no-ops with not_in_schema -- a clean exit, not a lost trigger value. The value MUST
    // be false: the construction write isCondTrig.<N>=true (binding a conditional trigger to its
    // condition) is load-bearing, and a skip there means the trigger was not made conditional --
    // that must still flip partial. Exempt only that exact field+reason+value so a non-conditional
    // trigger does not spuriously report partial, while every other not_in_schema skip flips it.
    // triggerNotBaked and brokenMarkers flip partial independently below, so a genuinely
    // needed-but-missing field also surfaces via the not-baked check.
    def triggerInformationalReasons = _rmInformationalSkippedReasons()
    def genuineSkipped = (skipped ?: []).findAll {
        if (!(it instanceof Map) || it.reason == null) return true
        if (it.reason in triggerInformationalReasons) return false
        // The post-commit finalize toggle's absence (isCondTrig.<N>=false) is a clean exit, not
        // a degraded write. The =true construction write is load-bearing and is NOT exempt.
        if (it.reason == "not_in_schema" && it.key?.toString()?.matches(/isCondTrig\.\d+/) && it.value?.toString() == "false") return false
        return true
    }
    def partial = !genuineSkipped.isEmpty() || triggerNotBaked ||
                  ((health?.brokenMarkers as List)?.size() > 0)
    def hubRenderError = err != null || (genuineSkipped.any { it?.available != null && (it.available as List).isEmpty() } as Boolean) || triggerNotBaked
    def repairHints = []
    def hasBrokenLabel = health?.label?.toString()?.contains("*BROKEN*") as Boolean
    if (triggerNotBaked) {
        repairHints << "Trigger did not bake — mainPage still shows 'Define Triggers' placeholder. Common causes: state value not in capability's enum (e.g. 'on' is invalid for Motion which uses 'active'/'inactive'), capability/state mismatch, or unknown deviceIds. Verify state value matches the capability's domain (Switch: 'on'/'off'/'*changed*', Motion: 'active'/'inactive', Contact: 'open'/'closed', etc.) and run hub_list_devices to verify deviceIds. Then call removeAction or rebuild the rule."
    }
    if (partial || hasBrokenLabel) {
        // Name only genuinely-degraded fields (exclude the informational walker
        // sentinels) so the hint doesn't tell callers to repair a field that the
        // walker merely matched after it was already visible.
        // comparator_force_written_unverified is NOT a lost value: the comparator WAS
        // POSTed (it is in settingsApplied) but the exposure-probe re-fetch that would
        // confirm it failed transiently. Telling the caller it "didn't land" / to re-write
        // it would be wrong, so split those keys out into a verify-don't-rewrite hint.
        def forceWrittenKeys = genuineSkipped.findAll { it instanceof Map && it.reason == "comparator_force_written_unverified" }*.key.findAll { it != null }
        // Every reason here carries its OWN specific hint below, so exclude them from the
        // generic "didn't land -- introspect and re-write" hint -- that advice does not apply
        // and would mislead. comparator_force_written_unverified is written-but-unverified;
        // comparator_not_representable_for_enum_attribute is genuinely unrepresentable; the two
        // device-state state-change reasons (no matching picker option / unverifiable re-fetch)
        // are unrepresentable-or-unverified on the value-picker path -- following the generic
        // "write the missing tstate field" advice would send the caller to write a token the
        // picker rejected (a repair loop).
        def specificHintReasons = ["comparator_force_written_unverified", "comparator_not_representable_for_enum_attribute",
                                   "change_comparator_not_representable_for_device_state", "state_change_route_unverified_fetch_failed"]
        def lostSkipped = genuineSkipped.findAll { !(it instanceof Map && it.reason in specificHintReasons) }
        if (!lostSkipped.isEmpty()) {
            def skippedKeys = lostSkipped*.key.findAll { it != null }.join(', ')
            def settingWord = lostSkipped.size() == 1 ? "setting" : "settings"
            repairHints << "Some trigger ${settingWord} didn't land: ${skippedKeys}. Use hub_set_rule(walkStep={page:'selectTriggers', operation:'introspect'}) to see the live schema, then write the missing fields one at a time. CAVEAT: if the introspect call returns an empty schema for the missing field, that field is likely wizard-past-state (write-only during initial trigger construction, no longer in the live input list). Verify via hub_get_app_config(appId) -- if the trigger paragraph renders the value correctly (e.g. 'Certain Time 5:30 PM'), the partial flag is cosmetic and the trigger is fully baked. Skip the repair."
        }
        if (!forceWrittenKeys.isEmpty()) {
            def cmpWord = forceWrittenKeys.size() == 1 ? "Comparator" : "Comparators"
            def cmpVerb = forceWrittenKeys.size() == 1 ? "was" : "were"
            repairHints << "${cmpWord} ${forceWrittenKeys.join(', ')} ${cmpVerb} force-written via a degraded path after a transient re-fetch failure -- the value IS in settingsApplied and success stays true, but it could not be schema-confirmed. Verify via hub_get_app_config(appId): if the trigger paragraph renders the comparator correctly, the partial flag is cosmetic. Do NOT re-write -- only re-add via hub_set_rule(walkStep={...}) if the paragraph shows the comparator missing."
        }
        def notRepresentable = genuineSkipped.findAll { it instanceof Map && it.reason == "comparator_not_representable_for_enum_attribute" }
        for (sk in notRepresentable) {
            repairHints << _rmNotRepresentableEnumComparatorHint(
                (sk instanceof Map ? sk.attribute : null), (sk instanceof Map ? sk.value : null))
        }
        // Device-state change-comparator skips (no matching picker option, or an unverifiable
        // re-fetch) carry their own precise walkStep hint on the skip -- surface it directly so
        // the caller gets the accurate device-state repair path, not the generic one above.
        genuineSkipped.findAll { it instanceof Map &&
                (it.reason == "change_comparator_not_representable_for_device_state" || it.reason == "state_change_route_unverified_fetch_failed") }.each { sk ->
            if (sk.hint) repairHints << sk.hint.toString()
        }
        if (hasBrokenLabel) {
            repairHints << "Trigger row has *BROKEN* marker -- capability '${cap}' likely needs a capability-specific field (Mode: pass state='ModeName' or modeIds=['id'], NOT rawSettings.tstate; Periodic: pass periodic={} sub-spec). Re-add the trigger with the correct fields."
        }
        if ((health?.brokenMarkers as List)?.size() > 0 && !hasBrokenLabel) {
            repairHints << "Rule has pre-existing broken markers: ${(health.brokenMarkers as List).unique().join(', ')}. The new trigger committed, but run hub_get_rule_health(${appId}) and repair the existing broken trigger/action rows before this rule fires correctly."
        }
        if (skipped?.any { it?.reason == "periodic_href_unresolved_nonfirst_trigger" }) {
            repairHints << "The periodic sub-page index could not be resolved for this (non-first) trigger -- its href was absent from the trigger schema, or the href's params.n was malformed -- so its schedule was NOT written, because writing it would have overwritten an earlier periodic trigger's schedule. Retry the add: re-fetch with hub_set_rule(walkStep={page:'selectTriggers', operation:'introspect'}) to confirm the periodic href is present with an integer params.n, or rebuild the rule's triggers in order. If the rule has only one periodic trigger, this should not recur."
        }
        if (hubRenderError) {
            repairHints << "WARNING: selectTriggers may have rendered with an error (configPageError=${err}, or skipped items have empty available list). This is a hub-side issue. Consider deleting the trigger and trying with different deviceIds or trigger shape."
        }
    }
    // success=true when: the API call completed without an error AND at least
    // one setting was written to the rule (meaning the trigger skeleton
    // exists). partial=true is an orthogonal caller-actionable signal -- the
    // row exists but needs repair. Using !applied.isEmpty() rather than
    // !partial || !hasBrokenLabel means we no longer conflate "row needs
    // repair" with "the operation failed outright". Callers check success
    // for "did anything happen" then partial for "is more work needed."
    def result = [
        success: !err && !applied.isEmpty(),
        partial: partial || hasBrokenLabel,
        hubRenderError: hubRenderError,
        triggerIndex: idx,
        capability: cap,
        settingsApplied: applied,
        settingsSkipped: skipped,
        configPageError: err,
        repairHints: repairHints,
        health: health,
        verificationFetchFailed: verificationFetchFailed
    ]
    if (conditionId != null) result.conditionId = conditionId
    return result
    }
    return _impl()
}

// Return a structured schema Map describing every supported addTrigger capability.
// Called when addTrigger: {discover: true} is passed -- no hub mutation, no
// confirm/backup required. Content is sourced from the inline capability-family
// reference in the hub_set_rule tool description.
private Map _rmTriggerSchemaForDiscover() {
    return [
        discriminator: "capability",
        note: "Pass the chosen capability name (case-insensitive) as addTrigger.capability in the real call.",
        conditionFields: [
            [name: "not", type: "Boolean", description: "Applies inside a CONDITION list only (addTrigger.condition, addRequiredExpression.conditions[], addAction expression conditions[]) -- NOT the trigger row itself. not:true negates the condition (e.g. Time NOT between, mode is NOT Night, does-not-contain via not:true + comparator:'*contains*')."]
        ],
        capabilities: [
            [
                name: "Switch",
                family: "device-state",
                requiredFields: [
                    [name: "deviceIds", type: "List<Integer>", description: "Switch device IDs"],
                    [name: "state", type: "enum", values: ["on", "off"], description: "Trigger condition"]
                ],
                optionalFields: [
                    [name: "allOfThese", type: "Boolean", description: "Require ALL selected devices to match (vs. any one)"],
                    [name: "andStays", type: "Map", description: "{hours?, minutes?, seconds?} -- only fire after state has held this long"],
                    [name: "conditional", type: "Boolean", description: "Make this a conditional trigger (sets isCondTrig)"],
                    [name: "condition", type: "Map", description: "Inline conditional-trigger gate -- same per-condition shape as addRequiredExpression conditions[]"],
                    [name: "rawSettings", type: "Map", description: "Escape hatch for fields not yet mapped"]
                ]
            ],
            [
                name: "Motion",
                family: "device-state",
                requiredFields: [
                    [name: "deviceIds", type: "List<Integer>", description: "Motion sensor device IDs"],
                    [name: "state", type: "enum", values: ["active", "inactive"], description: "Trigger condition"]
                ],
                optionalFields: [
                    [name: "allOfThese", type: "Boolean", description: "Require ALL selected devices to match"],
                    [name: "andStays", type: "Map", description: "{hours?, minutes?, seconds?}"],
                    [name: "conditional", type: "Boolean"],
                    [name: "condition", type: "Map"],
                    [name: "rawSettings", type: "Map"]
                ]
            ],
            [
                name: "Contact",
                family: "device-state",
                requiredFields: [
                    [name: "deviceIds", type: "List<Integer>", description: "Contact sensor device IDs"],
                    [name: "state", type: "enum", values: ["open", "closed"], description: "Trigger condition"]
                ],
                optionalFields: [
                    [name: "allOfThese", type: "Boolean"],
                    [name: "andStays", type: "Map", description: "{hours?, minutes?, seconds?}"],
                    [name: "conditional", type: "Boolean"],
                    [name: "condition", type: "Map"],
                    [name: "rawSettings", type: "Map"]
                ]
            ],
            [
                name: "Lock",
                family: "device-state",
                requiredFields: [
                    [name: "deviceIds", type: "List<Integer>", description: "Lock device IDs"],
                    [name: "state", type: "enum", values: ["locked", "unlocked"], description: "Trigger condition"]
                ],
                optionalFields: [
                    [name: "allOfThese", type: "Boolean"],
                    [name: "andStays", type: "Map", description: "{hours?, minutes?, seconds?}"],
                    [name: "conditional", type: "Boolean"],
                    [name: "condition", type: "Map"],
                    [name: "rawSettings", type: "Map"]
                ]
            ],
            [
                name: "Presence",
                family: "device-state",
                requiredFields: [
                    [name: "deviceIds", type: "List<Integer>", description: "Presence sensor device IDs"],
                    [name: "state", type: "enum", values: ["present", "not present"], description: "Trigger condition"]
                ],
                optionalFields: [
                    [name: "allOfThese", type: "Boolean"],
                    [name: "andStays", type: "Map", description: "{hours?, minutes?, seconds?}"],
                    [name: "conditional", type: "Boolean"],
                    [name: "condition", type: "Map"],
                    [name: "rawSettings", type: "Map"]
                ]
            ],
            [
                name: "Garage",
                family: "device-state",
                aliases: ["Door", "Valve", "Window Shade"],
                notes: "Also covers Door, Valve, Window Shade -- pass any of these names as capability; use appropriate state values for each device type.",
                requiredFields: [
                    [name: "deviceIds", type: "List<Integer>"],
                    [name: "state", type: "enum", values: ["open", "closed"], description: "Trigger condition"]
                ],
                optionalFields: [
                    [name: "allOfThese", type: "Boolean"],
                    [name: "andStays", type: "Map"],
                    [name: "rawSettings", type: "Map"]
                ]
            ],
            [
                name: "Power source",
                family: "device-state",
                requiredFields: [
                    [name: "deviceIds", type: "List<Integer>"],
                    [name: "state", type: "enum", values: ["battery", "dc", "mains", "unknown"], description: "Trigger condition"]
                ],
                optionalFields: [
                    [name: "allOfThese", type: "Boolean"],
                    [name: "andStays", type: "Map"],
                    [name: "rawSettings", type: "Map"]
                ]
            ],
            [
                name: "Temperature",
                family: "numeric",
